"use strict";(self.webpackChunkrapid_docs_2=self.webpackChunkrapid_docs_2||[]).push([[23361],{34782:e=>{e.exports=JSON.parse('{"archive":{"blogPosts":[{"id":"/2026/09/21/2026-09-21-1.67 - Rapid Platform/1.67 - Rapid Platform","metadata":{"permalink":"/changelog/2026/09/21/2026-09-21-1.67 - Rapid Platform/1.67 - Rapid Platform","source":"@site/blog/2026-09-21-1.67 - Rapid Platform/2026-09-21-1.67 - Rapid Platform.md","title":"v1.67 \u2014 Rapid Platform","description":"We\'re excited to announce new features live on Rapid Platform Monday, September 28th","date":"2026-09-21T00:00:00.000Z","tags":[{"inline":true,"label":"Changelog","permalink":"/changelog/tags/changelog"}],"readingTime":2.71,"hasTruncateMarker":false,"authors":[{"name":"Danny Rattu","title":"Documents","url":"https://github.com/DannyRattu","email":"danny.rattu@rapidplatform.com","imageURL":"https://github.com/DannyRattu.png","key":"danny","page":null}],"frontMatter":{"authors":["danny"],"tags":["Changelog"]},"unlisted":false,"nextItem":{"title":"v1.66 \u2014 Rapid Platform","permalink":"/changelog/2026/07/31/2026-07-31-1.66 - Rapid Platform/1.66 - Rapid Platform"}},"content":"We\'re excited to announce new features live on Rapid Platform **Monday, September 28th**\\n\\n## Features\\n\\n### Permission inheritance\\n\\nItems can now inherit their permissions from a parent record. In Designer, the Permission Inheritance section of a table\'s Security & Permissions tab lets you choose the parent using a lookup or universal link column, and system lists and tables that extend another table can inherit too. New items take on their parent\'s permissions when they\'re created, and any change to the parent\'s permissions flows down through every level of child items. You can also choose whether a table\'s items share its default permissions or have their own, and restore a record to its table\'s default inheritance at any time.\\n\\n### Permissions admin page\\n\\nA new Permissions admin page under Maintenance in Designer shows which items have permissions that differ from their table\'s defaults. From here you can reset items to their defaults, bulk apply permissions to items matching a filter, or bulk set items to inherit from their parent. Every bulk change is previewed before it\'s applied. You can also see exactly who can access an item and where that access comes from, or pick a user or group to see everything they can access.\\n\\n### SharePoint permission sync in the background\\n\\nSharePoint permissions now sync in the background whenever an item is created or updated, so saving is no longer slowed down by the sync. Folder permissions follow the same inheritance as their items, and drift is detected and repaired automatically. Admins can track queued, completed and failed syncs in the new Permission Sync Events list.\\n\\n### Stronger Designer and Workflow permissions\\n\\nThe Designer and Workflow permissions are now enforced across the API, not just in the UI. Any user, integration or AI agent without the Designer permission can no longer change a site\'s structure, such as its tables, fields, views, menus and pages, and workflow administration requires the Workflow permission. Tables that extend another table are now protected by their own permissions, so a user with access to a base table can\'t read the extra fields on a table they haven\'t been granted.\\n\\n## Improvements\\n\\n* You\'ll now see a confirmation, showing where an item\'s permissions come from, before breaking its permission inheritance\\n* Permission errors from Designer and Workflow are now shown instead of failing silently\\n* Searching in the principal picker is no longer case-sensitive\\n* Full principal names are now shown in the permission picker and table\\n* You can no longer save an empty set of permissions\\n* Pages now show an empty state when none of their tabs are visible to you\\n* Installing a bundle now checks its tables first and names any invalid table, instead of installing it partially\\n\\n## Bug Fixes\\n\\n* Fixed an issue where notes created from the Activity Feed didn\'t inherit permissions from the record they were linked to\\n* Fixed an issue where removing a table that extends another table failed with a SQL error\\n* Fixed an issue where submitting a long public form could fail\\n* Fixed an issue where public forms failed to load on sites containing a table installed from a bundle without settings\\n* Fixed an issue where pages failed to load when their search state contained a dot\\n* Fixed an issue where the Creating document notification in Adaptive Designer never cleared"},{"id":"/2026/07/31/2026-07-31-1.66 - Rapid Platform/1.66 - Rapid Platform","metadata":{"permalink":"/changelog/2026/07/31/2026-07-31-1.66 - Rapid Platform/1.66 - Rapid Platform","source":"@site/blog/2026-07-31-1.66 - Rapid Platform/2026-07-31-1.66 - Rapid Platform.md","title":"v1.66 \u2014 Rapid Platform","description":"We\'re excited to announce new improvements live on Rapid Platform Friday, July 31st","date":"2026-07-31T00:00:00.000Z","tags":[{"inline":true,"label":"Changelog","permalink":"/changelog/tags/changelog"}],"readingTime":0.44,"hasTruncateMarker":false,"authors":[{"name":"Danny Rattu","title":"Documents","url":"https://github.com/DannyRattu","email":"danny.rattu@rapidplatform.com","imageURL":"https://github.com/DannyRattu.png","key":"danny","page":null}],"frontMatter":{"authors":["danny"],"tags":["Changelog"]},"unlisted":false,"prevItem":{"title":"v1.67 \u2014 Rapid Platform","permalink":"/changelog/2026/09/21/2026-09-21-1.67 - Rapid Platform/1.67 - Rapid Platform"},"nextItem":{"title":"v1.65 \u2014 Rapid Platform","permalink":"/changelog/2026/07/06/2026-07-06-1.65 - Rapid Platform/1.65 - Rapid Platform"}},"content":"We\'re excited to announce new improvements live on Rapid Platform **Friday, July 31st**\\n\\n## Bug Fixes\\n\\n* Fixed an issue where CSV exports could return rows in an inconsistent order across pages\\n* Fixed an issue where searching in a lookup didn\'t respect cascading lookup filters\\n* Fixed an issue where fetch connectors in Adaptive Documents could fail after saving progress and reloading the form\\n* Fixed an issue where edits to existing records weren\'t saved when syncing data from a workbook\\n* Fixed an issue where the Gantt component failed to load"},{"id":"/2026/07/06/2026-07-06-1.65 - Rapid Platform/1.65 - Rapid Platform","metadata":{"permalink":"/changelog/2026/07/06/2026-07-06-1.65 - Rapid Platform/1.65 - Rapid Platform","source":"@site/blog/2026-07-06-1.65 - Rapid Platform/2026-07-06-1.65 - Rapid Platform.md","title":"v1.65 \u2014 Rapid Platform","description":"We\'re excited to announce new improvements live on Rapid Platform Monday, July 6th","date":"2026-07-06T00:00:00.000Z","tags":[{"inline":true,"label":"Changelog","permalink":"/changelog/tags/changelog"}],"readingTime":0.54,"hasTruncateMarker":false,"authors":[{"name":"Danny Rattu","title":"Documents","url":"https://github.com/DannyRattu","email":"danny.rattu@rapidplatform.com","imageURL":"https://github.com/DannyRattu.png","key":"danny","page":null}],"frontMatter":{"authors":["danny"],"tags":["Changelog"]},"unlisted":false,"prevItem":{"title":"v1.66 \u2014 Rapid Platform","permalink":"/changelog/2026/07/31/2026-07-31-1.66 - Rapid Platform/1.66 - Rapid Platform"},"nextItem":{"title":"v1.64 \u2014 Rapid Platform","permalink":"/changelog/2026/06/23/2026-06-23-1.64 - Rapid Platform/1.64 - Rapid Platform"}},"content":"We\'re excited to announce new improvements live on Rapid Platform **Monday, July 6th**\\n\\n## Improvements\\n\\n* The Activity Feed now supports emails saved in the modern Outlook .msg format\\n* Field description tooltips now stay on screen on mobile devices\\n\\n## Bug Fixes\\n\\n* Fixed an issue where only the last file was saved when uploading multiple files with the same name to an Embedded File component on a public form, such as when taking several photos on mobile\\n* Fixed an issue where Adaptive Documents set to fetch on load cleared their prefilled values when there was no item to fetch\\n* Fixed an issue where Adaptive Designer crashed when switching between large documents"},{"id":"/2026/06/23/2026-06-23-1.64 - Rapid Platform/1.64 - Rapid Platform","metadata":{"permalink":"/changelog/2026/06/23/2026-06-23-1.64 - Rapid Platform/1.64 - Rapid Platform","source":"@site/blog/2026-06-23-1.64 - Rapid Platform/2026-06-23-1.64 - Rapid Platform.md","title":"v1.64 \u2014 Rapid Platform","description":"We\'re excited to announce new features live on Rapid Platform Tuesday, June 23rd","date":"2026-06-23T00:00:00.000Z","tags":[{"inline":true,"label":"Changelog","permalink":"/changelog/tags/changelog"}],"readingTime":1.89,"hasTruncateMarker":false,"authors":[{"name":"Danny Rattu","title":"Documents","url":"https://github.com/DannyRattu","email":"danny.rattu@rapidplatform.com","imageURL":"https://github.com/DannyRattu.png","key":"danny","page":null}],"frontMatter":{"authors":["danny"],"tags":["Changelog"]},"unlisted":false,"prevItem":{"title":"v1.65 \u2014 Rapid Platform","permalink":"/changelog/2026/07/06/2026-07-06-1.65 - Rapid Platform/1.65 - Rapid Platform"},"nextItem":{"title":"v1.62 \u2014 Rapid Platform","permalink":"/changelog/2026/04/13/2026-04-13-1.62 - Rapid Platform/1.62 - Rapid Platform"}},"content":"We\'re excited to announce new features live on Rapid Platform **Tuesday, June 23rd**\\n\\n## Features\\n\\n### Experiences are now Workspaces\\n\\nExperiences have been renamed to Workspaces throughout the platform, including labels, routes and search. You can now link a menu item to a Workspace, which displays that Workspace\'s full menu as nested children. Any changes made to the linked Workspace\'s menu are reflected automatically, without needing to re-save the menu that links to it.\\n\\n### Tab permissions\\n\\nYou can now limit which tabs in a Tab Strip are visible to specific users or groups. Tabs a user doesn\'t have access to are hidden when they view the page, while all tabs remain visible when editing the Tab Strip in Designer.\\n\\n### Wait for all Inclusive Gateway paths\\n\\nInclusive Gateways in Workflow can now wait for the outcomes of all active paths before the process continues. This is useful for scenarios such as onboarding, where a user may be provisioned to several systems and the process can\'t proceed until every system has been provisioned.\\n\\n### Application principals\\n\\nWe\'ve added a new principal type for applications. Application principals respect permissions in the same way as users and groups, so integrations can be given only the access they need.\\n\\n## Improvements\\n\\n* Added a New View button to the menu in Designer\\n* Added an Open in Adaptive Designer button to User Tasks in Workflow\\n* Creating a new table now lets you choose whether it\'s added to the sidebar menu\\n* The Get Rapid Item service task now shows a clear error when the target list or item can\'t be found\\n* Links in the External Page component that open a new tab or navigate the parent page now work\\n\\n## Bug Fixes\\n\\n* Fixed an issue where CSV exports could be missing rows\\n* Fixed an issue where copying an expression from a labelled Workflow element copied the label instead of the reference\\n* Fixed an issue where deleting a condition watcher in Adaptive Designer left its expression behind\\n* Fixed an issue where cascading lookups crashed the page when the linked list had no title field\\n* Fixed an issue where large uploads failed because of a field size limit\\n* Fixed an issue where document introspection in DocX templates stopped working\\n* Addressed styling issues with the public form URL in the state menu"},{"id":"/2026/04/13/2026-04-13-1.62 - Rapid Platform/1.62 - Rapid Platform","metadata":{"permalink":"/changelog/2026/04/13/2026-04-13-1.62 - Rapid Platform/1.62 - Rapid Platform","source":"@site/blog/2026-04-13-1.62 - Rapid Platform/2026-04-13-1.62 - Rapid Platform.md","title":"v1.62 \u2014 Rapid Platform","description":"We\'re excited to announce new features live on Rapid Platform Tuesday, April 28th","date":"2026-04-13T00:00:00.000Z","tags":[{"inline":true,"label":"Changelog","permalink":"/changelog/tags/changelog"}],"readingTime":0.68,"hasTruncateMarker":false,"authors":[{"name":"Joshua Nauer","title":"Documents","url":"https://github.com/decept1kon","email":"sales@rapidplatform.com","imageURL":"https://github.com/decept1kon.png","key":"josh","page":null}],"frontMatter":{"authors":["josh"],"tags":["Changelog"]},"unlisted":false,"prevItem":{"title":"v1.64 \u2014 Rapid Platform","permalink":"/changelog/2026/06/23/2026-06-23-1.64 - Rapid Platform/1.64 - Rapid Platform"},"nextItem":{"title":"v1.60.11 \u2014 Rapid Platform","permalink":"/changelog/2026/03/26/2026-03-26-1.60.11 - Rapid Platform/1.60.11 - Rapid Platform"}},"content":"We\'re excited to announce new features live on Rapid Platform **Tuesday, April 28th**\\n\\n## Improvements\\n\\n* You\u2019ll now see a confirmation dialog when deleting an Adaptive Document in Adaptive Designer\\n\\n## Bug Fixes\\n\\n* Fixed an issue where the warning icon was displayed on Send Email service tasks despite valid From field configuration\\n* Fixed an issue where default values exceeded the configured maximum length for Single Line of Text columns\\n* Removed the Required toggle from Embedded File slots within User Tasks in Workflow\\n* Fixed an issue where Adaptive Documents appeared on unrelated User Tasks when no documents were configured\\n* Fixed an issue where Choice fields configured as radio buttons displayed an additional blank option\\n* Addressed styling issues with the Open Document dialog in Adaptive Designer\\n* Fixed an issue where the `{~~html}` template caused a crash in Fill Document service tasks"},{"id":"/2026/03/26/2026-03-26-1.60.11 - Rapid Platform/1.60.11 - Rapid Platform","metadata":{"permalink":"/changelog/2026/03/26/2026-03-26-1.60.11 - Rapid Platform/1.60.11 - Rapid Platform","source":"@site/blog/2026-03-26-1.60.11 - Rapid Platform/2026-03-26-1.60.11 - Rapid Platform.md","title":"v1.60.11 \u2014 Rapid Platform","description":"We\'re excited to announce new features live on Rapid Platform Monday, March 30th","date":"2026-03-26T00:00:00.000Z","tags":[{"inline":true,"label":"Changelog","permalink":"/changelog/tags/changelog"}],"readingTime":1.22,"hasTruncateMarker":false,"authors":[{"name":"Joshua Nauer","title":"Documents","url":"https://github.com/decept1kon","email":"sales@rapidplatform.com","imageURL":"https://github.com/decept1kon.png","key":"josh","page":null}],"frontMatter":{"authors":["josh"],"tags":["Changelog"]},"unlisted":false,"prevItem":{"title":"v1.62 \u2014 Rapid Platform","permalink":"/changelog/2026/04/13/2026-04-13-1.62 - Rapid Platform/1.62 - Rapid Platform"},"nextItem":{"title":"v1.60.8 \u2014 Rapid Platform","permalink":"/changelog/2026/03/02/2026-03-02-1.60.7 - Rapid Platform/1.60.7 - Rapid Platform"}},"content":"We\'re excited to announce new features live on Rapid Platform **Monday, March 30th**\\n\\n## Features\\n\\n### Folder nesting under a parent table\\n\\nYou can now organise item folders under a parent table in document storage. Choose whether items link to the parent using a lookup or universal link, and whether folders are shared or created per item, keeping documents grouped automatically. [Learn more about Folder Nesting](/docs/folder-nesting)\\n\\n![Folder nesting enabled showing configuration](FolderNesting.png)\\n\\n## Improvements\\n\\n* You\u2019ll now see a warning if you try to leave a table with unsaved changes\\n\\n## Bug Fixes\\n\\n* Fixed an issue where split value choice fields appeared blank on public forms\\n* Fixed the Vertical Layout component crashing when added to a page\\n* Fixed an issue where invalid queries could be saved on Computed and Subquery columns\\n* Fixed an issue where field bindings couldn\u2019t be cleared on the Address component in Designer\\n* Fixed an issue where deleted notifications still appeared in the notifications list\\n* Fixed an issue where deleting subtypes of tables with names starting with numbers caused SQL errors\\n* Fixed an issue where mentions in the Activity Feed didn\u2019t trigger notifications\\n* Fixed an issue where address fields in submitted forms didn\u2019t populate their mapped fields\\n* Fixed an issue where copying and pasting a timer event had no effect\\n* Fixed an issue where using `thisElement` in a Lodash expression returned no value\\n* Fixed an issue where signing in with only an OID did not sync user details to the Principal record"},{"id":"/2026/03/02/2026-03-02-1.60.7 - Rapid Platform/1.60.7 - Rapid Platform","metadata":{"permalink":"/changelog/2026/03/02/2026-03-02-1.60.7 - Rapid Platform/1.60.7 - Rapid Platform","source":"@site/blog/2026-03-02-1.60.7 - Rapid Platform/2026-03-02-1.60.7 - Rapid Platform.md","title":"v1.60.8 \u2014 Rapid Platform","description":"We\'re excited to announce new improvements live on Rapid Platform Monday March 3rd!","date":"2026-03-02T00:00:00.000Z","tags":[{"inline":true,"label":"Changelog","permalink":"/changelog/tags/changelog"}],"readingTime":0.3,"hasTruncateMarker":false,"authors":[{"name":"Joshua Nauer","title":"Documents","url":"https://github.com/decept1kon","email":"sales@rapidplatform.com","imageURL":"https://github.com/decept1kon.png","key":"josh","page":null}],"frontMatter":{"authors":["josh"],"tags":["Changelog"]},"unlisted":false,"prevItem":{"title":"v1.60.11 \u2014 Rapid Platform","permalink":"/changelog/2026/03/26/2026-03-26-1.60.11 - Rapid Platform/1.60.11 - Rapid Platform"},"nextItem":{"title":"1.60.0 - Rapid Platform","permalink":"/changelog/2026/01/05/2026-01-05-1.60.0 - Rapid Platform/1.60.0 - Rapid Platform"}},"content":"We\'re excited to announce new improvements live on Rapid Platform Monday March 3rd!\\n\\n## Improvements\\n* Added city and district selection to the Address component.\\n\\n## Bug Fixes\\n* Check that accounts are enabled before inviting users to SharePoint folders.\\n* Disabled pagination when searching within a data table to prevent infinite network calls.\\n* Prevented network calls on keypress when using the Address component."},{"id":"/2026/01/05/2026-01-05-1.60.0 - Rapid Platform/1.60.0 - Rapid Platform","metadata":{"permalink":"/changelog/2026/01/05/2026-01-05-1.60.0 - Rapid Platform/1.60.0 - Rapid Platform","source":"@site/blog/2026-01-05-1.60.0 - Rapid Platform/2026-01-05-1.60.0 - Rapid Platform.md","title":"1.60.0 - Rapid Platform","description":"Release Date: 05/01/26","date":"2026-01-05T00:00:00.000Z","tags":[{"inline":true,"label":"Changelog","permalink":"/changelog/tags/changelog"}],"readingTime":1.2,"hasTruncateMarker":false,"authors":[{"name":"Joshua Nauer","title":"Documents","url":"https://github.com/decept1kon","email":"sales@rapidplatform.com","imageURL":"https://github.com/decept1kon.png","key":"josh","page":null}],"frontMatter":{"authors":["josh"],"tags":["Changelog"]},"unlisted":false,"prevItem":{"title":"v1.60.8 \u2014 Rapid Platform","permalink":"/changelog/2026/03/02/2026-03-02-1.60.7 - Rapid Platform/1.60.7 - Rapid Platform"},"nextItem":{"title":"1.58.0 - Rapid Platform","permalink":"/changelog/2025/12/15/2025-12-15-1.58.0 - Rapid Platform/1.58.0 - Rapid Platform"}},"content":"**Release Date:** 05/01/26\\n\\n# 1.60.0 Rapid Platform\\n\\n## Features\\n\\n### Map Location Fields\\n\\nWe would like to introduce a new field type for Rapid lists, Geography. These fields can store the Latitude and Longitude of a location.\\n\\nAdding the fields to a page will now present the map location stored. Clicking a location will set it as required.\\n\\n![Location field showing a map and a point](location.png)\\n\\nFor the report writers out there, these are stored as Geography fields using [WKT POINT](https://learn.microsoft.com/en-us/sql/t-sql/spatial-geometry/stmpointfromwkb-geometry-data-type?view=sql-server-ver17) format.\\nFor those of you interested in getting these points into PowerBI you will need to cast them for the built-in Map visual. For example:\\n\\n```sql\\nSELECT id\\n ,title\\n ,CAST(geo_field.Lat as FLOAT) \'Lat\', CAST(geo_field.Long as FLOAT) \'Long\'\\nFROM dbo.geo_list\\n```\\n\\n\\n## Improvements\\n- Creating a new process via upload will now pre-fill the title\\n- Altering permissions on items now requires at minimum edit permission to perform\\n- Permissions synced to SharePoint will now expand the groups and create individual permissions where required\\n- Updated Support chat-bot to new long-term model for better speed\\n\\n## Bug Fixes\\n- Execute workflow menu actions that contain inputs with a lookup to the current item will no longer crash on submission\\n- Recovered Ctrl+Enter shortcut to submit Activity Feeds notes, as it was just adding a new line before\\n- Support chat bot can answer your queries again"},{"id":"/2025/12/15/2025-12-15-1.58.0 - Rapid Platform/1.58.0 - Rapid Platform","metadata":{"permalink":"/changelog/2025/12/15/2025-12-15-1.58.0 - Rapid Platform/1.58.0 - Rapid Platform","source":"@site/blog/2025-12-15-1.58.0 - Rapid Platform/2025-12-15-1.58.0 - Rapid Platform.md","title":"1.58.0 - Rapid Platform","description":"Release Date: 15/12/25","date":"2025-12-15T00:00:00.000Z","tags":[{"inline":true,"label":"Changelog","permalink":"/changelog/tags/changelog"}],"readingTime":0.52,"hasTruncateMarker":false,"authors":[{"name":"Joshua Nauer","title":"Documents","url":"https://github.com/decept1kon","email":"sales@rapidplatform.com","imageURL":"https://github.com/decept1kon.png","key":"josh","page":null}],"frontMatter":{"authors":["josh"],"tags":["Changelog"]},"unlisted":false,"prevItem":{"title":"1.60.0 - Rapid Platform","permalink":"/changelog/2026/01/05/2026-01-05-1.60.0 - Rapid Platform/1.60.0 - Rapid Platform"},"nextItem":{"title":"1.57.0 - Rapid Platform","permalink":"/changelog/2025/11/10/2025-11-10-1.57.0 - Rapid Platform/1.57.0 - Rapid Platform"}},"content":"**Release Date:** 15/12/25\\n\\n# 1.58.0 Rapid Platform\\n\\nWe\'re excited to announce new improvements live on Rapid Platform **Monday December 15th**!\\n\\n---\\n\\n# Improvements\\n\\n- Workflow timers will now reply instantly, preventing long running process steps from being duplicated\\n- Inline styles and other HTML sanitisation has been standardised across the platform, you should be able to use a wider range of safe HTML elements in rich text\\n\\n\\n# Bug Fixes\\n\\n- Prevented public forms from being able to save their \'saving\' state if they fail to finish saving while submitting\\n- Updated Embedded file component in Public forms to correctly load their embedded file definition in single item scenarios"},{"id":"/2025/11/10/2025-11-10-1.57.0 - Rapid Platform/1.57.0 - Rapid Platform","metadata":{"permalink":"/changelog/2025/11/10/2025-11-10-1.57.0 - Rapid Platform/1.57.0 - Rapid Platform","source":"@site/blog/2025-11-10-1.57.0 - Rapid Platform/2025-11-10-1.57.0 - Rapid Platform.md","title":"1.57.0 - Rapid Platform","description":"Release Date: 10/11/25","date":"2025-11-10T00:00:00.000Z","tags":[{"inline":true,"label":"Changelog","permalink":"/changelog/tags/changelog"}],"readingTime":0.88,"hasTruncateMarker":false,"authors":[{"name":"Joshua Nauer","title":"Documents","url":"https://github.com/decept1kon","email":"sales@rapidplatform.com","imageURL":"https://github.com/decept1kon.png","key":"josh","page":null}],"frontMatter":{"authors":["josh"],"tags":["Changelog"]},"unlisted":false,"prevItem":{"title":"1.58.0 - Rapid Platform","permalink":"/changelog/2025/12/15/2025-12-15-1.58.0 - Rapid Platform/1.58.0 - Rapid Platform"},"nextItem":{"title":"1.56.3 - Rapid Platform","permalink":"/changelog/2025/10/13/2025-10-13-1.56.3 - Rapid Platform/1.56.3 - Rapid Platform"}},"content":"**Release Date:** 10/11/25\\n\\n# 1.57.0 Rapid Platform\\n\\nWe\'re excited to announce new features live on Rapid Platform **Monday November 10th**!\\n\\n---\\n\\n## Split values to choice and radio controls in Adaptive\\n\\nWe\'ve introduced the ability to assign split values to adaptive radio buttons and choices, enabling users to define a value that differs from the displayed label. This is particularly useful in scenarios where descriptive labels are used for user input, but numerical values are needed for backend processing or analysis. Users can now click the link icon when editing a choice or radio option to separate the label from its value, allowing them to store meaningful data directly without relying on post-submission conversion.\\n\\n![Designer UI showing Split Choices](SplitChoices.png)\\n\\n# Improvements\\n\\n- Enhanced the adaptive Rich Text Editor for better usability and formatting support.\\n- Updated permission handling when assigning placeholder permission fields via API or workflow.\\n\\n# Bug Fixes\\n\\n- Fixed a crash that occurred when attempting to extend a non-existent list.\\n- Resolved an error triggered by the timer under certain conditions.\\n- Addressed styling inconsistencies in adaptive components."},{"id":"/2025/10/13/2025-10-13-1.56.3 - Rapid Platform/1.56.3 - Rapid Platform","metadata":{"permalink":"/changelog/2025/10/13/2025-10-13-1.56.3 - Rapid Platform/1.56.3 - Rapid Platform","source":"@site/blog/2025-10-13-1.56.3 - Rapid Platform/2025-10-13-1.56.3 - Rapid Platform.md","title":"1.56.3 - Rapid Platform","description":"Release Date: 13/10/25","date":"2025-10-13T00:00:00.000Z","tags":[{"inline":true,"label":"Changelog","permalink":"/changelog/tags/changelog"}],"readingTime":1.21,"hasTruncateMarker":false,"authors":[{"name":"Joshua Nauer","title":"Documents","url":"https://github.com/decept1kon","email":"sales@rapidplatform.com","imageURL":"https://github.com/decept1kon.png","key":"josh","page":null}],"frontMatter":{"authors":["josh"],"tags":["Changelog"]},"unlisted":false,"prevItem":{"title":"1.57.0 - Rapid Platform","permalink":"/changelog/2025/11/10/2025-11-10-1.57.0 - Rapid Platform/1.57.0 - Rapid Platform"},"nextItem":{"title":"1.55.9 - Rapid Platform","permalink":"/changelog/2025/09/09/2025-09-09-1.55.9 - Rapid Platform/1.55.9 - Rapid Platform"}},"content":"**Release Date:** 13/10/25\\n\\n# 1.56.3 Rapid Platform\\n\\nWe\'re excited to announce new features live on Rapid Platform **Monday October 13th**!\\n\\n---\\n\\n## Embedded File Access in Public Forms\\n\\nUsers can now seamlessly open embedded files directly from Public Forms. When accessing a form that includes an embedded document, the file opens in SharePoint, allowing users to edit the document in real time. Any changes made are instantly synchronised with SharePoint, ensuring live updates across connected platforms.\\n\\n## Authenticated Forms\\n\\nWe\'ve introduced support for authenticated Adaptive Documents. You can now configure a User Task in Workflow to require login before accessing an Adaptive Document. This enhancement updates the User Task configuration panel with three new toggles, offering greater control over document access and behaviour.\\n\\n![alt text](authform.png)\\n\\nOnly principals will be granted access to authenticated forms, ensuring secure and role-based visibility. Additionally, user fields will now automatically populate when an authenticated form is used, streamlining data entry\\n\\n# Improvements\\n\\n- Added Confirmation Dialog to when closing half created items\\n- Clicking logo in Explorer now navigates to experience dashboard\\n- Added support BitWarden Chrome extension\\n- Switching experiences now displays the dashboard\\n\\n# Bug Fixes\\n\\n- Fixed searching in Cascading Lookups failing to populate items\\n- Fixed current experience button failling to appear selected\\n- Fixed creating items using an API call now respects default configuration\\n- Opening an item in Explorer with the Title field set to DateTime no longer crashes the page\\n- Activity Feed now displays the most recent 250 items"},{"id":"/2025/09/09/2025-09-09-1.55.9 - Rapid Platform/1.55.9 - Rapid Platform","metadata":{"permalink":"/changelog/2025/09/09/2025-09-09-1.55.9 - Rapid Platform/1.55.9 - Rapid Platform","source":"@site/blog/2025-09-09-1.55.9 - Rapid Platform/2025-09-09-1.55.9 - Rapid Platform.md","title":"1.55.9 - Rapid Platform","description":"Release Date: 09/09/25","date":"2025-09-09T00:00:00.000Z","tags":[{"inline":true,"label":"Changelog","permalink":"/changelog/tags/changelog"}],"readingTime":1.63,"hasTruncateMarker":false,"authors":[{"name":"Matt Franklin","title":"Documents","url":"https://github.com/MattFranklin-Rapid","email":"matthew@rapidplatform.com","imageURL":"https://github.com/MattFranklin-Rapid.png","key":"matt","page":null}],"frontMatter":{"authors":["matt"],"tags":["Changelog"]},"unlisted":false,"prevItem":{"title":"1.56.3 - Rapid Platform","permalink":"/changelog/2025/10/13/2025-10-13-1.56.3 - Rapid Platform/1.56.3 - Rapid Platform"},"nextItem":{"title":"1.55.0 - Rapid Platform","permalink":"/changelog/2025/08/08/2025-08-08-1.55.0 - Rapid Platform/1.55.0 - Rapid Platform"}},"content":"**Release Date:** 09/09/25\\n\\n# 1.55.9 - Rapid Platform\\n\\nWe\'re excited to announce new features live on Rapid Platform **Tuesday September 9th**!\\n\\nThis release focuses around usability improvements and fixes after the last major mono-repo release.\\n\\nPlease see below for more details:\\n\\n---\\n\\n## Custom Experiences\\n\\nYou can now build tailored experiences with unique menus and dashboard pages. Set specific permissions for users and groups to control access and visibility, giving you more flexibility than ever.\\n\\n## Upgraded Breadcrumbs\\n\\nNavigation just got easier. You\u2019ll now see the last 3 places you visited, helping you move faster and stay oriented while working on deep items.\\n\\n## New SharePoint to PDF Workflow Task\\n\\nAutomate more with our new workflow service task that takes a SharePoint file and generates a PDF version seamlessly.\\n\\n---\\n\\n## Usability Improvements\\n\\n- Filtered out App type Adaptive Documents from Adaptive Designer\\n- Added new description filed to Adaptive input fields, matching Explorer\\n- You can now configure the title of Public Forms separate from their document name\\n- Open URL actions in Adaptive can now configure whether to open in a new tab or the same\\n- Call Activities in Workflow now map their output values so you can access them\\n- Activity feed is now limited to the most recent 250 items, improving load times on old items\\n- Scrolling a data-table in an item context can now get the next page of items when over 250\\n\\n## Bug Fixes\\n\\n- Cleaned up configuring menus sometimes getting stuck\\n- Sending PDF files in workflow Emails should no longer be corrupt in Outlook\\n- Post-Submission forms in Public Forms now render again\\n- Data-Association elements in Workflow now behave correctly when rolling back past them\\n- Prevented infinite fetch loop when searching items under specific conditions\\n- Prevented infinite fetch loop when scrolling a data table\\n- Can now view linked sub-type items via the parent (or other base lookup field) in item contexts\\n- Prevent data table crash when moving between tabs in item context that had different view names"},{"id":"/2025/08/08/2025-08-08-1.55.0 - Rapid Platform/1.55.0 - Rapid Platform","metadata":{"permalink":"/changelog/2025/08/08/2025-08-08-1.55.0 - Rapid Platform/1.55.0 - Rapid Platform","source":"@site/blog/2025-08-08-1.55.0 - Rapid Platform/2025-08-08-1.55.0 - Rapid Platform.md","title":"1.55.0 - Rapid Platform","description":"Release Date: 08/08/25","date":"2025-08-08T00:00:00.000Z","tags":[{"inline":true,"label":"Changelog","permalink":"/changelog/tags/changelog"}],"readingTime":1.89,"hasTruncateMarker":false,"authors":[{"name":"Danny Rattu","title":"Documents","url":"https://github.com/DannyRattu","email":"danny.rattu@rapidplatform.com","imageURL":"https://github.com/DannyRattu.png","key":"danny","page":null}],"frontMatter":{"authors":["danny"],"tags":["Changelog"]},"unlisted":false,"prevItem":{"title":"1.55.9 - Rapid Platform","permalink":"/changelog/2025/09/09/2025-09-09-1.55.9 - Rapid Platform/1.55.9 - Rapid Platform"},"nextItem":{"title":"1.54.0 - Rapid Platform","permalink":"/changelog/2025/05/14/2025-05-14-1.54.0 - Rapid Platform/1.54.0 - Rapid Platform"}},"content":"**Release Date:** 08/08/25  \\n\\n# 1.55.0 - Rapid Platform\\n\\nWe\u2019re proud to announce a major milestone in the evolution of Rapid Platform. This release delivers a significant advancement:\\n\\nA **foundational architectural shift** through the consolidation of all major repositories into a single monorepo\u2014positioning Rapid for faster, more scalable development and innovation.\\n\\nThese improvements lay the groundwork for future innovations in mobile apps, client portals and further modernisation.\\n\\nIncluded in this release is also a powerful **new feature** that introduces dynamic data binding using lookup fields, enhancing the user experience by reducing manual data entry and improving data accuracy.\\n\\nPlease see below for more details:\\n\\n---\\n\\n## Platform Foundations: Monorepo & Modernisation\\n\\n### Monorepo Consolidation\\n\\n- Unified all core platform repositories into a single monorepo.\\n- Enables:\\n  - Faster, more reliable deployments  \\n  - Streamlined code reuse and improved team collaboration  \\n  - Reduces integration overhead and simplifies QA and release processes.\\n\\n### Modernized Tech Stack\\n\\n- Upgraded to the latest versions of React and supporting libraries.\\n- Aligns platform with modern best practices for performance, security, and scalability.\\n- Enables future flexibility with mobile and cross-platform UI frameworks.\\n\\n### Mobile App Readiness\\n\\n- Monorepo structure enables efficient development of mobile applications alongside the web platform.\\n- Shared component and logic layers reduce duplication and accelerate native mobile roadmap execution.\\n\\n---\\n\\n## New Feature: Dynamic Lookup Field Data Binding\\n\\n### Smarter Pages with Lookup-Driven Auto-Fill\\n\\n- You can now configure **lookup fields to automatically populate other fields** in the same record.  \\n- Perfect for scenarios such as:  \\n  - Selecting a **project template** to instantly apply default settings.  \\n  - Choosing a **material** in a quote item to pull in pricing or specifications from a price book.  \\n- Creates a **dynamic link between reference data and active inputs**, minimizing manual entry and improving data accuracy.\\n\\n### How to Configure Lookup Data Binding\\n\\n1. In **Designer**, go to the table containing your lookup column.  \\n2. Open the lookup column\u2019s configuration panel.  \\n3. Enable **Data Binding**.  \\n4. Map the fields from the lookup\u2019s source table to the corresponding fields in your destination table.  \\n\\n---\\n\\n## Looking to the Future\\n\\nWith the monorepo in place, Rapid is primed to move faster and smarter. These upgrades open the door to richer mobile apps, portals and adaptive development\u2014bringing even more value to our customers and partners.\\n\\nWe\u2019re thrilled to deliver this release and look forward to what we\u2019ll build next together."},{"id":"/2025/05/14/2025-05-14-1.54.0 - Rapid Platform/1.54.0 - Rapid Platform","metadata":{"permalink":"/changelog/2025/05/14/2025-05-14-1.54.0 - Rapid Platform/1.54.0 - Rapid Platform","source":"@site/blog/2025-05-14-1.54.0 - Rapid Platform/2025-05-14-1.54.0 - Rapid Platform.md","title":"1.54.0 - Rapid Platform","description":"Release Date: 15/05/25","date":"2025-05-14T00:00:00.000Z","tags":[{"inline":true,"label":"Changelog","permalink":"/changelog/tags/changelog"}],"readingTime":1.58,"hasTruncateMarker":false,"authors":[{"name":"Danny Rattu","title":"Documents","url":"https://github.com/DannyRattu","email":"danny.rattu@rapidplatform.com","imageURL":"https://github.com/DannyRattu.png","key":"danny","page":null}],"frontMatter":{"authors":["danny"],"tags":["Changelog"]},"unlisted":false,"prevItem":{"title":"1.55.0 - Rapid Platform","permalink":"/changelog/2025/08/08/2025-08-08-1.55.0 - Rapid Platform/1.55.0 - Rapid Platform"},"nextItem":{"title":"1.53.0 - Rapid Platform","permalink":"/changelog/2025/04/10/2025-04-10-1.53.0 - Rapid Platform/1.53.0 - Rapid Platform"}},"content":"**Release Date:** 15/05/25  \\n\\n# 1.54.0 - Rapid Platform\\n\\nThis release introduces key permission enhancements, stability improvements, and a variety of bug fixes to improve form interactions and data table functionality.\\n\\n## New Features\\n\\n- **Create Permission Granularity**  \\n  Introduced a `\\"Create\\"` permission type, allowing Keypers to fine-tune which users or groups can create list items.\\n\\n- **Additive Permissions Model**  \\n  Permissions are now additive, meaning `\\"Allow\\"` permissions take precedence across group memberships. This ensures users in higher-privileged roles retain appropriate access even when also part of more restricted groups (i.e. All Staff Group).\\n\\n## Bug Fixes\\n\\n- **Lodash Expression in Send Email Task**  \\n  Resolved an issue where array-handling Lodash expressions in the CC field were not resolving correctly.\\n\\n- **Neighbour Data Table Crash on Datasource Change**  \\n  Fixed a crash that occurred when changing a data table\u2019s datasource with a linked neighbour table.\\n\\n- **Groups in Adaptive If-Then Causing Crashes**  \\n  Prevented crashes caused by group logic placed within `If-Then` validation conditions in Adaptive.\\n\\n- **Disabled Save Button in Inline Editing**  \\n  Fixed a UI issue where the Save button was incorrectly disabled when inline editing was attempted on a Data Table with creation turned off.\\n\\n- **Multi-line Text Formatting in Documentation**  \\n  Corrected display issues with specific multi-line text formats in the Documentation component.\\n\\n- **Overlapping Form Fields**  \\n  Resolved field layout overlap when all columns were added to a item page and a new item was created.\\n\\n- **Arrow Key Navigation Blocked by Lookup Fields**  \\n  Addressed a keyboard navigation bug where movement using arrow keys stopped at lookup fields in Data Tables.\\n\\n- **Selected Row Edited During Inline Creation**  \\n  Fixed unintended edits to previously selected Data Table rows when new items were created inline.\\n\\n- **Date Picker UI Overlap**  \\n  Resolved UI conflict where the \u201cClear\u201d button overlapped with the calendar icon in date/date-time fields.\\n\\nThank you for using Rapid Platform! If you have questions or feedback, feel free to reach out to our support team."},{"id":"/2025/04/10/2025-04-10-1.53.0 - Rapid Platform/1.53.0 - Rapid Platform","metadata":{"permalink":"/changelog/2025/04/10/2025-04-10-1.53.0 - Rapid Platform/1.53.0 - Rapid Platform","source":"@site/blog/2025-04-10-1.53.0 - Rapid Platform/2025-04-10-1.53.0 - Rapid Platform.md","title":"1.53.0 - Rapid Platform","description":"Release Date: 10/04/25","date":"2025-04-10T00:00:00.000Z","tags":[{"inline":true,"label":"Changelog","permalink":"/changelog/tags/changelog"}],"readingTime":1.56,"hasTruncateMarker":false,"authors":[{"name":"Danny Rattu","title":"Documents","url":"https://github.com/DannyRattu","email":"danny.rattu@rapidplatform.com","imageURL":"https://github.com/DannyRattu.png","key":"danny","page":null}],"frontMatter":{"authors":["danny"],"tags":["Changelog"]},"unlisted":false,"prevItem":{"title":"1.54.0 - Rapid Platform","permalink":"/changelog/2025/05/14/2025-05-14-1.54.0 - Rapid Platform/1.54.0 - Rapid Platform"},"nextItem":{"title":"1.52.0 - Rapid Platform","permalink":"/changelog/2025/03/27/2025-03-27-1.52.0 - Rapid Platform/1.52.0 - Rapid Platform"}},"content":"**Release Date:** 10/04/25  \\n\\n# 1.53.0 - Rapid Platform\\n\\nThis update includes important bug fixes, usability enhancements, and new features aimed at improving adaptive form workflows, permissions management, and public form access.  \\n\\n## New Features\\n\\n- **Dynamic Task Descriptions with Prefilled Data**  \\n  Task descriptions within workflows can now include **Lodash expressions** and **HTML** to dynamically prefill relevant information. This ensures that task assignees receive the context they need to complete tasks accurately and efficiently.\\n\\n- **Public Form Usage Without Admin Consent**  \\n  Users can now access **public forms for non-file purposes** without requiring administrative consent, enabling streamlined form distribution.\\n\\n- **Column-Based Filtering on Boards and Lists**  \\n  Users can now select a **specific column from a configured table** to use as a filter on Board and List components. This enhancement provides greater control and flexibility in organizing and displaying data.\\n\\n## Bug Fixes\\n\\n- **Permission Search Behavior**  \\n  Corrected an issue where the permission search was **case sensitive** and only matched column names. Searches now recognize both case and column titles for improved usability.\\n\\n- **Adaptive Control Connection Setup**  \\n  Resolved an issue preventing users from **configuring a connection** when adding a new Adaptive control.\\n\\n- **Tristate Toggle Condition Handling**  \\n  Fixed inconsistent behavior in **Tristate Toggle controls** when using conditional logic in V3 Adaptive forms.\\n\\n- **Date and DateTime Default Value Handling**  \\n  Addressed an issue where removing default relative times from Date and DateTime fields incorrectly defaulted to **today\u2019s date**.\\n\\n- **Stale Values on Item Navigation**  \\n  Fixed a bug that caused **item values to become outdated** when navigating between records.\\n\\n- **Divider Control Crash in V3 Documents**  \\n  Resolved a crash caused by clicking on a missing **Divider control** within the element tree of an Adaptive V3 document.\\n\\n- **Duplicate Users in Placeholder Permissions**  \\n  Fixed a bug that allowed **duplicate user entries** when using placeholder permissions.\\n\\nThank you for using Rapid Platform! If you have any questions or encounter any issues, please reach out to our support team."},{"id":"/2025/03/27/2025-03-27-1.52.0 - Rapid Platform/1.52.0 - Rapid Platform","metadata":{"permalink":"/changelog/2025/03/27/2025-03-27-1.52.0 - Rapid Platform/1.52.0 - Rapid Platform","source":"@site/blog/2025-03-27-1.52.0 - Rapid Platform/2025-03-27-1.52.0 - Rapid Platform.md","title":"1.52.0 - Rapid Platform","description":"Release Date: 27/03/25","date":"2025-03-27T00:00:00.000Z","tags":[{"inline":true,"label":"Changelog","permalink":"/changelog/tags/changelog"}],"readingTime":2.11,"hasTruncateMarker":false,"authors":[{"name":"Danny Rattu","title":"Documents","url":"https://github.com/DannyRattu","email":"danny.rattu@rapidplatform.com","imageURL":"https://github.com/DannyRattu.png","key":"danny","page":null}],"frontMatter":{"authors":["danny"],"tags":["Changelog"]},"unlisted":false,"prevItem":{"title":"1.53.0 - Rapid Platform","permalink":"/changelog/2025/04/10/2025-04-10-1.53.0 - Rapid Platform/1.53.0 - Rapid Platform"},"nextItem":{"title":"1.51.0 - Rapid Platform","permalink":"/changelog/2025/02/13/2025-02-13-1.51.0 - Rapid Platform/1.51.0 - Rapid Platform"}},"content":"**Release Date:** 27/03/25  \\n\\n# 1.52.0 - Rapid Platform  \\n\\nThis release includes several new features, usability improvements, and a number of bug fixes. See below for more details:  \\n\\n## New Features  \\n\\n- **Bulk Item Updates in Data Tables**  \\n  - Users can now update multiple records simultaneously via data tables.  \\n  - After selecting multiple items, modifying a field will now apply the change across all selected items. Be sure to save your changes.  \\n\\n- **Time-Based Conditions for DateTime Fields**  \\n  - Users can now configure conditions that trigger based on time values within DateTime fields.  \\n\\n- **Disable CSV Export on Data Tables**  \\n  - Admins can now disable the \\"Export to CSV\\" option to prevent excessive database load.  \\n\\n- **Payment Feature Updates**  \\n  - Admins can now configure payment descriptions for better reconciliation.  \\n  - Payer accounts in Rapid now stay updated to prevent duplicate records.  \\n\\n## Bug Fixes  \\n\\n- **General Fixes**  \\n  - Refreshing the page no longer removes on-click actions in the Explorer Sidebar Menu.  \\n  - Changes to Date & Time fields are now correctly recorded in the activity feed.  \\n  - Fixed an issue where misconfigured feature permissions could accidentally lock users out of core features like Explorer.  \\n  - Resolved form component dependency issues between Create Screen and Details Page.  \\n  - Fixed POST errors when selecting \\"Test With\\" on new subqueries or computed columns.  \\n\\n- **V3 Control Fixes**  \\n  - Currency Field Prefix now displays correctly before interaction.  \\n  - Choice Control Colors now render properly.  \\n  - Multiline Text Field Sizing displays correctly when set to full height.  \\n  - Disabled Multiline Text Control users can no longer enter text via the HTML option.  \\n  - Number Control Default Value Handling users can now clear default values and set fields to NULL.  \\n  - Decimal Place Increments in Number Control step sizes can now be configured properly.  \\n  - Radio Control Justification Options \\"Evenly\\" and \\"Between\\" options now function as expected.  \\n  - Multi-Page Control Navigation hidden pages in public forms are no longer accessible.  \\n  - Image/Link Control URL Handling prevents automatic \\"https://v3.test.rpform.com/\\" prefixing.  \\n  - Multi-Lookup Placeholder Display now disappears after a selection is made.  \\n  - Dialog Control Elements missing \\"Add Element\\" button restored.  \\n  - Spacer Control Consistency now maintains uniform sizing.  \\n  - Divider Control Attributes now render correctly.  \\n  - Persistent Public Form Save Progress Button now correctly hidden.  \\n\\n- **File Upload Fixes**  \\n  - Fixed blank item creation when uploading files using an Embedded File component in a V3 public form.  \\n  - Resolved issues preventing file uploads when updating an item via a V3 public form.  \\n  - Fixed duplicated templates when updating an item with an embedded file template in Workflow V3.  \\n\\nThank you for using Rapid Platform! If you have any questions or encounter any issues, please reach out to our support team."},{"id":"/2025/02/13/2025-02-13-1.51.0 - Rapid Platform/1.51.0 - Rapid Platform","metadata":{"permalink":"/changelog/2025/02/13/2025-02-13-1.51.0 - Rapid Platform/1.51.0 - Rapid Platform","source":"@site/blog/2025-02-13-1.51.0 - Rapid Platform/2025-02-13-1.51.0 - Rapid Platform.md","title":"1.51.0 - Rapid Platform","description":"13/02/2025","date":"2025-02-13T00:00:00.000Z","tags":[{"inline":true,"label":"Changelog","permalink":"/changelog/tags/changelog"}],"readingTime":1.57,"hasTruncateMarker":false,"authors":[{"name":"Danny Rattu","title":"Documents","url":"https://github.com/DannyRattu","email":"danny.rattu@rapidplatform.com","imageURL":"https://github.com/DannyRattu.png","key":"danny","page":null}],"frontMatter":{"authors":["danny"],"tags":["Changelog"]},"unlisted":false,"prevItem":{"title":"1.52.0 - Rapid Platform","permalink":"/changelog/2025/03/27/2025-03-27-1.52.0 - Rapid Platform/1.52.0 - Rapid Platform"},"nextItem":{"title":"1.50.0 - Rapid Platform","permalink":"/changelog/2025/01/30/2025-01-30-1.50.0 - Rapid Platform/1.50.0 - Rapid Platform"}},"content":"13/02/2025\\n\\n# 1.51.0 - Rapid Platform\\n\\nIntroducing **Rapid Platform Release 1.51.0**. This update implements an overhaul to our Page Designer, refines numerous Adaptive v3 controls and enhances payment collection via persistent forms. See below for more details:\\n\\n## New Features\\n- **Page Designer Overhaul:** We\'ve made a major upgrade to how pages in **Explorer** are configured! This update improves usability by enhancing how fields can be placed and resized. Page fields in the Designer now correctly obey the placement indicator, resulting in a faster and smoother user experience.\\n- **Persistent Form Payment Collection:** Users can now collect payments through a persistent form link, simplifying recurring transactions and payment processing.\\n\\n## Bug Fixes\\n- **Lookup Flyouts in Forms:** Flyouts on lookup components now follow the target container properly when scrolling on the page.\\n- **Choice Control Color Persistence:** Fixed an issue where choice colors set in Adaptive V3 disappeared after navigating away and back to the configuration panel.\\n- **Adaptive V3 Element Naming:** Fixed an issue where renaming an element in the tree caused the name to revert unexpectedly.\\n- **Adaptive V3 Control Logic Fixes:**  \\n  - **NULL Target Values & Operators:** Operators such as \\"omit\\" now function correctly when the target value is NULL.  \\n  - **Fetch Item on Load:** Resolved delays in simultaneous updates on form fields linked to the same column connection.  \\n  - **Number Input Restrictions:**  \\n    - Removing MIN, MAX, or STEP SIZE no longer forces a value of 0.  \\n    - Fixed an issue where some manually entered numbers were blocked due to strict validation rules.  \\n- **View Connections in Adaptive Designer:** Users can now properly add elements in the context of their table when working with view (repeating section) connections.\\n- **Slow Internet & Public Forms:** Uploading large public forms with slow internet no longer triggers an incorrect Captcha error.\\n\\nThis release continues to refine the platform, making page configuration, workflow execution, and payment collection more reliable and user-friendly. As always, we appreciate your feedback\u2014keep it coming! \ud83d\ude80"},{"id":"/2025/01/30/2025-01-30-1.50.0 - Rapid Platform/1.50.0 - Rapid Platform","metadata":{"permalink":"/changelog/2025/01/30/2025-01-30-1.50.0 - Rapid Platform/1.50.0 - Rapid Platform","source":"@site/blog/2025-01-30-1.50.0 - Rapid Platform/2025-01-30-1.50.0 - Rapid Platform.md","title":"1.50.0 - Rapid Platform","description":"30/01/2025","date":"2025-01-30T00:00:00.000Z","tags":[{"inline":true,"label":"Changelog","permalink":"/changelog/tags/changelog"}],"readingTime":2.07,"hasTruncateMarker":false,"authors":[{"name":"Danny Rattu","title":"Documents","url":"https://github.com/DannyRattu","email":"danny.rattu@rapidplatform.com","imageURL":"https://github.com/DannyRattu.png","key":"danny","page":null}],"frontMatter":{"authors":["danny"],"tags":["Changelog"]},"unlisted":false,"prevItem":{"title":"1.51.0 - Rapid Platform","permalink":"/changelog/2025/02/13/2025-02-13-1.51.0 - Rapid Platform/1.51.0 - Rapid Platform"},"nextItem":{"title":"1.49.0 - Rapid Platform","permalink":"/changelog/2024/12/19/2024-12-19-1.49.0 - Rapid Platform/1.49.0 - Rapid Platform"}},"content":"30/01/2025\\n\\n# 1.50.0 - Rapid Platform\\n\\nAnnouncing **Rapid Platform release 1.50.0**, packed with exciting updates, including the ability to generate PowerPoint and Excel files through workflows, add new items to data tables with ease, and organise your activity feed with collapsible items for a clearer overview. These enhancements make managing your work smoother and more efficient!\\n\\n## New Features\\n- **PowerPoint and Excel File Generation in Workflows:** Users can now generate PowerPoint and Excel files through workflows, enabling streamlined reporting and presentation creation.\\n- **Creating Items via a Data Table:** Users can now add new items directly via data tables, simplifying data entry.\\n- **Collapsible Activity Feed Items:** Users can now collapse and expand each item in the activity feed, providing a broader and more organised view of all logged activities.\\n- **Gantt Chart Enhancements:** Gantt users can now view more than 250 items on Gantt charts, enabling better project management for large datasets.\\n- **Middle-Click Navigation in Data Tables:** Users can now middle-click on a title field in a Data Table to open it in a new tab.\\n\\n## Bug Fixes\\n- **Embedded File Templates:** Embedded file templates in Adaptive V3 now support single file uploads as expected, but modifications to allow multiple file uploads remain unsupported.\\n- **Adaptive V3 Placeholder Support:** Placeholder text added to choice fields in Adaptive V3 now appears as intended, providing clearer guidance for users.\\n- **Icon Overlap Issues:** Resolved overlapping issues when hovering over:\\n  - The description icon on an input field.\\n  - The public form link on a generate form ID field.\\n- **Multi-Lookup Configuration:** The parent list type is now omitted from configuration when setting up related connections in Adaptive V3, as multi-lookups between the same list type are not supported.\\n- **User Column Default Value:** Fixed an issue where User columns with a default value set to `@me` were being incorrectly updated to the platform user \\"Rapid Platform\\" during workflow data can updates.\\n- **Min/Max Relative Offset Toggle:** Addressed a bug where public forms treated the min/max relative offset as enabled even when toggled off in Adaptive V3.\\n- **Lookup Clicks in Pre-Fill Tasks:** Fixed a page crash occurring when clicking a lookup during data pre-filling on user tasks.\\n- **Placeholder in Choice Fields:** Fixed a bug where placeholders in choice fields appeared as selectable choices.\\n- **Label Component in Explorer:** Resolved a bug where the text in label components was vertically cut off.\\n- **Element Selection in Adaptive V3:** Fixed an issue where clicking elements in the Element Tree did not select them."},{"id":"/2024/12/19/2024-12-19-1.49.0 - Rapid Platform/1.49.0 - Rapid Platform","metadata":{"permalink":"/changelog/2024/12/19/2024-12-19-1.49.0 - Rapid Platform/1.49.0 - Rapid Platform","source":"@site/blog/2024-12-19-1.49.0 - Rapid Platform/2024-12-19-1.49.0 - Rapid Platform.md","title":"1.49.0 - Rapid Platform","description":"19/12/2024","date":"2024-12-19T00:00:00.000Z","tags":[{"inline":true,"label":"Changelog","permalink":"/changelog/tags/changelog"}],"readingTime":1.45,"hasTruncateMarker":false,"authors":[{"name":"Danny Rattu","title":"Documents","url":"https://github.com/DannyRattu","email":"danny.rattu@rapidplatform.com","imageURL":"https://github.com/DannyRattu.png","key":"danny","page":null}],"frontMatter":{"authors":["danny"],"tags":["Changelog"]},"unlisted":false,"prevItem":{"title":"1.50.0 - Rapid Platform","permalink":"/changelog/2025/01/30/2025-01-30-1.50.0 - Rapid Platform/1.50.0 - Rapid Platform"},"nextItem":{"title":"1.48.0 - Rapid Platform","permalink":"/changelog/2024/12/02/2024-12-02-1.48.0 - Rapid Platform/1.48.0 - Rapid Platform"}},"content":"19/12/2024\\n\\n# 1.49.0 - Rapid Platform\\n\\nWith **Rapid Platform release 1.49.0**, we\u2019re delivering enhanced usability and powerful features to help you work smarter and faster. From smoother data navigation to ensuring accurate data entries and improved file handling, this release focuses on making your everyday tasks more efficient. Here\'s what\'s new:\\n\\n## New Features\\n- **Duplicate Data Prevention:** Users can now ensure that duplicate records are not created when unique data is submitted more than once. For more information on how to implement unique data columns, please reach out to Rapid Support.\\n- **Drag-and-Drop Emails into Activity Feed:** Users can now drag email files (.msg or .eml) into an Activity feed, and the system will log the email details against that item, streamlining email activity management.\\n- **CSV Export Notifications and Restrictions:** Users are now notified that their CSV export is being generated immediately after clicking the export button. Additionally, users are restricted from initiating another export process until the current one is complete.\\n- **Payable Subtotal on Payment Forms:** Payment forms now display the payable subtotal before users validate their credit card details, offering greater transparency.\\n- **Enhanced Data Table Navigation:** Users can now navigate data tables with the tab key and directional arrows, improving accessibility and efficiency.\\n- **File Attachment Interface Improvements:** The user interface for embedded files has been refined to show file type icons and clearer labelling.\\n\\n## Bug Fixes\\n- **Interrupting Signal and Timer Issues:** Fixed an issue where the Interrupting Signal event was negatively impacting timers.\\n- **Adaptive V3 Designer Upgrades:** Ensured v3 designer fully and correctly upgrades v2 forms when loaded.\\n- **Date-Time Field AM/PM Settings:** Resolved an issue where the AM/PM setting could not be modified when \\"Show Time\\" was toggled ON in Adaptive v3 date-time fields."},{"id":"/2024/12/02/2024-12-02-1.48.0 - Rapid Platform/1.48.0 - Rapid Platform","metadata":{"permalink":"/changelog/2024/12/02/2024-12-02-1.48.0 - Rapid Platform/1.48.0 - Rapid Platform","source":"@site/blog/2024-12-02-1.48.0 - Rapid Platform/2024-12-02-1.48.0 - Rapid Platform.md","title":"1.48.0 - Rapid Platform","description":"02/12/2024","date":"2024-12-02T00:00:00.000Z","tags":[{"inline":true,"label":"Changelog","permalink":"/changelog/tags/changelog"}],"readingTime":2.03,"hasTruncateMarker":false,"authors":[{"name":"Danny Rattu","title":"Documents","url":"https://github.com/DannyRattu","email":"danny.rattu@rapidplatform.com","imageURL":"https://github.com/DannyRattu.png","key":"danny","page":null}],"frontMatter":{"authors":["danny"],"tags":["Changelog"]},"unlisted":false,"prevItem":{"title":"1.49.0 - Rapid Platform","permalink":"/changelog/2024/12/19/2024-12-19-1.49.0 - Rapid Platform/1.49.0 - Rapid Platform"},"nextItem":{"title":"1.47.0 - Rapid Platform","permalink":"/changelog/2024/11/18/2024-11-18-1.47.0 - Rapid Platform/1.47.0 - Rapid Platform"}},"content":"02/12/2024\\n\\n# 1.48.0 - Rapid Platform\\n\\nAnnouncing **Rapid Platform release 1.48.0**. This release focuses on enhancing data table flexibility and resolving various bugs to improve overall workflow and user experience. Below are the updates included in this release.\\n\\n## New Features\\n- **Editable Column Configuration:** Release 1.47.0 introduced the ability for users to perform inline editing in data tables. Building on that foundation, Release 1.48.0 gives users the ability to configure columns as non-editable. This enhancement allows for greater flexibility in system implementation, enabling users to restrict editable access for specific use cases and ensure precise control over data management.\\n\\n### How to Configure Non-Editable Columns\\n1. Navigate to the relevant table page.\\n2. Select the desired View from the **View dropdown**.\\n3. Click the **edit table icon** (located on the far right).\\n4. Click the **edit pencil** for the column you want to configure.\\n5. Select **Disable editing in data table**.\\n6. Click **Save**.  \\n   The selected column will now be non-editable.\\n\\n**Note:** If you want to disable editing for a column across the entire system, you must repeat this process for the column in all configured views.\\n\\n## Bug Fixes\\n- **Rapid Workflow Output to PDF:** Resolved an issue where fullstops were not permitted in PDF outputs, ensuring consistency with DOCX outputs.\\n- **Swim Lane Display in Process Diagrams:** Fixed a bug where swim lanes erroneously displayed as green on certain process diagrams during execution.\\n- **Explorer Field Search:** Addressed an issue where searching in specific lookup fields did not work properly. \\n- **Subtype Item Notifications:** Fixed a problem where adding a note to the activity feed failed when accessing Subtype items through notifications.\\n- **Data Table Subquery Fields:** Resolved an issue where values in data tables with more than one subquery field were not populated correctly.\\n- **Persistent Public Form Submission:** Resolved an issue where submitting a persistent public form erroneously marked the task as complete.\\n- **Lookup Field Behavior in Public Forms:** Fixed a bug causing public forms to jump back to the top of the form after selecting a lookup fields.\\n- **Public Payment Task Fees Toggle:** Resolved a problem where the \\"pass on fees\\" toggle in public payment tasks appeared non-functional.\\n- **Payment Form Fee Processing:** Fixed an issue where submitting a payment form with fees toggled off still included fees passed on to the customer in the processed amount.\\n\\nThese updates ensure a more stable and user-friendly experience. For any questions or assistance, please contact our support team."},{"id":"/2024/11/18/2024-11-18-1.47.0 - Rapid Platform/1.47.0 - Rapid Platform","metadata":{"permalink":"/changelog/2024/11/18/2024-11-18-1.47.0 - Rapid Platform/1.47.0 - Rapid Platform","source":"@site/blog/2024-11-18-1.47.0 - Rapid Platform/2024-11-18-1.47.0 - Rapid Platform.md","title":"1.47.0 - Rapid Platform","description":"21/11/2024","date":"2024-11-18T00:00:00.000Z","tags":[{"inline":true,"label":"Changelog","permalink":"/changelog/tags/changelog"}],"readingTime":1.69,"hasTruncateMarker":false,"authors":[{"name":"Danny Rattu","title":"Documents","url":"https://github.com/DannyRattu","email":"danny.rattu@rapidplatform.com","imageURL":"https://github.com/DannyRattu.png","key":"danny","page":null}],"frontMatter":{"authors":["danny"],"tags":["Changelog"]},"unlisted":false,"prevItem":{"title":"1.48.0 - Rapid Platform","permalink":"/changelog/2024/12/02/2024-12-02-1.48.0 - Rapid Platform/1.48.0 - Rapid Platform"},"nextItem":{"title":"1.46.0 - Rapid Platform","permalink":"/changelog/2024/10/22/2024-10-22-1.46.0 - Rapid Platform/1.46.0 - Rapid Platform"}},"content":"21/11/2024\\n\\n# 1.47.0 - Rapid Platform\\n\\nWe\u2019re excited to announce **Rapid Platform release 1.47.0**. This release expands data table functionality, allowing users to directly edit multiple field types, including text, dates, currency, and more, making data management more efficient and flexible. Read on to explore the full list of changes.\\n\\n## New Features\\n- **Inline Data Table Editing:** Users can now directly edit a variety of field types in data tables. To edit values via the data table, simply click into the desired field, make the necessary edits, and save the changes. The following column types are now editable with this release:\\n\\n  - Single Line of Text\\n  - Email\\n  - Date and Time\\n  - Date\\n  - Lookup\\n  - Boolean\\n  - Number\\n  - Percentage\\n  - Currency\\n  - User\\n  - Whole Number\\n\\n**Note:** If a column is designated as the title column, it will not be editable (due to it being the link to open the item).\\n\\n## Improvements\\n- **Adaptive v3 Number Inputs:** Adaptive number inputs now handle undefined or null values gracefully by leaving the field blank instead of defaulting to zero.\\n- **Enhanced Connection Identification:** Technical users can now clearly identify connections when configuring prefill data in workflow, improving usability.\\n- **Improved Item Cloning:** Cloned items now inherit parent lookup fields, reducing setup time and enhancing accuracy.\\n\\n## Bug Fixes\\n- **Adaptive Designer Element Tree:** Fixed an issue where the root node could be dragged into its children, causing the entire tree to disappear.\\n- **Connection Section Usability:** Fixed the unusable connection section displayed in layout sections\u2019 attributes panel.\\n- **Embedded File Replacement:** Replacing embedded files with files of the same name now updates correctly.\\n- **Choice Field Text Overlap:** Fixed an issue where choice field text overlapped with chevrons in certain configurations.\\n- **Connection Input Disconnection:** Resolved an issue where inputs added from single connections within a repeating context would disconnect from the connection.\\n- **Embedded Form Data Integrity:** Resolved an issue where adding or changing embedded forms wiped additional fields in a user task within workflow.\\n- **Multi-line Text Field Display:** Fixed a bug where expanding a multi-line text field caused pop-ups to appear behind other elements."},{"id":"/2024/10/22/2024-10-22-1.46.0 - Rapid Platform/1.46.0 - Rapid Platform","metadata":{"permalink":"/changelog/2024/10/22/2024-10-22-1.46.0 - Rapid Platform/1.46.0 - Rapid Platform","source":"@site/blog/2024-10-22-1.46.0 - Rapid Platform/2024-10-22-1.46.0 - Rapid Platform.md","title":"1.46.0 - Rapid Platform","description":"22/10/2024","date":"2024-10-22T00:00:00.000Z","tags":[{"inline":true,"label":"Changelog","permalink":"/changelog/tags/changelog"}],"readingTime":3.67,"hasTruncateMarker":false,"authors":[{"name":"Danny Rattu","title":"Documents","url":"https://github.com/DannyRattu","email":"danny.rattu@rapidplatform.com","imageURL":"https://github.com/DannyRattu.png","key":"danny","page":null}],"frontMatter":{"authors":["danny"],"tags":["Changelog"]},"unlisted":false,"prevItem":{"title":"1.47.0 - Rapid Platform","permalink":"/changelog/2024/11/18/2024-11-18-1.47.0 - Rapid Platform/1.47.0 - Rapid Platform"},"nextItem":{"title":"1.45.0 - Rapid Platform","permalink":"/changelog/2024/09/10/2024-09-10-1.45.0 - Rapid Platform/1.45.0 - Rapid Platform"}},"content":"22/10/2024\\n\\n# 1.46.0 - Rapid Platform\\n\\nIntroducing the latest Rapid Platform update 1.46.0, which brings a host of new features, improvements, and critical bug fixes aimed at enhancing user experience and platform stability. This release includes powerful new capabilities like fuzzy matching when searching Adaptive components, new payment forms and workflows (available to approved customers), and enhanced adaptive form functionalities. Read on to discover a list of key changes in this release.\\n\\n## New Features:\\n- **Fuzzy Matching for Component Selection**: The component selection panel in Adaptive Designer now supports fuzzy matching using lunr.js, making it easier for users to find form components.\\n- **Editable \\"Choice\\" Fields in Data Tables**: Users can now edit \\"Choice\\" fields directly in data tables, improving the user experience.\\n- **Payment Components in Adaptive Forms**: Users can now create adaptive forms with payment components, enabling one-time payments. NB: only available to approved customers.\\n- **Payment Tasks in Workflow**: Workflow can now pass through a payment amount into an adaptive form credit card component using a payment task. This allows for the delivery of Payment Forms to clients. NB: only available to approved customers.\\n- **Support for Lodash in Trigger URLs**: Technical users can now use Lodash in Trigger Endpoint URLs without validation issues.\\n\\n## Improvements:\\n- **Adaptive Designer CSS Isolation**: CSS styles are now better isolated in Adaptive Designer, preventing styling bleed into other components.\\n- **Side Menu Popup Enhancement**: Sidebar menu folders now pop up if they hit the bottom of the screen, improving usability before resorting to a scrollbar.\\n- **Browser Page/Tab Titles Reflect Context**: Browser Page/Tab titles now better reflect the context of the page, enhancing navigation and clarity.\\n- **Radio Button Configuration Overhaul**: In Adaptive V3, radio buttons now support vertical/horizontal alignment, justify options, and custom colors for checked and unchecked states, enhancing flexibility and user experience.\\n- **Input Boolean Control Enhancements**: A condition has been added to the Input.Boolean \\"inline-box\\" so it only shows when the toggle is set to checkbox mode.\\n- **Folder Syncing from Subqueries**: Improved syncing of folder titles from subqueries, ensuring accurate updates.\\n- **Improved Notifications Navigation**: Clicking on a notification now correctly navigates users to the relevant item.\\n- **Improved Lookup Dropdown Experience**: Lookup field dropdowns now stretch to display values within a reasonably sized window.\\n\\n## Bug Fixes:\\n- **Board Component Resizing**: Users can now resize the board component in grid layouts without being obstructed by the layout overlay.\\n- **Breadcrumb Corruption**: Fixed breadcrumb corruption issues when navigating between lookups or from Gantt charts.\\n- **File Rename Box Size**: The rename box in the file browser component has been resized for better usability.\\n- **Power BI Redis Connection Error**: Fixed a Redis connection error when migrating Power BI workspaces.\\n- **Adaptive Form Field Hiding Issue**: Fixed the issue where fields hidden in an adaptive form would disappear, making form management difficult.\\n- **Workflow Errors**: Fixed unhelpful error messages when running workflows without end events, making troubleshooting easier.\\n- **Lookup Configurations with Subqueries**: Lookups configured with subqueries now display titles correctly in the flyout.\\n- **Fixed Crashes on Adaptive Form Reopen**: Pages no longer crash when forms are reopened after being closed.\\n- **Form Submission Error with Files**: Resolved file upload issues causing errors during form submission.\\n- **Missing Users on Site Import**: Fixed issue where imported users were marked as \\"Not Set\\" when importing users/groups after site installation.\\n- **Column Minimum Width Fix**: Fixed the issue where column minimum width could no longer be set in table views.\\n\\n## Adaptive Fixes:\\n- **Tab Component in Adaptive V3**: Resolved display issues in the Tab component, improving its usability.\\n- **Adaptive V3 Designer Tooltip**: Corrected the on-hover tooltip in Adaptive V3 Designer, which was displaying incorrect information.\\n- **Lookup Display Field Crash**: Interacting with a lookup with an invalid display field no longer crashes the page in Adaptive V3.\\n- **Connection Handling**: Fixed issues where connections created via the UI were not updating correctly without re-selection.\\n- **Cloned Cards Issue**: Resolved issue where placing two cards on a form caused them to be linked and undeletable.\\n- **Form Submission Error**: Fixed a form submission error that occurred when uploading files.\\n- **Handling Cascading Lookup Fields**: Resolved issue where parent cascading lookups went blank when child cascading lookups were selected in preview mode.\\n- **Adaptive Document Saving Issue**: Fixed page crashes when reopening saved documents.\\n- **Adaptive Form Management Fixes**:\\n  - Fixed issues where cloned documents resulted in duplicate workspace items.\\n  - Addressed validation issues in document creation dialogs.\\n  - Resolved problems where documents were deleted but not removed from the UI."},{"id":"/2024/09/10/2024-09-10-1.45.0 - Rapid Platform/1.45.0 - Rapid Platform","metadata":{"permalink":"/changelog/2024/09/10/2024-09-10-1.45.0 - Rapid Platform/1.45.0 - Rapid Platform","source":"@site/blog/2024-09-10-1.45.0 - Rapid Platform/2024-09-10-1.45.0 - Rapid Platform.md","title":"1.45.0 - Rapid Platform","description":"10/09/2024","date":"2024-09-10T00:00:00.000Z","tags":[{"inline":true,"label":"Changelog","permalink":"/changelog/tags/changelog"}],"readingTime":0.34,"hasTruncateMarker":false,"authors":[{"name":"Matt Franklin","title":"Documents","url":"https://github.com/MattFranklin-Rapid","email":"matthew@rapidplatform.com","imageURL":"https://github.com/MattFranklin-Rapid.png","key":"matt","page":null}],"frontMatter":{"authors":["matt"],"tags":["Changelog"]},"unlisted":false,"prevItem":{"title":"1.46.0 - Rapid Platform","permalink":"/changelog/2024/10/22/2024-10-22-1.46.0 - Rapid Platform/1.46.0 - Rapid Platform"},"nextItem":{"title":"1.44.0 - Rapid Platform","permalink":"/changelog/2024/08/20/2024-08-20-1.44.0 - Rapid Platform/1.44.0 - Rapid Platform"}},"content":"10/09/2024\\n\\n# 1.45.0 - Rapid Platform\\n\\nThis release sees only minor architectural changes with no anticipated change in behaviour. While these changes are not mechanical, they are very wide reaching. This release has been isolated to ensure stable performance.\\n\\nAs with every release, if you notice anything strange or have any feedback please do get in touch via support or the new [general feedback form](https://rpform.io/grxAZ)."},{"id":"/2024/08/20/2024-08-20-1.44.0 - Rapid Platform/1.44.0 - Rapid Platform","metadata":{"permalink":"/changelog/2024/08/20/2024-08-20-1.44.0 - Rapid Platform/1.44.0 - Rapid Platform","source":"@site/blog/2024-08-20-1.44.0 - Rapid Platform/2024-08-20-1.44.0 - Rapid Platform.md","title":"1.44.0 - Rapid Platform","description":"20/08/2024","date":"2024-08-20T00:00:00.000Z","tags":[{"inline":true,"label":"Changelog","permalink":"/changelog/tags/changelog"}],"readingTime":7.91,"hasTruncateMarker":false,"authors":[{"name":"Matt Franklin","title":"Documents","url":"https://github.com/MattFranklin-Rapid","email":"matthew@rapidplatform.com","imageURL":"https://github.com/MattFranklin-Rapid.png","key":"matt","page":null}],"frontMatter":{"authors":["matt"],"tags":["Changelog"]},"unlisted":false,"prevItem":{"title":"1.45.0 - Rapid Platform","permalink":"/changelog/2024/09/10/2024-09-10-1.45.0 - Rapid Platform/1.45.0 - Rapid Platform"},"nextItem":{"title":"1.43.0 - Rapid Platform","permalink":"/changelog/2024/08/08/2024-08-08-1.43.0 - Rapid Platform/1.43.0 - Rapid Platform"}},"content":"20/08/2024\\n\\n# 1.44.0 - Rapid Platform\\n\\n## Feature\\n\\n### Introduction of Cascading Lookups in Adaptive V3\\n\\nThis new release introduces cascading lookups in Adaptive V3, allowing selections to dynamically filter related options. This ensures a more streamlined and efficient user experience with relevant data choices.\\n\\n**The concept of Cascading Lookups**  \\n\\nCascading fields concept involves setting up a pair of fields - can be called as ***Primary*** and ***Dependent***. The value of the _Primary_ field dictates the possible values for the _Dependent_ field. \\n\\nExtend this concept to a pair of lookups ie. both _Primary_ and _Dependent_ fields are a lookup type of control. Therefore, the _Primary lookup_ will have a list of values. Based on what the user selects in the _Primary lookup_, the _Dependent lookup_ will present a filtered list available for selection.\\n\\n\\n**Scenario**\\n\\nImagine  a WHS manager is trying to select a WHS representative from each department. The manager faces difficulty navigating a long, unfiltered employee list. \\n\\nThe manager now uses cascading lookups and sets up **Departments** as the primary lookup and **Employees** as the dependent lookup. With cascading lookups, selecting the department first filters the employee list, making it easy to choose the correct representative quickly and efficiently.\\n\\n:::info[Cascading Lookup logic]  \\n Step 1 - Show values of Column A from Table P (defined as Primary Lookup).  \\n Step 2 - Let the user select an item.  \\n Step 3 - For the item selected by user, take the value of Column B of Table P.  \\n Step 4 - Equate the value obtained in Step 3 with Column C of Table D (defined as Dependent Lookup). Get all the items which match this criteria.   \\n Step 5 - Show values of Column D from Table P for all items from Step 4.  \\n \\n Therefore, to set up Cascading Lookups we need to define:  \\n Table P  \\n  - Column A and \\n  - Column B  \\n\\nTable D  \\n  - Column C and \\n - Column D  \\n\\n:::  \\n\\n**Setting up the Cascading Lookups in Adaptive V3 Designer**\\n\\nWe shall attempt to configure the above scenario in Adaptive V3 Designer.\\n\\nTo configure the cascading lookups, add two lookup controls to your canvas. For ease of explanation we name them as Primary and Dependent.\\n\\nSet up the Primary Lookup as normal. Select the Table ***Departments*** as Lookup List and its column - ***Name*** as Lookup field. As per the normal behaviour of the control, this tells the system the table and column from where the values need to be displayed in the dropdown of the lookup. Therefore, in the Primary Lookup, the names of all the Departments will be displayed.\\n\\nSimilarly set up Dependent Lookup to show Full Name from Employees table.\\n\\n![Image showing two lookup controls added to the canvas](Cascading_1.png)\\n\\nObserve the above image, every lookup control now has a **new section in the Element Configuration Panel - Cascading**.\\n\\nThis section allows you to define the attributes that converts two separate lookup elements into a pair of cascading lookups.\\n\\nThe Cascading section in the Element Configuration Panel should be filled only for the Dependent lookup. \\n\\n![Image showing fields of cascading section](Cascading_2.jpeg)\\n\\nThe Cascading section has the following fields:\\n\\n1. Select Element - This is a dropdown field which will display titles of all the Lookup type of controls present on the Canvas. Select the Lookup element that you wish to set as Primary Lookup.\\n\\n2. To Field - Once the Primary Lookup element is selected, this field will display the list of the columns of the table set in Primary lookup. Select the column of the Primary Lookup against which you wish to equate the value.\\n\\n3. From Field - This field displays the list of all columns for the table set in Dependent lookup. Select the column with which you wish to equate the value of Primary Lookup.\\n\\nThis completes the simple set up of the cascading lookups.\\n\\nLets look at the behaviour of our Cascading Lookup as configured above:\\n\\n1. The Primary lookup shows the names of all the Departments.\\n\\n![Image showing Primary Lookup having names of departments](Cascading_3.png)\\n\\n2. Based on a Department selection, the Dependent Lookup shows a list of Employee Names that belong to the department selected in Primary.\\n\\n![Image showing employee names that belong to selected department](Cascading_4.png)\\n\\n3. Change the Department in Primary and the list of employees change in Dependent Lookup as well.\\n\\n![image showing change in employee list as the value of department changes](Cascading_5.png)\\n\\n**Custom configuration** \\n\\nA single lookup field can also be configured to show filtered values. Observe this field in the Cascading section of the Element Configuration Panel.\\n\\nThe discussion so far was oriented towards the configuration with Element\\n\\n![Image showing element fields in cascading section](Cascading_6.png)\\n\\nIf you select the Custom option, then instead of \\"Primary element\\" you can define the table and select an item from it.   \\n\\n![Image showing custom fields in cascading section](Cascading_7.jpeg)  \\n\\nThe two new fields that appear on selecting Custom configuration are:\\n\\n1. Linked to List - This is a dropdown field and shall display the list of all the tables in the system. Select the relevant table here.\\n\\n2. Linked to ID - This is also a dropdown list and displays the values of title column for the table selected. Please note, although you select the title column, the system actually retrieves its record ID value.\\n\\n:::note[Important]  \\n\\nThe key point to note here is that when in Custom Mode, a single Lookup can also presents a filtered list as the parameters of the Primary Lookup are hard passed to it.\\n\\n![Image showing output of custom mode](Cascading_8.png)\\n\\nIn the above image, although the selected Department is IT, however, the employees of Projects Department are shown as per the Custom configuration.  \\n\\n:::\\n\\n:::tip[Important Points to note about Cascading Lookups]\\n\\n1. Cascading Lookups can function without establishing relationships via Connections.\\n\\n2. Care must be given while selecting the columns of Primary and Dependent Lookups based on Table definition. Both the columns should return comparable values. For instance, if one of the columns is a Lookup, it returns an ID value. Comparing this to a string will give an error.\\n\\n3. Cascading lookups work as one pair. You can define the same Primary for multiple Dependents.\\n\\n4. You can define a Multi-lookup as a Dependent as well. However, a Multi-lookups cannot function as Primary because the value matching is supported for one variable only.\\n\\n:::\\n\\n\\n## Improvement\\n\\n- Users can now tab through page elements without info tooltips being selected, improving navigation flow and accessibility.\\n- Users can now open title fields or item columns in a new tab by pressing the Ctrl key while clicking, allowing for quicker multitasking.\\n- Rapid support teams can now track errored process runs across the platform, improving issue resolution and monitoring.\\n- Users can now copy and paste adaptive elements and conditional expressions, speeding up the design process and reducing repetitive tasks.\\n\\n## Bug fixes\\n\\n- Fixed issue where attachment text overflowed its container.\\n- Corrected the spelling of \\"Built-In\\" in the Type column of the Menus list. It is now spelled \\"Build-In\\".\\n- Fixed issue where Explorer would not fetch or return data when a version change was applied.\\n- Menu panels now close when users click outside the menu area, improving usability.\\n- Fixed the collapse button functionality in the designer menus\\n- Currency fields are now right-aligned for easier readability and comparison.\\n- Fixed toggle visibility issue on attachment bars in tab strips.\\n- Resolved Gantt view rendering issues to ensure expected visual representation.\\n- Updated header bar colours on Gantt charts to align with branding.\\n- Adjusted file explorer preview zoom level to a more suitable default of 100%.\\n- Fixed issue with conditionally disabled menu items not updating after field value changes.\\n- Fixed subquery column issue that caused \\"(no title)\\" to display instead of the correct title.\\n- Resolved error that occurred when creating items with empty date or date-time lookups.\\n- Corrected behaviour for Whole Number inputs to function as expected.\\n- Fixed issue where not all fields were cleared when saving and adding a new embedded file template.\\n- Resolved issue causing duplicate file references when replacing embedded files in public forms.\\n- Fixed presentation of Percentage and Whole Number inputs in workflows, no longer displayed as strings.\\n- Resolved issue where unrelated principals were populated in the \\"Assigned To\\" field when using a Rapid Unique Identifier.\\n- Bot interaction history is now retained when switching between documentation and support.\\n- Fixed issue with nested menu actions being incorrectly presented on data tables configured to \\"Item only.\\"\\n- Enhanced security by sanitizing HTML content in notification items.\\n- Restored correct shape and format of user field inputs in Workflow.\\n- Fixed error when pre-filling date and date-time fields in embedded forms.\\n- Page now displays an appropriate message when a user without permissions tries to access Explorer, instead of crashing.\\n- Fixed issue preventing workflows with collaboration buckets around swimlanes from being saved.\\n\\n**Adaptive fixes**\\n- Fixed issue preventing all files from saving when using the \'Save all\' function in Adaptive V3.\\n- Number inputs in Adaptive V3 now correctly respect Max, Min, and Step Size values.\\n- Resolved issue where the parent lookup flyout appeared blank in public forms.\\n- Adaptive forms are now properly deactivated when a task is aborted in a workflow.\\n- Fixed crash when loading a public form with parent/child connections set to load nothing.\\n- V3 documents are no longer visible when using the document picker in V2 Adaptive Designer.\\n- V3 documents are no longer visible when opening the document picker in V2 Designer.\\n- Improved validation UI for better user understanding and interaction.\\n- Applied multiple UI and experience enhancements to Adaptive Designer."},{"id":"/2024/08/08/2024-08-08-1.43.0 - Rapid Platform/1.43.0 - Rapid Platform","metadata":{"permalink":"/changelog/2024/08/08/2024-08-08-1.43.0 - Rapid Platform/1.43.0 - Rapid Platform","source":"@site/blog/2024-08-08-1.43.0 - Rapid Platform/2024-08-08-1.43.0 - Rapid Platform.md","title":"1.43.0 - Rapid Platform","description":"08/08/2024","date":"2024-08-08T00:00:00.000Z","tags":[{"inline":true,"label":"Changelog","permalink":"/changelog/tags/changelog"}],"readingTime":2.13,"hasTruncateMarker":false,"authors":[{"name":"Matt Franklin","title":"Documents","url":"https://github.com/MattFranklin-Rapid","email":"matthew@rapidplatform.com","imageURL":"https://github.com/MattFranklin-Rapid.png","key":"matt","page":null}],"frontMatter":{"authors":["matt"],"tags":["Changelog"]},"unlisted":false,"prevItem":{"title":"1.44.0 - Rapid Platform","permalink":"/changelog/2024/08/20/2024-08-20-1.44.0 - Rapid Platform/1.44.0 - Rapid Platform"},"nextItem":{"title":"1.42.0 - Rapid Platform","permalink":"/changelog/2024/06/29/2024-06-29-1.42.0 - Rapid Platform/1.42.0 - Rapid Platform"}},"content":"08/08/2024\\n\\n# 1.43.0 - Rapid Platform\\n\\n## Feature\\n\\n**Retain Page State on Refresh**\\n\\nIn version 1.43 of Rapid Platform, we\'ve introduced a powerful new feature that preserves the state of your working page even after refreshing the browser. \\n\\nImagine you\'re in Explorer, working within the Tasks List:\\n\\n1. You\'ve switched from the default \\"Active\\" view to \\"Not Started\\".\\n2. You then search for a specific group of tasks using the Search bar.\\n3. You hit the refresh button.\\n\\n![Image showing how the page state is retained post refresh](Retain_state_v1-43.png)\\n\\nPreviously, this would reset your session, forcing you to redo your adjustments. Now, with this update, Rapid Platform will automatically restore the exact state you were in prior to the refresh, including your selected view and search results. This enhancement allows you to seamlessly continue your work without losing your place, minimising disruptions and improving efficiency. This is particularly beneficial for those who manage multiple tabs simultaneously.\\n\\nWith this improvement, accidental refreshes will no longer cause frustration, letting you pick up right where you left off.\\n\\n## Improvement\\n\\n- Added support for middle-clicking and control-clicking menu items in Explorer to open them in a new tab of web browser.\\n\\n## Bug fixes\\n\\n- Fixed an issue where clicking \\"Process Diagrams\\" in the JumboTron after executing a workflow with an embedded form caused the data table to crash.  \\n- Resolved inconsistency where workflow diagrams displayed a footer in test environments but not in production.\\n- Restored functionality of the menu buttons with on-click action set as \\"Raise Workflow Created Signal\\". The error \\"Cannot raise signal: Converting circular structure to JSON --\x3e starting at object with constructor...\\" has been resolved.\\n- Fixed breadcrumb corruption issue when opening a task from a process run.\\n- Addressed an issue causing an infinite loop during the initial login after signing up for Rapid Platform.\\n- Resolved error that occurred when executing a user task, which updated a SharePoint folder name.\\n- Fixed issue where adding principals via OID would throw an error despite the operation succeeding.\\n- Fixed the table crash issue that occurred when creating a new process diagram.\\n- Resolved error encountered when launching a user task with an adaptive document.\\n- Updated the Edit Diagram button on a process run in Explorer to generate the correct route, preventing page crashes.\\n- Fixed error encountered when deleting a subtype on sites with disabled row-level security.\\n- Resolved issue where the delete button was incorrectly disabled on item level on sites with disabled row-level permissions.\\n- Addressed issue where deleted page components were not removed after saving and refreshing the page."},{"id":"/2024/06/29/2024-06-29-1.42.0 - Rapid Platform/1.42.0 - Rapid Platform","metadata":{"permalink":"/changelog/2024/06/29/2024-06-29-1.42.0 - Rapid Platform/1.42.0 - Rapid Platform","source":"@site/blog/2024-06-29-1.42.0 - Rapid Platform/2024-06-29-1.42.0 - Rapid Platform.md","title":"1.42.0 - Rapid Platform","description":"29/06/2024","date":"2024-06-29T00:00:00.000Z","tags":[{"inline":true,"label":"Changelog","permalink":"/changelog/tags/changelog"}],"readingTime":2.64,"hasTruncateMarker":false,"authors":[{"name":"Matt Franklin","title":"Documents","url":"https://github.com/MattFranklin-Rapid","email":"matthew@rapidplatform.com","imageURL":"https://github.com/MattFranklin-Rapid.png","key":"matt","page":null}],"frontMatter":{"authors":["matt"],"tags":["Changelog"]},"unlisted":false,"prevItem":{"title":"1.43.0 - Rapid Platform","permalink":"/changelog/2024/08/08/2024-08-08-1.43.0 - Rapid Platform/1.43.0 - Rapid Platform"},"nextItem":{"title":"1.41.1 - Rapid Platform","permalink":"/changelog/2024/06/07/2024-06-07-1.41.1 - Rapid Platform/1.41.1 - Rapid Platform"}},"content":"29/06/2024\\n\\n# 1.42.0 - Rapid Platform\\n## Features\\n\\n### New Preview feature for Attachments\\n\\n#### What is the change about?\\nThis release brings a new feature to preview the attachment file without using the _File Preview_ component. The option to preview the file is now placed within the attachment options along with Download and Remove.\\n\\n| Prior to Release v1.42.0 | Post Release v1.42.0 |  \\n| :-----------: | :----------: |\\n|![Image showing old attachment options](<Preview attachment 1.png>) | ![Image showing new attachment options](<Preview attachment 2.png>) |  \\n\\n#### How does the Preview work?\\nClicking on the Preview option in the attachments will open a wide screen preview of the subject file. \\n\\n![Image showing preview of an attachment file](<Preview attachment 3.png>)\\n\\nIf the attachment slot holds multiple files, then the user can preview other attachments using the arrow icons (marked in the image above).\\n\\nThe name of the attachment being previewed appears in the middle of the ribbon. \\n\\n#### What benefit does this feature bring?\\nWith the addition of preview within the attachment options, the compulsion of adding a _File Preview_ component to the Page is not there. The File Preview component sits on the Page and provides a constant preview of the selected file at the defined position on the Page. \\n\\n![Image showing File Preview component on Page](<Preview attachment 4.png>)\\n\\nIn many business situations, the requirement for having a constant preview of attachments is not there. The File Preview component, thus consumes space on the Page, which could be utilised for better experience. \\n\\nThe new preview feature functions like an on-demand preview of the file, when needed. \\n\\n#### Key points of Attachment Preview\\n\\n1. The Preview option (along with download option) will remain disabled (ghosted) till the attachment file(s) is uploaded. The upload of attachments will happen when you press the Save button. \\n\\n![Image showing options disabled when attachment not uploaded](<Preview attachment 5.png>)\\n\\n2. If the attachment slot is created from an embedded file template, then based on the type of the template the options\' appearance varies slightly:\\n\\n    a. If the attachment slot is of Single type (ie. able to hold a single file as attachment) - the options will appear right below the slot.  \\n    b. If the attachment slot is of Multiple type (ie. able to hold more than one files as attachments) - the list of files will appear below the slot and options for each attachment will appear in a separate, corresponding dropdown.\\n\\n![Image showing comparison of how options appear for single and multiple types of attachment slot](<Preview attachment 6.png>)\\n\\n## Improvements\\n\\n- Required fields are now clearly labelled as \\"required\\" in v3 generated forms.\\n- Enhanced public forms to indicate when they are in the process of being submitted.\\n\\n## Bug fixes\\n\\n- Corrected the positioning of the \\"This List is Empty\\" message in Data Tables (when viewed via Workflow).  \\n- Lookup fields to the base type on the create screen now autofill correctly.\\n- Fixed issue where validation on repeating sections was incorrectly blocking form submission.\\n- Resolved page crash issue when editing a menu item that opens a public form link.\\n- Fixed cursor behaviour in validation configuration message box to prevent it from jumping to the end.\\n- Addressed regression issue with multi-line text validation."},{"id":"/2024/06/07/2024-06-07-1.41.1 - Rapid Platform/1.41.1 - Rapid Platform","metadata":{"permalink":"/changelog/2024/06/07/2024-06-07-1.41.1 - Rapid Platform/1.41.1 - Rapid Platform","source":"@site/blog/2024-06-07-1.41.1 - Rapid Platform/2024-06-07-1.41.1 - Rapid Platform.md","title":"1.41.1 - Rapid Platform","description":"06/06/2024","date":"2024-06-07T00:00:00.000Z","tags":[{"inline":true,"label":"Changelog","permalink":"/changelog/tags/changelog"}],"readingTime":1.2,"hasTruncateMarker":false,"authors":[{"name":"Matt Franklin","title":"Documents","url":"https://github.com/MattFranklin-Rapid","email":"matthew@rapidplatform.com","imageURL":"https://github.com/MattFranklin-Rapid.png","key":"matt","page":null}],"frontMatter":{"authors":["matt"],"tags":["Changelog"]},"unlisted":false,"prevItem":{"title":"1.42.0 - Rapid Platform","permalink":"/changelog/2024/06/29/2024-06-29-1.42.0 - Rapid Platform/1.42.0 - Rapid Platform"},"nextItem":{"title":"1.40.0 - Rapid Platform","permalink":"/changelog/2024/05/05/2024-05-05-1.40.0 - Rapid Platform/1.40.0 - Rapid Platform"}},"content":"06/06/2024\\n\\n# 1.41.0 - Rapid Platform\\n\\n## Features\\n\\nThis release focuses on usability and clean-up.\\n\\n## Improvements\\n\\n- Interruption events can now be configured to a specific list item ID rather than relying on the signal event item.\\n- Adaptive fields with masking no longer block submission if left empty\\n- Added disabled state to side-bar menu items when blocked by permissions\\n- Added a default details page for the Settings table\\n- Cleaned up the UI for configuring menus\\n- Added support to clone multi-lookup fields when cloning items\\n- You can now delete pages from a site in Designer\\n- Added more styling options to Radio inputs in Adaptive Designer\\n- Improved contextual memory when navigating Explorer (views and tabs should be more stable)\\n- Added support for Product owned links for the Support Request panel\\n\\n## Bug fixes\\n\\n- Ensured validation messages are displayed in Adaptive Documents on submission\\n- Reinstated page scroll when configuring pages in Designer\\n- Fixed some cases where creating a state in Adaptive Designer would fail\\n- Ensured the OData `in()` operator can regard base list columns on sub-types\\n- Prevented page crash when hovering \'Change Type\' right-click menu option in Adaptive Designer\\n- Fixed helper links for page creation buttons in Tasks experience to navigate to the correct Adaptive Designer\\n- Added handling for Currency inputs to Workflow from the Launch panel\\n- Added handling for Date inputs to Workflow from the Launch panel\\n- Removed being able to directly create universal links as an item in Workflow"},{"id":"/2024/05/05/2024-05-05-1.40.0 - Rapid Platform/1.40.0 - Rapid Platform","metadata":{"permalink":"/changelog/2024/05/05/2024-05-05-1.40.0 - Rapid Platform/1.40.0 - Rapid Platform","source":"@site/blog/2024-05-05-1.40.0 - Rapid Platform/2024-05-05-1.40.0 - Rapid Platform.md","title":"1.40.0 - Rapid Platform","description":"10/05/2024","date":"2024-05-05T00:00:00.000Z","tags":[{"inline":true,"label":"Changelog","permalink":"/changelog/tags/changelog"}],"readingTime":12.86,"hasTruncateMarker":false,"authors":[{"name":"Matt Franklin","title":"Documents","url":"https://github.com/MattFranklin-Rapid","email":"matthew@rapidplatform.com","imageURL":"https://github.com/MattFranklin-Rapid.png","key":"matt","page":null}],"frontMatter":{"authors":["matt"],"tags":["Changelog"]},"unlisted":false,"prevItem":{"title":"1.41.1 - Rapid Platform","permalink":"/changelog/2024/06/07/2024-06-07-1.41.1 - Rapid Platform/1.41.1 - Rapid Platform"},"nextItem":{"title":"1.39.0 - Rapid Platform","permalink":"/changelog/2024/04/30/2024-04-30-1.39.0 - Rapid Platform/1.39.0 - Rapid Platform"}},"content":"10/05/2024\\n\\n## Features\\n### Unification of Attachments and Embedded files components\\n\\nPrior to this release (v1.40), Rapid Platform has two components which the users could use to attach files against table items. These components were:\\n1. Embedded Files\\n2. Attachments\\n\\nAttachments and Embedded Files have always occupied a similar space. Frequently we have been asked about the difference between them and when to use either. \\nWith this new release both approaches have been collapsed into a singular Attachments system to make managing files on items simple.\\n\\nAlthough, both the components principally served the same functionality of attaching files against items; however, there were finer differences in functionalities offered by the two components. \\n\\nPost release v1.40, all the functionalities of Embedded Files and Attachments are merged together under the title Attachments.\\n\\nUnder Attachments, we now have:\\n1. Attachment File Bar (the parallel to Embedded files)\\n2. Attachments component\\n\\n#### Attachments in Designer\\n\\n**No more Embedded Files component in Designer**\\n\\nThe Embedded Files component can no more be seen in the Components list. The Attachments component can be added, as normal.\\n\\n![Image showing comparison of components across versions pre and post 1.40](<Attachments 1.png>)\\n\\n:::warning[Please note]  \\nThe Attachments component added from the \\"Add a component\\" panel  displays the list of attached files in Explorer. This may not be visible to the users in Explorer, if there are no files attached.\\n\\n![Image showing Attachment component added in Designer but not visible in Explorer](<Attachments 2.png>)\\n\\nThe users in Explorer cannot add files to the Attachments component until the Attachment File bar is enabled from the Tab Strip and the first file is uploaded there.\\n:::   \\n\\n**Enabling the Attachment File bar**\\n\\nTo provide the ability to upload files in Explorer, you need to enable the Attachment File bar from Tab Strip.\\n\\nPlease consider the following steps:\\n\\n1. Navigate to Designer of your desired Table.  \\n2. Goto Design Tab and select Singular (Item level) set of pages\\n3. On the Tab Strip, click the Edit icon.\\n\\n![Image showing click point to enter Edit panel of Tab strip](<Attachments 3.png>)\\n\\n4. The Tab Strip Edit panel will open showing the list of all the tabs. Toggle the \\"Show Attachment File bar\\" button for the tabs where you want to provide the users with ability to access Attachments.\\n\\n![Image showing Edit panel of Tab Strip highlighting Show attachment file bar toggle button](<Attachments 4.png>)\\n\\n\\n#### Attachments in Explorer\\n\\n**Adding files**\\n\\nWhen the Attachment File bar is enabled for the tab, the user can see an \\"upload\\" icon at the top left corner of the tab page.\\n\\n![Image showing Upload icon on Attachment File bar](<Attachments 5.png>)\\n\\nThe user can click the icon and the upload the desired file from a directory location. \\n\\nOR \\n\\nThe user can also drag and drop the file(s) at the icon.\\n\\nAs soon as the file is dropped at the icon, it gets uploaded as attachment to the subject item.\\n\\n![Image showing files attached in Attachment file bar and attachment components](<Attachments 6.png>)\\n\\n:::note[Please note]\\nIf the Attachments component is added to the page in Designer, then it will show the list of attached files in Explorer.\\n:::  \\n\\n:::info[Please note]  \\nIf there is an Attachments component added to the page \\nAND \\nthe user have added the first file to the Attachment File Bar, \\nTHEN\\nthe user can add more attachments by drag and drop to the Attachments component as well.\\n:::  \\n\\n:::tip[Please note]  \\nYou can select multiple files and upload them simultaneously.\\n:::\\n\\n\\n\\n**Appearance and features of Attachments in Explorer**\\n\\nThe Embedded Files appearance and features are available in the Attachment File bar. \\n\\n_Attachment File Bar_  \\n\\n![Image showing Attachment File bar](<Attachments 8.png>)\\n\\n1. As soon as the first file is attached, a rectangle titled \\"Attachments\\" appears (Attachment File bar). \\n\\n2. A small image identifier of the file displays at the left of the Attachment file bar, if the uploaded file is of an image type.\\nThis identifier also indicates the count of the files attached through this pattern. If the file count exceeds 4, the pattern shows first four images.\\n\\n![Image showing changing identifier pattern as attached files number is changed](<Attachments 7.png>)\\n\\n3. The name of the file attached is displayed.   \\n:::info[Please note]\\nIf there are more than one files attached, then the name of the first file in the stack is displayed.\\n:::\\n\\n*Features*\\n\\nAs the user clicks on the Attachment File bar rectangle, a list of all the files attached appears. \\n\\n- More files can be uploaded.\\n- Individual files can be downloaded / removed.\\n- All files can be removed.\\n\\n![Image showing features of Attachment File bar](<Attachments 9.png>)\\n\\nThe Attachments component appearance and features are retained in the Attachments component.\\n\\n_Attachments component_\\n\\nThe appearance and features of Attachments component are retained.\\n\\n![Image showing Attachments component](<Attachments 10.png>)\\n\\n1. File identifier image\\n2. File name\\n3. Download file \\n4. Remove file\\n\\n**Relationship with Files Browser component**\\n\\nAs soon as the first file is added as attachment to the item, an \\"Attachments\\" folder is created in the defined SharePoint directory of the item. \\n\\nThis can be accessed through the Files Browser in the Files Tab of the Item. \\n\\nThe \\"Attachments\\" folder will have all the files uploaded to the SharePoint automatically.\\n\\n![Image showing attachments folder visible in Files browser component in Files tab](<Attachments 11.png>)\\n\\n:::note[conclusion]\\n\\nAll the features and functionality of Embedded Files and Attachments is retained and unified as \\"Attachments\\".\\n\\n:::  \\n\\n\\n\\n### The all new Visualisation Component\\n\\nThis release introduces the cool 2D chart visualisation component. \\n\\nImagine a Project Manager trying to analyse the distribution of project tasks statuses (completed, in-progress and pending for start) from table data. It would be with a simple pie chart. Isn\'t it!\\n\\nOR\\n\\nImagine yourself as a finance manager, trying to crunch numbers analysing changes in pattern of average asset values for a particular type of asset across the last two financial years. A bar graph can be such a life saver! \\n\\nThis new visualisation component makes the assimilation of data easier, without the need to navigate off the table page (to load a specific Power Bi report). \\n\\n**How to add the visualisation component?**\\n\\nTo add a visualisation component, please consider the following steps:\\n\\n1. Navigate to your desired table in Designer.\\n2. Goto the Design tab and select the page where you want to add the visualisation.\\n3. Open the _Add a Component_ panel on the layout / page by clicking the + icon.\\n4. In the _Add a Component_, observe the section - Visualisation.  \\n\\n![Image showing Visualisation section in components](<Visual 1.png>)\\n\\n5. Click Visual to add the component to the layout / page.\\n\\n:::note[Please note]\\nThe visualisation section, at present, as two components  \\n    a. Counter component  \\n    b. Visual component\\n\\nThe <a href=\\"https://docs.rapidplatform.com/docs/Rapid/User%20Manual/glossary/#composition-area\\" target=\\"_blank\\">**Counter**</a> is an existing component, however, the Visual component has a capability to configure a counter and with a greater capacity to express data (discussed later in this article).   \\n\\nWe will discuss the Visual component in this article.  \\n:::\\n\\n:::tip[Please note]\\nIf you are adding a visual component to the list page, it is a good practice to first add a Tab Strip and then add Visual component to a separate tab. This way the user can view the list and the visualisation based on specific need.\\n\\nIf adding the Visual component on a page along with other components, it is important that the width and height of the component is kept large enough, so as to accommodate visual information properly.  \\n\\n![Image showing visual component on page](<Visual 2.png>)\\n:::\\n\\n**Configuring the Visual component**\\n\\nTo configure this component, please consider the following points:\\n\\n1. Once the component is added to the page, it appears in Red colour. This indicates that the component is not configured correctly yet.\\n\\n![Image showing unconfigured visual component](<Visual 3.png>)\\n\\n2. Click on the edit (pencil) icon.  \\n  ![Image showing edit preferences for component](<Visual 16.png>)\\nA panel to edit component preferences open up.\\n\\n3. Configure the component.  \\n Following is the description of each field of the Visual component Edit preferences panel.\\n\\n ![Image showing fields to configure visual component](<Visual 4.png>)\\n\\n   a. **Part of module** - This is a dropdown field. It has the list of all the modules available for your site. If your component belongs to a specific module, you can select the same in this field.   \\n\\n   b. **Type of chart** - Here you can select the nature of chart in which you want to display information. \\n   \\n   There are four options available at present:  \\n            i. Pie  \\n            ii. Donut  \\n            iii. Bar  \\n            iv. Counter  \\n\\n   Please note, you can select only one of the types. Although this field is not mandatory at present, you need to select a type to meaningfully configure the component. \\n\\n   c. **Title** - This is the title of your chart. It appears on the component in Designer and above the chart in Explorer. Although this field is not mandatory, however, it is a good practice to provide an appropriate title to your chart, so that it assists everyone in interpreting the information better.  \\n   \\n   Next is the **Source Data section.**\\n \\n   d. **Table** - This is a dropdown field. Clicking on this field will open a list of all tables present in the site. Select your desired table from this list. Please note this is a mandatory field.  \\n\\n   e. **View** - Based on the Table selected, all the eligible Views appear in this dropdown list. Select the View of your choice here. The name of the selected View will also appear on your component in Designer.\\n\\n   :::info[Please note]  \\n   Every 2D chart is based on a minimum of two variables. \\n   \\n   First is the **independent variable**. The independent variable  defines the group or category for which the chart is plotted. \\n   \\n   The second is the **dependent variable**. It defines  what value to plot for each state of independent variable (ie. each group or category). \\n   \\n   For example - A chart can be plotted to depict _average $ value_ of all assets by _asset condition_. Here, condition of asset is independent variable which defines the group or category. Condition can be  Excellent, Good, Fair or Not Working. \\n   \\n   The chart will plot dependent variable - average $ value - for each state of independent variable ie. of each group or category.  \\n   :::\\n\\n\\n   f. **Group By Field** - Here you can define independent variable - the group or category for which the value needs to be plotted. \\n   This is a dropdown field. Clicking on this field will open up the list of all the columns of the selected table (except those of Multi-lookup type). The column title appears with its type mentioned in brackets. Click your desired table column as independent variable.\\n\\n   **Aggregate Fields section**\\n\\n   g. **Add Aggregate** button - Click this button to add the dependent variable. As you click this button a set of three fields will appear in this section. \\n\\n   ![Image showing fields to add aggregate variable](<Visual 5.png>)\\n\\n   :::info[Please note]\\n\\n   The aggregate section allows you define the dependent variable for the chart. \\n\\n   It is important to note that you need to define at least one dependent variable for all chart types. \\n\\n   However, you can define more dependent variables for Bar chart and Counter types. \\n\\n   Pie and Donut chart work with only one dependent variable.\\n\\n   With every click on Add Aggregate button, a new set of fields will appear, allowing you to configure more dependent variables.\\n   :::\\n\\n   Please consider the below description of fields for aggregate (dependent) variable.\\n\\n      i. In case when there are multiple aggregates (dependent) variables defined, this allows you to arrange the variables in correct order. By click and drag on this icon you can reorder the variables up and down in the list of multiple aggregate variables.\\n\\n      ii. **Name** - You can type the name of the aggregate (dependent) variable here. It appears in the chart in Explorer.\\n\\n      iii. **Field** - This is a dropdown field. As you click on this field a list of all columns of the table (as selected in d. above) will appear. Again, the multi-lookup types do not feature in this list. You can select the desired column as your dependent variable. Please note this is a mandatory field.\\n\\n      iv. **Type** - The type field provides the function operator based on which the value of the selected aggregate variable is calibrated. This is a dropdown field. There can be six options:\\n\\n![Image shown the possible values for aggregate field](<Visual 7.png>)\\n\\n      The option names are self-explanatory of their meaning.\\n\\n:::warning[Please note]\\n      If you select the blank as a value for this type, the aggregate variable will become ineffective and will not appear in the chart.\\n\\n      This is a mandatory field and needs to have a non-blank value.\\n:::\\n\\n      v. **Bin** - Click on the bin icon to delete the aggregate variable.\\n\\n:::note[Please note]  \\n      You can configure multiple aggregates. \\n\\n![Image showing two aggregate variables configured](<Visual 6.png>)  \\n:::\\n\\n 4 . **Save the page** for the configuration to take effect.\\n\\n**How does a successfully configured visual component appear in Designer?**\\n\\n![Image showing successfully configured component in designer](<Visual 8.png>)\\n\\nA successfully configured component appears white, while a component not configured properly shall appear in red background.\\n\\nIt provides the following information.\\n\\n1. The type of chart selected\\n2. Title of the chart\\n3. View of the table selected\\n\\n**Sample of charts with one aggregate variable**\\n\\n| Pie chart | Donut chart | \\n| ----------- | ------------- | \\n| ![Image showing Pie chart](<Visual 9.png>) | ![Image showing Donut chart](<Visual 10.png>) | \\n\\n| Bar chart | Counter |\\n| -------- | --------- |\\n| ![Image showing Bar chart](<Visual 11.png>) | ![Image showing Counter](<Visual 12.png>) |\\n\\n**Sample of charts with two aggregate variables**\\n\\n| Bar chart | Counter |\\n| -------- | --------- |\\n| ![Image showing Bar chart with 2 aggregates](<Visual 13.png>) | ![Image showing Counter with 2 aggregates](<Visual 14.png>) |\\n\\n:::warning[Please note]\\nIt is important that the choices of variables and configuration are meaningful. For example - if you select a _Single line of text_ type of aggregate variable and ask the system to calibrate its average, then such a combination does not return any meaningful value. \\n\\nIn such cases, the component will break and it will not load / render on the Explorer page.\\n\\n![Image showing component not rendering in Explorer](<Visual 15.png>)\\n:::\\n\\n\\n## Improvements\\n\\n- Improved adaptive condition expressions to handle nested connections\\n- Improved adaptive validation expressions to handle nested connections\\n- Increased the size of the expanded multi-line text fields in explorer\\n- Added default date configuration for date fields\\n- Improved validation message presentation to not be so sticky\\n- Added Required star configuration support to Date and Choice adaptive inputs\\n- Added the connection for elements when picking an element through v3 Designer\\n- Single line of Text columns can now define their character limit (default 512)\\n- Workflow signal `changed()` function can now respect missing columns\\n\\n## Bug Fixes\\n\\n- Enabled configuration on file upload component in Adaptive v3\\n- Prevented Explorer documentation component from overflowing text\\n- Updated `htmlToText()` lodash function to not insert extra line breaks\\n- Deleting a connection in v3 Designer no longer deletes unrelated connections\\n- Prevented page crash on sign-up experience when the user has a fresh tenant\\n- Default value configuration on v3 Adaptive elements are now respected\\n- Fixed v3 rich text components being stuck in upper case\\n- Enabled menu permissions to apply to nested menu items\\n- Fixed public forms embedded files failing to respect the filename and drive configuration\\n- Updating a title via workflow no longer skips keeping SharePoint folders in sync\\n- Updating sub-type items will now keep their SharePoint folder in sync"},{"id":"/2024/04/30/2024-04-30-1.39.0 - Rapid Platform/1.39.0 - Rapid Platform","metadata":{"permalink":"/changelog/2024/04/30/2024-04-30-1.39.0 - Rapid Platform/1.39.0 - Rapid Platform","source":"@site/blog/2024-04-30-1.39.0 - Rapid Platform/2024-04-30-1.39.0 - Rapid Platform.md","title":"1.39.0 - Rapid Platform","description":"30/04/2024","date":"2024-04-30T00:00:00.000Z","tags":[{"inline":true,"label":"Changelog","permalink":"/changelog/tags/changelog"}],"readingTime":6.85,"hasTruncateMarker":false,"authors":[{"name":"Matt Franklin","title":"Documents","url":"https://github.com/MattFranklin-Rapid","email":"matthew@rapidplatform.com","imageURL":"https://github.com/MattFranklin-Rapid.png","key":"matt","page":null}],"frontMatter":{"authors":["matt"],"tags":["Changelog"]},"unlisted":false,"prevItem":{"title":"1.40.0 - Rapid Platform","permalink":"/changelog/2024/05/05/2024-05-05-1.40.0 - Rapid Platform/1.40.0 - Rapid Platform"},"nextItem":{"title":"1.38.0 - Rapid Platform","permalink":"/changelog/2024/03/26/2024-03-26-1.38 - Rapid Platform/1.38 - Rapid Platform"}},"content":"30/04/2024\\n\\n## Features\\n### System Settings Table\\n\\nWhile creating reports in Rapid Platform, it is not an uncommon to be want to create links to items within the report. You can now dynamically generate these links to regard the site they come from using the new Settings table. This table holds configuration information about the site itself, such as its identity.\\n\\n**The problem**\\nTo link an item in a report, a URL is required. This URL to the item has the title of the Tenant and Site.\\n\\nPreviously this would need to be baked into the reports themselves as the site was not aware of its own identity.\\n\\nThis notably failed in reporting scenarios that spanned multiple sites, or product reports that are deployed dynamically to customer sites.\\n\\n**The solution - \\"Settings\\" Table**\\nIn release v1.39, there is a new system list created with the title - \\"Settings\\". This Settings table has two columns - Title and Value.\\n\\n![Image showing columns tab in designer for Settings table](<./Settings table designer.png>)\\n\\nThis table stores the following about the subject site:\\n\\n1. The Site Title\\n2. The Site ID\\n3. The Tenant Title\\n4. The Tenant ID\\n5. The Environment\\n\\n![Image showing data in explorer for Settings table](<./Settings table explorer.png>)\\n\\nUsing the Settings Table, the problem is addressed. The title and id of the site is now stored in the system and hence is accessible by the report for creating links.\\n\\n**Using Settings in PowerBI**\\n\\nSettings is just a normal list as far as loading its data into your PowerBI reports. If you\'re interested in getting started straight away, here is a simple way to start generating dynamic links:\\n\\n1. Load the settings table into your data model directly grabbing the Site and Tenant values\\n![Image showing query to fetch site and tenant titles from Settings table](<./Query to get settings.png>)\\n\\n2. These are single row values, so use a measure to flatten the value into a scalar string for easy future referencing using the `MAXX` function\\n![Image showing ScalarSite and ScalarTenant tables](<./ScalarSite.png>)\\n\\n3. Setup the link URL using the values from the scalar Site and Tenant values you\'ve created, the concatenation `&` operator makes this nice and easy\\n![Image showing URL for report link to item](<./Link.png>)\\n\\n### Process Clean up\\n\\nProcesses frequently rely on certain items for the process to make sense. When a process run is triggered from a signal event the triggering item is now flagged as important to that process run. With this new feature, deletion of the important item will now abort the associated process(es). \\n\\nThis is an early feature exploring automated clean-up. Any feedback on what you expect, how it behaves and what you imagine it working would be greatly appreciated.\\n\\n### Conditionally Enabled Menus\\n\\nMenu items can be configured to perform specific actions like triggering a workflow, opening an adaptive document, sending an email etc. \\n\\nThere can be occasions when the defined action is eligible based upon a certain condition. \\n\\nFor example - consider a menu button is configured to trigger a workflow - to \\"wrap-up the project\\". This process involves sending out _thank you_ emails to all stakeholders, checking for any pending  deliverables, unpaid invoices, release of resources etc. \\n\\nA project wrap-up is only eligible for projects having status - \\"completed and ready for wrap-up\\". Imagine an employee (by mistake) clicks the \\"wrap-up project\\" button for an \\"in progress\\" project. This can cause anxiety and frustration among stakeholders, along with data changes that may be difficult to manage. \\n\\nYou can now enable / disable the menu button based on specific conditions. \\n\\n***Steps to conditionally enable a menu***\\n\\n1. Navigate to your desired table in Designer.\\n2. Goto the Menu tab.\\n3. There is a field titled - \\"Conditionally Enable\\".\\n\\n:::info[Please note]\\nThe Conditionally Enable field is visible when the location to display is either \\"Both\\" or \\"Item\\". This field will not be visible if the location to display of the menu is set as \\"Table\\".\\n\\n![Image showing field to configure condition visible / invisible based on location of menu selected ](<Conditionally enable 1.png>)\\n\\nThis is because, the functionality to enable / disable menu button checks for the condition at the item level. It does not hold any meaning at the list level.\\n\\nWith reference to behaviour of enable / disable of menu button\'s location on List / Item pages, please consider the following:  \\n\\n1. If the location to display is set as \\"Both\\" AND there is a condition specified in the \\"Conditionally Enable\\", then the subject menu button will always be ***disabled*** for the List page. It will be enabled or disabled on the item page based on whether the condition is met or not. \\n\\n2. If the location to display is set as \\"Item\\" AND condition is specified in the field, then the menu button will be enabled / disabled based on whether the condition is met or not. \\n\\n3. If the location to display is set as \\"Table\\", you cannot specify the condition as the field \\"Conditionally Enable\\" will not be visible in Designer.\\n\\n4. If the location to display is set as \\"Both\\" OR \\"Item\\" AND there the \\"Conditionally Enable\\" field is left blank, then the menu button will always appear as enabled on both List Page and Item Page (if location as Both) and Item Page (if location as Item).  \\n:::\\n\\n1. Provide the condition in the field. The syntax for the condition uses our <a href=\\"https://docs.rapidplatform.com/docs/Rapid/Developer%20Manual/API%20Concepts/#odata-filter-support\\">OData</a> filter query syntax. Fundamentally, there are three elements to the OData filter query  \\n   a. The column name. For example - **project_status**.  \\n   b. The operator. For example - **eq** (stands for equals).   \\n   c. The value to be operated against. For example - **\'Completed and ready for Wrap-up\'** (the string value needs to be provided in single quotes)  \\n\\n![Image showing OData syntax in field to specify condition](<Conditionally enable 2.png>)  \\n\\nTo learn more about OData $filter query <a href=\\"https://docs.rapidplatform.com/docs/Rapid/Developer%20Manual/API%20Concepts/#odata-filter-support\\" target=\\"_blank\\">**click here**</a>.\\n\\n1. Click Save.\\n\\n***Output in Explorer***\\n\\nThe menu button is enabled on the item page when the specified condition is met.\\n\\n![Image showing menu enabled as condition met](<Conditionally enable 3.png>)\\n\\nThe menu button is disabled on the item page when the specified condition is not met.\\n\\n![Image showing menu disabled as condition not met](<Conditionally enable 4.png>)\\n\\n## Improvements\\n\\n- You can now edit, remove and add to lists installed from a product definition\\n- Enabled editable system fields to be altered by data association update actions\\n- Adaptive v3 validation rules now only process once per pass\\n- Lookups & Multi-lookups can have default views configured in Public Forms\\n- The element picker in Adaptive Designer can now add elements in nested contexts\\n- Adaptive repeating contexts can have their default number of repeating sections configured\\n- Unique / Generic flags on Adaptive documents has been replaced with a global save button\\n- Adaptive Boolean elements can now display an undefined or null state\\n- Improved scrolling behaviour in Public Forms for mobile users\\n- Menus can now have descriptions added to them, displayed as a info call out\\n- Set the default time on DateTime pickers in Explorer to midday\\n- Added warning message to Data Cans that they can only fetch up to 250 items\\n- Added better pattern matching in Adaptive validation rules\\n- Updated system generated emails to use new branding\\n- Huge improvement to styling of Adaptive validation configuration controls\\n- Enabled default view configuration for lookups generated in Embedded Forms\\n\\n## Bug Fixes\\n\\n- When configuring the create page the details page is no longer affected\\n- Fixed installing PowerBI workspaces from failing as often\\n- Disabled fields with validation, especially from modules, no longer prevent item creation in Explorer\\n- Padding on Adaptive currency fields now regards the selected currency type\\n- Improved consistency when setting the SharePoint folder name automatically based off a Computed field\\n- Fixed field placeholder values not being able to be set in Designer\\n- Multi-Lookup fields in Explorer will now actually clear all selected elements when told\\n- Fixed the Time picker component failing to display when configured in Adaptive Designer\\n- Date inputs on process diagrams will no longer be stored as ISO DateTime strings but instead `yyyy-MM-dd` date strings"},{"id":"/2024/03/26/2024-03-26-1.38 - Rapid Platform/1.38 - Rapid Platform","metadata":{"permalink":"/changelog/2024/03/26/2024-03-26-1.38 - Rapid Platform/1.38 - Rapid Platform","source":"@site/blog/2024-03-26-1.38 - Rapid Platform/2024-03-26-1.38 - Rapid Platform.md","title":"1.38.0 - Rapid Platform","description":"30/03/2024","date":"2024-03-26T00:00:00.000Z","tags":[{"inline":true,"label":"Changelog","permalink":"/changelog/tags/changelog"}],"readingTime":4.08,"hasTruncateMarker":false,"authors":[{"name":"Matt Franklin","title":"Documents","url":"https://github.com/MattFranklin-Rapid","email":"matthew@rapidplatform.com","imageURL":"https://github.com/MattFranklin-Rapid.png","key":"matt","page":null}],"frontMatter":{"authors":["matt"],"tags":["Changelog"]},"unlisted":false,"prevItem":{"title":"1.39.0 - Rapid Platform","permalink":"/changelog/2024/04/30/2024-04-30-1.39.0 - Rapid Platform/1.39.0 - Rapid Platform"},"nextItem":{"title":"1.37.0 - Rapid Platform","permalink":"/changelog/2024/03/21/2024-03-21-1.37 - Rapid Platform/1.37 - Rapid Platform"}},"content":"30/03/2024\\n\\n## Features\\n\\n### Creating and enquiring about support requests\\n\\n**What is a support request?**\\n\\nA support request is a unit communication between the system user and the system\'s support staff. A user can create a support request when he/she is not able to proceed with a system functionality on his/her own or with the help of documentation. This indicates the need for assistance and a support request is a method to seek that assistance from support staff. \\n\\nUsers can also use support requests to submit bugs or improvement requests. \\n\\n**How to create a support request?**\\n\\nTo create a support request consider the following points:\\n\\n1. In Explorer, click the chatbot icon.\\n\\n![Image showing how to access chatbot in Explorer](<Support req 1.png>)\\n\\n2. The chatbot assistant panel will open. Click on Support. \\n\\n![Image showing Support Chatbot panel](<Support req 2.png>)\\n\\n:::info[Please note]\\nRapid Platform uses two different Chat bots; one trained on each - documentation and support. \\n:::\\n\\n3. You need to fill out the three mandatory fields:\\n\\n![Image showing the three mandatory fields to raise a support ticket](<Support req 3.png>)  \\n\\n- Subject - This a text field. Type in the subject of your support request here. It is a best practice to keep the subject crisp and relevant so that the support team can understand and refer to the issue effectively.\\n\\n- Scale - This is a dropdown field. Scale indicates the severity of the issue for the user. There are five levels of scale (in increasing order of severity). Select the most relevant scale value for your support request.\\n\\n![Image showing five scale options](<Support req 4.png>)\\n\\n- Description - This is a free-text (multi-lines of text) field. You can use this field to describe the issue with as much details as possible.\\n\\n:::tip[Please note]\\nDescription is  a richtext field. Therefore, you can use formatting options and also add images etc. as we do in a text editor.\\n\\nTo enter text editor mode, just click on the arrow icon at the top right corner of the Description field. \\n\\n![Image showing how to enter text editor mode for Description field](<Support req 5.png>)\\n:::\\n\\n4. Click \\"Submit\\".\\n\\n![Image showing Submit button](<Support req 6.png>)\\n\\n:::info[Please note]\\nThe Submit button shall become active only when all the three the fields are populated. Otherwise it remains in the inactive state.\\n:::\\n\\nOnce the support request is submitted successfully:\\n\\na. A success message will be displayed in the Support Chatbot panel. \\n\\n![Image showing success message for support ticket creation](<Support req 7.png>)\\n\\nb. An email confirmation will be sent to your inbox.\\n\\n![Image showing email confirmation message for support ticket creation](<Support req 8.png>)\\n:::note[Please note]\\nThe email will display the subject of your support request, appended with a system generated number. The email will also have a \\"Go to chat\\" button. If you click on \\"Go to chat\\" button, it will open the Microsoft Teams chatroom, which will connect you to the support team. The support team can ask you more relevant questions here, and you can use the chatroom to provide more details about the issue. \\n:::\\n\\n\\n**How to enquire about a support request**\\n\\nUsers can enquire about their support requests (submitted in past), from the chatbot. \\n\\nThe chatbot will respond with the status of the request.\\n\\nTo enquire about a support request, please consider the following points:\\n\\n1. In Explorer, click the chatbot icon.\\n\\n![Image showing how to access chatbot in Explorer](<Support req 1.png>)\\n\\n2. The chatbot assistant panel will open. Click on Support. \\n\\n![Image showing Support Chatbot panel](<Support req 2.png>)\\n\\n3. In the \\"Ask a question\\" field, type in your query regarding the support request. \\n\\n![Image showing how to query the chatbot for support tickets](<Support req 9.png>)\\n\\n4. Click submit. \\n\\nThe chatbot will respond with appropriate answer.\\n\\n## Improvements\\n- `/` characters in DocX file names will no longer be set to `_`\\n- Huge improvement in save & load times for pages, especially on large sites\\n- Improved support in Workflow OData filters for tables/columns that begin with a numeral\\n- Improved Adaptive Radio controls justified styling\\n- Added support for validation on repeating sections in Adaptive v3\\n- Huge improvement to the validation configurator for Adaptive v3\\n- Added required visual toggle for input fields in Adaptive v3\\n- Added Date column support in Adaptive v3\\n- Added delete confirmation when deleting a column\\n- Ensured the Get Item service task that fails to get an item throws an error\\n- Disabled needing a principal configuration when setting up Board components in Designer\\n\\n## Bug Fixes\\n- Fixed signing up with certain Azure permissions throwing an error\\n- Adding a Principal to a Role will no longer error out\\n- Fixed manual upload being erroneously applied to the file browser in some scenarios\\n- Prevented data association update actions from being able to alter system managed fields\\n- Disabled double submit on public forms when mashing the button"},{"id":"/2024/03/21/2024-03-21-1.37 - Rapid Platform/1.37 - Rapid Platform","metadata":{"permalink":"/changelog/2024/03/21/2024-03-21-1.37 - Rapid Platform/1.37 - Rapid Platform","source":"@site/blog/2024-03-21-1.37 - Rapid Platform/2024-03-21-1.37 - Rapid Platform.md","title":"1.37.0 - Rapid Platform","description":"21/03/2024","date":"2024-03-21T00:00:00.000Z","tags":[{"inline":true,"label":"Changelog","permalink":"/changelog/tags/changelog"}],"readingTime":1.52,"hasTruncateMarker":false,"authors":[{"name":"Matt Franklin","title":"Documents","url":"https://github.com/MattFranklin-Rapid","email":"matthew@rapidplatform.com","imageURL":"https://github.com/MattFranklin-Rapid.png","key":"matt","page":null}],"frontMatter":{"authors":["matt"],"tags":["Changelog"]},"unlisted":false,"prevItem":{"title":"1.38.0 - Rapid Platform","permalink":"/changelog/2024/03/26/2024-03-26-1.38 - Rapid Platform/1.38 - Rapid Platform"},"nextItem":{"title":"1.36.0 - Rapid Platform","permalink":"/changelog/2024/02/22/2024-02-22-1.36 - Rapid Platform/1.36 - Rapid Platform"}},"content":"21/03/2024\\n\\n## Features\\n\\n### Modular Rapid\\n\\nYou can now group up tables, menus and pages into logical units we call [Modules](https://docs.rapidplatform.com/docs/Rapid/Keyper%20Manual/Designer/Advanced/modules/). These modules can be toggled on/off to give more complete control over your site.\\n\\nYou can read up on how to create and manage modules [here](https://docs.rapidplatform.com/docs/Rapid/Keyper%20Manual/Designer/Advanced/modules/).\\n\\n### New and Improved Notifications interface \\n\\nThis release brings out an improvement how the [notifications](https://docs.rapidplatform.com/docs/Rapid/User%20Manual/Explorer/Notifications/) appear in Explorer. \\n\\nThe new notifications interface makes it easier to pickup the mentions and reminders from the remaining list. Prior to this release, there were no visual alerts in Explorer to notify the unread notifications. One had to access the notifications area to view the list of unread ones. \\n\\n![Notification with Alerts](<Notification Alert.png>)\\n\\nThe new notification interface will show both the header and the body (without truncating it) in the notification list itself. This brings ease of viewing the notification and reduces the time to assimilate the message.\\n\\n![Image showing comparison between old and new notifications interface with reference to header and body of notification](<Notification 5.png>)\\n\\nYou can find out more about Notifications [here](https://docs.rapidplatform.com/docs/Rapid/User%20Manual/Explorer/Notifications/)\\n\\n## Improvments\\n\\n- Adding principals in User Consent flagged sites will now update their SharePoint permissions\\n- Disabled lookups no longer disable the \'go to\' button\\n- Page save times have been dramatically improved\\n- Added mark all as read notifications button\\n\\n## Bug Fixes\\n\\n- Date columns on inherited tables will now format their values on data tables correctly\\n- Persistent forms will no longer update their prefill data on submission\\n- Fixed deleting date columns leaving trash behind\\n- Trigger Workflow menu buttons now show Date inputs correctly\\n- Prevented uploading files into the file browser creating duplicate files"},{"id":"/2024/02/22/2024-02-22-1.36 - Rapid Platform/1.36 - Rapid Platform","metadata":{"permalink":"/changelog/2024/02/22/2024-02-22-1.36 - Rapid Platform/1.36 - Rapid Platform","source":"@site/blog/2024-02-22-1.36 - Rapid Platform/2024-02-22-1.36 - Rapid Platform.md","title":"1.36.0 - Rapid Platform","description":"22/02/2024","date":"2024-02-22T00:00:00.000Z","tags":[{"inline":true,"label":"Changelog","permalink":"/changelog/tags/changelog"}],"readingTime":1.3,"hasTruncateMarker":false,"authors":[{"name":"Matt Franklin","title":"Documents","url":"https://github.com/MattFranklin-Rapid","email":"matthew@rapidplatform.com","imageURL":"https://github.com/MattFranklin-Rapid.png","key":"matt","page":null}],"frontMatter":{"authors":["matt"],"tags":["Changelog"]},"unlisted":false,"prevItem":{"title":"1.37.0 - Rapid Platform","permalink":"/changelog/2024/03/21/2024-03-21-1.37 - Rapid Platform/1.37 - Rapid Platform"},"nextItem":{"title":"1.35.0 - Rapid Platform","permalink":"/changelog/2024/02/08/2024-02-08-1.35.0 - Rapid Platform/1.35.0 - Rapid Platform"}},"content":"22/02/2024\\n\\n## Features\\n\\n### Bulk Update via Data Associations\\n\\nYou can now update a collection of items with the same value in Workflow!\\nBulk update support is achieved via the Data Association element, just like single update and creation.\\n\\nFor example:\\n![Example Project Setup Process](<Example Diagram.png>)\\n\\nSay you had a process for formally setting up a project, along with all the tasks. As part of this process is an approval stage. If the project wasn\'t approved it would be pretty tedious to shut down all the tasks. \\n\\n![Example Data Association Configuration](<Example Data Configuration.png>)\\n\\nInstead you can now use a data association to update a Data Can that fetches many items, which will then set the chosen values for each of them. Here we use the can to select all the tasks associated with the project, then set their status to Aborted to cleanly shut them down.\\n\\n## Improvements\\n\\n- Added documentation component to Explorer to display static text on a page for instructional purposes\\n- Added support to sign-up experience to link an existing site\\n- Enabled fetching an updated SharePoint token when a page has been open for more than half an hour\\n- Enabled the delete button on Views in Explorer\\n- Improved file drop handling in the File Browser component\\n- Added admin consent button into Designer\\n\\n## Bug Fixes\\n\\n- Updated DocX parser to not leak inner scoped keys to higher scopes\\n- Fixed page crash when configuring Fill Document service task\\n- Prevented File Preview component controls overlapping inner content\\n- Updated out of date integrations to no longer error on SendGrid configuration"},{"id":"/2024/02/08/2024-02-08-1.35.0 - Rapid Platform/1.35.0 - Rapid Platform","metadata":{"permalink":"/changelog/2024/02/08/2024-02-08-1.35.0 - Rapid Platform/1.35.0 - Rapid Platform","source":"@site/blog/2024-02-08-1.35.0 - Rapid Platform/2024-02-08-1.35.0 - Rapid Platform.md","title":"1.35.0 - Rapid Platform","description":"08/02/2024","date":"2024-02-08T00:00:00.000Z","tags":[{"inline":true,"label":"Changelog","permalink":"/changelog/tags/changelog"}],"readingTime":6.33,"hasTruncateMarker":false,"authors":[{"name":"Matt Franklin","title":"Documents","url":"https://github.com/MattFranklin-Rapid","email":"matthew@rapidplatform.com","imageURL":"https://github.com/MattFranklin-Rapid.png","key":"matt","page":null}],"frontMatter":{"authors":["matt"],"tags":["Changelog"]},"unlisted":false,"prevItem":{"title":"1.36.0 - Rapid Platform","permalink":"/changelog/2024/02/22/2024-02-22-1.36 - Rapid Platform/1.36 - Rapid Platform"},"nextItem":{"title":"1.34.0 - Rapid Platform","permalink":"/changelog/2024/02/01/2024-02-01-1.34.0 - Rapid Platform/1.34.0 - Rapid Platform"}},"content":"08/02/2024\\n\\n## Features\\n### 1. Hide View selection panel from a Lookup / Multi-lookup in Explorer\\n\\nThis feature relates to Lookup / Multi-Lookup column types and Table Views.\\n\\nLookups / Multi-Lookups are special types of columns. Not only they link tables with each other, at the user level (in Explorer), they provide the ability to:\\n1) View all data of linked fields\\n2) Select any data from linked fields\\n\\nThis is made possible by the ability to select / change Views while selecting a Lookup / Multi-Lookup value.\\n\\nThis can be a double edged sword. \\n\\nFor example - a Projects Item has a field - \\"Client\\". Client is a Lookup on \\"Contacts\\" Table which stores the information of all contacts for the organisation.\\n\\n![Image showing a Lookup field in Explorer](<Lookup View Side Panel 1.png>)\\n\\nClicking on the Lookup - Client field, the list of Contacts open in a dropdown. The right side provides the ability to change the view.\\n\\n![Image showing Lookup field shows values and side panel provides ability to change Views](<Lookup View Side Panel 2.png>)\\n\\nAlthough the field was meant to select a customer, a User can also view information on Suppliers / All contacts of the organisation. This can be a potential threat to confidentiality. \\n\\n:::info[New Feature]\\nThis new feature provides you with the ability to hide the View selection panel.  \\nIf the feature is set to hide the View selection panel, the user will only see results as per the default View set / Item Filter configured in Designer.  \\nThe user (in Explorer) would not be able to change the View and cannot access information from other Views.  \\n:::\\n\\n**How to hide/show Views in Lookup / Multi-Lookup**\\n\\nPlease consider the following steps:\\n\\n1. In Designer, go to your desired Table (where the subject Lookup / Multi-Lookup field is present)  \\n2. Go to Columns Tab\\n3. Select the subject Lookup / Multi-Lookup field.\\n\\n![Image showing selecting a Lookup field in Columns Tab for a Table in Designer](<Lookup View Side Panel 3.png>)\\n\\n4. Notice a new checkbox - \\"Toggle Side Panel Visibility\\"\\n\\n![Image showing Checkbox field titled Toggle Side Panel Visibility](<Lookup View Side Panel 4.png>)\\n\\n  If this field is:\\n\\n  a) Checked - it means the Side Panel to select / change Views will be absent\\n  b) Unchecked - it means the Side Panel to select / change Views will be present\\n\\n![Image showing how Toggle Side Panel checkbox works](<Lookup View Side Panel 5.png>)\\n\\n:::tip[Please note]\\n1) If you have set the default view and checked the \\"Toggle Side Panel Visibility\\" then the Lookup / Multi-lookup will show only the values as per the set default View.\\n\\n![Image showing Default View setting in column](<Lookup View Side Panel 6.png>)\\n\\n2) If no default View is mentioned on the system will take the \\"All\\" View as default and Lookup / Multi-lookup will show all values.\\n\\n![Image showing default view as blank in column](<Lookup View Side Panel 7.png>)\\n\\n3) If an Item Filter is set then the set rule will take precedence over the default View and the values in the Lookup / Multi-Lookup will be appear accordingly.\\n\\n![Image showing Item Filter in column](<Lookup View Side Panel 8.png>)\\n\\n4) The checkbox - Toggle Side Panel Visibility can be set while creating a Column as well.  \\n\\n:::\\n\\n### 2. The Rapid Signup Experience\\n\\nThis release is significant as it unveils the Rapid sign-up Experience. Users can now buy Rapid from Microsoft store. The whole sign-up experience covers the spectrum from purchasing the Rapid product from Microsoft and installing it.\\n\\nBelow are a sequence of steps to showcase the journey through sign-up.\\n\\n1. Goto https://appsource.microsoft.com/en-us/product/web-apps/rapidplatform.rapid_developer. This is the Microsoft AppSource page for Rapid Platform - Developer product.\\n![Image showing Microsoft Appsource Page for Rapid](<Signup Ex 1.png>)\\n\\n2. It is important to ascertain that your region is selected as Australia. Rapid Platform currently available for Australia region only.\\n![Image showing how to change region on AppSource](<Signup Ex 2.png>)\\n\\n  \\n3. Click \\"Get it now\\" button. There is another option - \\"Starting at Free\\". It will also initiate the same process. \\n![Image showing Get it now option](<Signup Ex 3.png>)\\n\\n4. Sign-in with your email account.\\n![Image showing sign in Page](<Signup Ex 4.png>)\\n\\n:::warning[Please note]\\nIt is possible that post sign-in your country has changed, you need to select the region as Australia again.\\n![Image showing post sign-in page with region other than Australia](<Signup Ex 5.png>)\\n:::\\n\\n5. Post Sign-in, you will see the Rapid Platform Page. Presently it shows only Developer Product, but this is where all future products will appear for selection. Click \\"Get it now\\".\\n![Image showing Get it now option](<Signup Ex 6.png>)\\n\\n6. Next you will get the Checkout Page. This is the five step process where you will asked to confirm your country, plan, billing terms (annual / monthly, recurring On / Off), your billing address, credit card details etc. \\n![Image showing checkout page](<Signup Ex 7.png>)\\n\\n7. After filling out all the details, and successfully placing the order, the last step is to configure SaaS account.\\n![Image showing successful checkout page](<Signup Ex 8.png>)\\n  \\n\\n:::info[Please note]  \\nYou will now leave Microsoft AppSource and enter Rapid Platform Sign-up Experience.  \\n:::\\n\\n8. You will be navigated to Rapid Sign-up Page. The Saas account configuration process is initiated. Welcome Rapid screen appears. You need to provide a unique account name and click Next.\\n![Image showing Welcome screen for Rapid sign in Experience](<Signup Ex 9.png>)\\n  \\n\\n:::tip[Please note]  \\nIf another account exists with your entered name, the system will prompt you to enter a unique account name.   \\n:::\\n\\n9. Next, you need to select the type of installation. If you have administrator privileges, you can select Yes. Else, for all other user types, you should select No (Limited functionality). \\n![Image showing type of installation selection screen](<Signup Ex 10.png>)\\n\\n10. As the next step, you need to provide options for configuring the SharePoint Document Storage for your account. You have two options:\\na) Provide a Team Name\\nb) Use a custom MS365 storage and document library from your existing Groups and Document Libraries.  \\n\\n![Image showing Document Storage configuration page](<Signup Ex 11.png>)  \\n\\n:::info[Please note]  \\n\\nYou can select either a) or b) as an option. If you Check the box to \\"Use a custom Microsoft 365 group ...\\", then the field to enter Team Name will be disabled. Further you can select your desired Group and Document Storage Library from Dropdowns.   \\n\\nIf this option is unchecked, then the dropdowns to Group and Document Library are disabled, and Team Name text field becomes active.  \\n:::\\n\\n11. Carefully read through all the Terms and Conditions of account creation and usage, click the checkbox and press \\"Next\\".\\n![Image showing Terms and Conditions page](<Signup Ex 12.png>)\\n\\n12. Thats it! The system will do all the Provisioning of your subject Rapid account (based on details provided) with reference to Microsoft applications. Just  click \\"Next\\" when all the three icons appear green.\\n![Image showing Microsoft Provisioning Page](<Signup Ex 13.png>)\\n\\n13. Finally the system will install your Rapid Site. Click \\"Go to site\\" when the Installing bar completes.\\n![Image showing rapid site installation page](<Signup Ex 14.png>)\\n\\n14. You will be navigated to Sign-in Page of your New Rapid Site. Login with your MS365 login credentials.\\n![Image showing Rapid Sign-in Page](<Signup Ex 15.png>)\\n\\n:::info[Congratulation]\\nYour Rapid site is ready!\\n\\n![Image showing New Rapid site](<Signup Ex 16.png>)\\n:::"},{"id":"/2024/02/01/2024-02-01-1.34.0 - Rapid Platform/1.34.0 - Rapid Platform","metadata":{"permalink":"/changelog/2024/02/01/2024-02-01-1.34.0 - Rapid Platform/1.34.0 - Rapid Platform","source":"@site/blog/2024-02-01-1.34.0 - Rapid Platform/2024-02-01-1.34.0 - Rapid Platform.md","title":"1.34.0 - Rapid Platform","description":"01/02/2024","date":"2024-02-01T00:00:00.000Z","tags":[{"inline":true,"label":"Changelog","permalink":"/changelog/tags/changelog"}],"readingTime":14.96,"hasTruncateMarker":false,"authors":[{"name":"Matt Franklin","title":"Documents","url":"https://github.com/MattFranklin-Rapid","email":"matthew@rapidplatform.com","imageURL":"https://github.com/MattFranklin-Rapid.png","key":"matt","page":null}],"frontMatter":{"authors":["matt"],"tags":["Changelog"]},"unlisted":false,"prevItem":{"title":"1.35.0 - Rapid Platform","permalink":"/changelog/2024/02/08/2024-02-08-1.35.0 - Rapid Platform/1.35.0 - Rapid Platform"},"nextItem":{"title":"1.33.0 - Rapid Platform","permalink":"/changelog/2023/11/30/2023-11-30-1.33.0 - Rapid Platform/1.33.0 - Rapid Platform"}},"content":"01/02/2024\\n\\n## Features\\n### 1. Create multiple items from within workflow.\\n\\n**A simple scenario**\\n\\nImagine an office furniture retail business. It has received an order of:\\n\\n![Image of a table showing three furniture items with details](<Table 1.png>)\\n\\nThe sales manager wants to create an invoice for the customer. The business already has an **Inv Line Items** Table. The sales manager needs to enter all the details to the **Inv Line Items** Table and then generate an invoice.\\n\\nThis new feature helps to automate the above and many such scenarios.\\n\\n**The order items can now be automatically created into invoice lines without the manager having to manually create them.**\\n\\nNow Rapid Platform can create multiple (dynamic) items in a desired table using the workflow. \\n\\n> #### **Create Items Service Task**\\n\\nThere is a new type of service task \u2013 **\u201cCreate Items\u201d**. It can enable you to create multiple items in a desired data table.\\n\\nWe will try to simulate the above scenario in the system using the Create Items service task. \\n\\nThe Create Items service task has two parameters:\\n\\n1. **Choose an entity** \u2013 you can select the desired table here, where you want the workflow to create items.\\n\\n2. **Items expression** \u2013 provide the values for the item columns here as an expression.   \\n\\n![Image showing how to configure Create Items Service Task](<Create Multiple Items 1.png>)\\n\\nThe workflow runs successfully.\\n![Image showing green task indicating the service task ran successfully](<Create Multiple Items 2.png>)\\n\\n\\nItems are created in Inv Line Items Table by the workflow execution.\\n![Image showing Explorer window of the Inv Line Items Table. It shows all the items created successfully by the workflow](<Create Multiple Items 3.png>)\\n\\n:::danger[**Please note:**]\\n\\n1. You need to provide the column name from the table and not the column title.\\n2. You can pass values to the table items using LODASH / JSON. **An example of this can be seen in the next feature.**\\n3. You can pass dynamic values to the service task, however, for the sake of simplicity, we are illustrating with static values. \\n:::  \\n\\n\\n### 2. Trigger a workflow from a menu item and pass multiple data table items as an array.\\n\\n\\n*Continuing the Office Furniture Retail business scenario*\\n\\nNow the sales manager has the Invoice line Items entered into the table automatically. However, there is a need to create an invoice for the same. \\n\\nThe need is to have multiple items into a single document.\\n\\nThis new feature will enable the user to select multiple items from a Data Table in Explorer and click a menu item to execute a workflow. The workflow execution will happen once and the data of all the items will be passed to it as an array.\\n\\nEssentially it offers the ability for a user to select multiple items from a list view, press a menu button, and for these to be available in the workflow via the start\\\\_event.\\n\\nGenerating a pdf with the selected items from Explorer can be another use case for this feature. There can be other useful applications as well.\\n\\n> #### **Workflow Execution Menu item - Single request** \\n\\n**To set up this menu item, please follow the below steps:**\\n\\n1. **Navigate to Designer.**\\n1. **Go to your desired table.**\\n1. **Click on Menu Tab.**\\n1. **Create a New Blank Menu Item.**\\n1. **Give it a name and select an icon identifier.**\\n1. **Select On-Click Action as \u201cWorkflow \u2013 Execute Process\u201d.**\\n1. **Select Location to display as \u201cTable\u201d.**\\n1. **Provide Process Diagram ID (this id is present in the url of the process diagram)**\\n1. **Toggle on \u2013 Single Request.**\\n1. **Click Save.**\\n\\n![Image showing configuration of Menu for single request](<Trigger Workflow - single 1.png>)\\n\\n:::info\\nWe have configured the menu button to call a defined workflow. This menu can be triggered from Explorer window and the system should pass the selected items from the Table in Explorer to the workflow.\\n:::\\n\\n**The menu item appears on the Data Table List view in Explorer, as configured.**\\n![Image showing how to execute menu button from Explorer. Select desired items and click on Menu button](<Trigger Workflow - Single 2.png>)\\n\\nBefore proceeding forward let us take a look at the workflow setting as well. The below image shows the workflow design. Please note we are extending illustration from previous feature, hence the use of Create Items type of Service Task.\\n  \\n![Image showing configuration of workflow that is triggered with subject menu](<Trigger workflow - Single 5.png>)\\n\\n:::danger[Please note]\\n1. The workflow being triggered via the subject menu button should always have a **Manual Start Event**. Any other type of Start Event (like Signal Start Event) would not give desired results when called via menu.  \\n\\n2. When the menu button is clicked from Explorer window, it will trigger the defined workflow. The information about the selected items shall appear in the Start Event (Workflow Results).\\n\\n3. Reference can be made to Start Event as shown in the configuration of Create Items task. Use the JSON command - ```<%= JSON.stringify(workflow[\'StartEvent_1\'].properties.items) %>```. Copy this command in the Items Expression of Create Items task. \\n\\n`JSON.stringify()` function prompts the system to consider the list of items data as a single array.\\n\\n4. Just like Create Items task shown in this example, you can configure workflow to any other task like Send Email / Fill document etc. \\n:::\\n\\n**As depicted below, upon the click of the menu, the workflow is executed once. The output of the Service Task shows three items being passed as an array.**\\n![Image showing workflow is executed and the items are passed as a single array](<Trigger Workflow - Single 3.png>)\\n\\n\\n**Upon expanding the array in the output of the service task, it is found that data for all the items (selected in Explorer) is passed properly.**\\n![Image showing workflow results of the task. The details of the selected items being successfully passed to the workflow](<Trigger Workflow - Single 4.png>)\\n\\n\\n:::warning[**Please note:**]\\n\\n**The key parameter in the menu item is Single Request (toggle). It guides the system that upon click of the subject menu item, only a single run of the defined workflow should occur. Hence, all the selected data table items data is passed as an array.** \\n:::\\n\\n### 3. Trigger a workflow from a menu item and pass multiple data table items as individual entities to the process run\\n\\n\\n*Continuing the Office Furniture Retail business scenario*\\n\\nNow the sales manager got the invoice generated automatically. He must pass on this information to the Store manager for order fulfillment. \\n\\nImagine the store has chairs in the required quantity, however, the desk and rack aren\u2019t there. The Procurement manager is intimated to place an order for these items from different vendors. \\n\\nThe Procurement manager needs to select multiple items but does not want to send it as an array to a single entity, rather to different entities.\\n\\n:::info[**Requirement**] \\nHence, the need is to select multiple items from the data table. Run the workflow process flow using the menu item, however, instead of a single run, there should be multiple runs of the process. Each process run of the workflow will have data from one (and only one) item of the data table.\\n:::\\n\\nOther use cases many include:\\n\\n1. Sending emails to a select list of customers\\n1. Sending surveys to a select list of employees\\n\\n> #### **Workflow Execution Menu item - multiple request** \\n\\nPlease note: \\n\\nTo demonstrate this new feature, we will create a new menu item. \\n\\nAll the settings will remain the same as discussed above (single request).\\n\\nThe only change \u2013 Single Request field is Toggled OFF.\\n![Image showing configuration of menu with Single Request as OFF](<Trigger Workflow - Multi 1.png>)\\n\\nThe menu item appears on the Data Table List view in Explorer, as configured.\\n![Image showing how to execute menu button from Explorer. Select desired items and click on Menu button](<Trigger Workflow - Multi 2.png>)\\n\\n\\nAs depicted below, the workflow is executed twice (as there were two items selected in the data table). The output of the Service Task shows a single item being passed per workflow execution.\\n![Image showing multiple workflow process runs with one item data per run](<Trigger Workflow - Multi 3.png>)\\n\\n   \\n\\n:::tip[**Please note:**]\\n\\n1. All the properties of triggering workflow via a menu item remains the same. For instance, passing inputs to the workflow.\\n1. In case of multiple requests, if input parameters are passed on click of the menu button, all the workflow executions will receive the same set of parameters as inputs.\\n1. Neither Single Request nor Multiple Requests do not have any practical utility if the menu button is located at the Item Level. \\n:::\\n\\n### 4. A New Column Type - **DATE**\\n\\nWe now have a new type of column in Rapid Platform. This is titled - **\\"Date\\"**.\\n\\n![Image showing new Date column type](<Date 1.png>)  \\n\\n> #### Need for this type and Difference from existing Date and Time type\\n\\nIt is important to note that we already have a Date and Time type of column. \\n\\nIn Explorer Data Table view or Item Details both \\"Date and Time\\" and \\"Date\\" type may appear to hold similar information.\\n![Image showing the similarity in appearance of values of Date and Time type and Date type in Explorer](<Date 2.png>)\\n\\nHowever, Date and Time type always stores values in full time stamp format, that is, the value will be stored in the field as date appended with time value. For example - \\"2024-01-24T06:17:58.438Z\\"\\n\\nNow, certain fields require only a date to be stored, for instance, Date of Birth, Joining Date, etc. Having a date and time does not hold relevance in such cases. \\n\\nHence, the need for the Date type. \\n\\nIn the below image, \\"date_old\\" is the Date and Time type and \\"date\\" is the new Date type of column. We can clearly observe the difference in values for two column types.\\n![Image showing the difference in Date and Time type and Date type values at database level](<Date 3.png>)\\n\\n:::warning[Important Points]\\n\\n1. Date type does not have any Relative time or Default Offset settings, unlike Date and Time type.\\n![Image comparing Date and Time type and Date type column configuration options](<Date 4.png>)\\n\\n2. At the database level, the Date type stores value in the format - YYYY-MM-DD.\\n\\n3. All the other column properties apply to the Date type like - it can be set as title column, toggle if this column can be \\"Searchable\\", toggle if the column can be \\"In All View\\", the method to add or edit the column etc.\\n\\n4. In the Explorer UI, the Date field appears with a Date Picker just like the Date and Time type. \\n![Image showing Date Picker for Date type field in Explorer](<Date 5.png>)\\n:::\\n\\n### 5. Sanitised Output file naming in Fill Document type Service Task (Docx)\\n\\nThe Fill Document type of Service Task is used to generate files from a Docx template. You can generate files which can have dynamic data sourced from specific Data Table fields. This can be used for various business purposes like automated generation of invoices, purchase orders, transaction receipts, newsletters etc.  \\n\\n> #### Need for this feature\\nIt is important to note that the output file(s) generated via the Fill Document type Service Task is placed in a SharePoint folder. \\n\\nSharePoint has general rules defining invalid characters and character sequences which should be avoided for a valid File / Folder name.\\n\\nThe below image displays the rules for invalid characters while naming a file / folder in SharePoint. To learn more - [**click here**](https://support.microsoft.com/en-us/office/restrictions-and-limitations-in-onedrive-and-sharepoint-64883a5d-228e-48f5-b3d2-eb39e07630fa?ui=en-us&rs=en-us&ad=us#invalidcharacters)\\n\\n![Image showing symbols and sequences not allowed while naming a SharePoint file / folder](<invalid symbols sharepoint file.png>)\\n\\n[Before this feature]\\nIf the user while configuring the Fill Document type Service Task workflow, named the Output file with the invalid characters, then an error appeared.\\n\\n![Image showing error generated when invalid symbols used in Output filename](<SharePoint file name old.png>)\\n\\n\\n[After this feature]\\nIf the user while configuring enter the Output file name with invalid characters, then the system will automatically sanitize the Filename by replacing the invalid character(s) with \\"_\\"\\n\\n![Image showing process success and automatic sanitization of Output File Name](<SharePoint file name new.png>)\\n\\n:::warning\\nSanitized files do not throw an error and will just happily continue on even if you don\'t expect it.\\n:::\\n\\n\\n### 6. Rapido - The AI Chatbot based on Documentation\\n\\nThis release unveils RAPIDO - Rapid Platform\'s AI Chatbot. Rapido is a GPT powered AI application that responds to user queries about how to use Rapid Platform. Rapido is trained on Rapid Platform\'s Documentation.\\n\\n**How to access Rapido?**\\n\\nYou can access Rapido from the top right corner of your Rapid environment. \\n\\n![Image showing how to access Rapido](<Access Rapido.png>)\\n\\nThis icon is present throughout the Rapid environment irrespective of the application - whether Explorer, Workflow or Designer.\\n\\nTo access Rapido, just click on the icon. This will open the Rapido interface for you to ask questions.\\n\\n![Image showing Rapido Interface](<Rapido interface.png>)\\n\\n:::tip[Collapse Rapido window]\\n\\nTo close the Rapido interface, just click on the collapse icon. \\n\\n![Image showing how to collapse Rapido Interface](<Collapse Rapido Interface.png>)\\n:::\\n\\n>\\n**What are the key elements of Rapido?**\\n\\nSuggested questions:\\n\\nTo assist users in formulating their thoughts, Rapido provides a set of three suggested questions. These questions are based upon the application from where you access Rapido - that is, Rapido will suggest different questions if you access it from Explorer, Workflow or Designer. This intends to build a bit of a context on your role.\\n\\n![Image showing suggested questions in Rapido interface](<Rapido suggestive questions.png>)\\n\\n:::tip\\nYou can click on the suggested question and Rapido will consider it as a question to answer. You do not need to type it then.\\n:::\\n\\n**Disclaimer:**\\n\\nPlease note the disclaimer (highlighted below). Because Rapido is a Chatbot, it is prone to interpretation and response faults. The links to source documentation are provided with responses, in case you wish to verify / take a closer look at the information provided.\\n\\n![Image showing disclaimer in Rapido Interface](<Rapido Disclaimer.png>)\\n\\n**Query box:**\\n\\nThis is the text area where you can type in your desired question. For example - if you wish to learn how to create a new page, just type it as shown below:\\n\\n![Image showing Query box in Rapido](<Rapido Query box.png>)\\n\\n**Submit button**\\n\\nOnce you have typed in your query in the Query box, you can click on the button to submit the query to Rapido. \\n\\n![Image showing Submit button in Rapido Interface](<Rapido submit button.png>)\\n  \\n  \\n:::tip\\nYou can press enter to submit your query text.\\n:::  \\n\\n:::info[Please note]\\n\\nThe Submit button is enable only when some text is entered in the Query box, else it is in disabled state.\\n\\n![Image showing Submit button in different states](<Rapido submit button states.png>)\\n:::\\n\\nAs you submit a query, Rapido will assimilate it and return a response.\\n\\n![Image showing Rapido responding to user query in a session](<Rapido session.png>)\\n\\n\\n**Refresh button**\\n\\nClicking on this button will refresh the chat session, clear history and bring Rapido to its initial state. \\n\\n![Image showing how to refresh a Rapido Session](<Rapido session refresh.png>)\\n\\n:::danger[Please note]\\nThe Refresh button is enabled only when your session with Rapido has at least one chat, else it remains in disabled state.\\n:::\\n\\n>\\n**Some key features of Rapido**\\n\\n1. Rapido responses provide a link to the source documentation. Should you wish to read further, you can click on the link and it will navigate you to the documentation page in a new browser tab.\\n\\n![Image showing links to source documentation](<Rapido links to documentation.png>)\\n\\n2. You can ask subsequent questions to Rapido in a session. Rapido will analyze your questions and form a context. Hence, with every new question Rapido will attempt to refine its answers smartly. \\n\\n3. There can be maximum of 8 messages (a set of 4 questions and corresponding answers) that can be held in a chat session. Once you have received 4 answers, Rapido will force you to Refresh the session to continue. (shown below)\\n\\n4. If Rapido does not know an answer to your query, it shall respond with appropriate regret response. (shown below)\\n\\n![Image showing regret message and session expiry for Rapido](<Rapido regret message.png>)\\n\\n\\n## Improvements\\n\\n- Added Explorer menu option to link directly to an Adaptive Document as a Public Form\\n- Improved Universal Link page component to display larger and more useful modal screen\\n- De-cluttered site install wizard, removing sub-site support\\n- Added toggle to generate public share links on DocX generated files\\n- Prevented Enter button from closing Explorer menu button forms\\n- Removed secondary scroll from the \'Select a Folder\' modal when configuring default folder templates on lists\\n- Improved drag handling and hit area for the File Browser\\n- Fixed out of date state being presented when viewing process runs in Explorer\\n- Improved speed and response times of Menu configuration page\\n- Added currency formatting support to DocX glyph library\\n- Added expand button to File Browser preview panel\\n- Improved typing support to Date components\\n- Improved array support in Lodash functions when using Create Items service task\\n- Enforced process runs are linked to their generating item when using the Execute Process menu action\\n\\n## Bug Fixes\\n\\n- Fixed @myGroups OData filter failing to regard groups of groups\\n- Resolved inability to toggle menu buttons to Both after selecting Table/Item\\n- Updated default link in Explorer to Workflow to respect new dashboard path\\n- Fixed cases where Send Email service tasks didn\'t\\n- Prevented a page crash when configuring Create Item service tasks\\n- Enabled the Create Item service task to regard the target table SharePoint file configuration\\n- Handled null input cases on Create Item service task\\n- Handled error cases when generating an item with a User field through the Create Item service task\\n- Prevented Correspondence Integrations items generating a second, empty key\\n- Fixed Choice fields crashing in Firefox\\n- Fixed deleting a lookup failing to clean up after itself"},{"id":"/2023/11/30/2023-11-30-1.33.0 - Rapid Platform/1.33.0 - Rapid Platform","metadata":{"permalink":"/changelog/2023/11/30/2023-11-30-1.33.0 - Rapid Platform/1.33.0 - Rapid Platform","source":"@site/blog/2023-11-30-1.33.0 - Rapid Platform/2023-11-30-1.33.0 - Rapid Platform.md","title":"1.33.0 - Rapid Platform","description":"30/11/2023","date":"2023-11-30T00:00:00.000Z","tags":[{"inline":true,"label":"Changelog","permalink":"/changelog/tags/changelog"}],"readingTime":4.38,"hasTruncateMarker":false,"authors":[{"name":"Matt Franklin","title":"Documents","url":"https://github.com/MattFranklin-Rapid","email":"matthew@rapidplatform.com","imageURL":"https://github.com/MattFranklin-Rapid.png","key":"matt","page":null}],"frontMatter":{"authors":["matt"],"tags":["Changelog"]},"unlisted":false,"prevItem":{"title":"1.34.0 - Rapid Platform","permalink":"/changelog/2024/02/01/2024-02-01-1.34.0 - Rapid Platform/1.34.0 - Rapid Platform"},"nextItem":{"title":"1.32.0 - Rapid Platform","permalink":"/changelog/2023/11/27/2023-11-27-1.32.0 - Rapid Platform/1.32.0 - Rapid Platform"}},"content":"30/11/2023\\n\\n## Features\\n\\nToken Injection and Process Interruption\\n\\n### simple scenario\\n\\nImagine a sales lead nurturing process. The workflow will:\\n\u2022 \xa0 \xa0Send newsletters, product updates every week to the lead\\n\u2022 \xa0 \xa0Every time before sending, check the lead status\\n\u2022 \xa0 \xa0If lead status = subscribed; send the material\\n\u2022 \xa0 \xa0If lead status = unsubscribed; display a form to gather reason for unsubscribing and End process.\\n\\nBefore this release, the above case (and all similar requirements) was achieved by a combination of a Timer Intermediate Catch Event and an Exclusive gateway.\\n\\n![Timer with gateway](<Timer with Gateway.png>)\\n\\n#### The problem with above solution\\n\\nThe Timer Intermediate Catch Event can only be configured to:\\n\\n- A specific point in time\xa0\\n- A duration of delay\\n\\nImagine the user who received a newsletter on a Tuesday. Upon receipt the Unsubscribe button was pressed. But the workflow will only check for the status next week. Till then the process token remains active.\\n\\n\\n#### Token injection and process interruption\\n\\nThis release introduces a new type of Intermediate event \u2013 _The Signal Intermediate Catch Event_.\\n\\n![Intermediate Catch Event](<Intermediate Catch Event.png>)\\n\\nThere are three fields which will help to configure the nature of this event:\\n1. Choose a table \u2013 select the required table from the list. This a mandatory field.\\n2. Conditional Expression \u2013 to provide the condition to be checked on a column value of the selected table. This is an optional field.\\n3. Interrupting signal \u2013 YES / NO \u2013 When turned YES, and the nature of the event becomes interrupting, else it remains non-interrupting.\\n\\nAs the name suggests, this event is capable of:\\n- Injecting a new token in the workflow process\\n- Interrupt the existing process (kill all existing tokens)\\n\\n**What does it mean?**\\n\\nThe Signal Intermediate Catch Event gets triggered when:\\n1. an item is updated on the selected table (Default case - if the Conditional Expression is left empty)\\n\\nOR\\n\\n2. an item is updated on the selected table AND the defined condition on the relevant column value is met.\xa0\\n\\nConsidering our previous scenario, as soon as the lead Status turns \u201cUnsubscribed\u201d, this event will be triggered (if configured properly). Triggering of the event will generate a new token and the workflow will proceed forward from the subject intermediate event. Hence, token injection at the point in workflow where intermediate event is present, when the defined condition is met.\\n\\nFurther, if the \u201cInterrupting Signal\u201d field is set to YES, it means that as soon as the subject intermediate event is triggered, all the existing active tokens will be terminated. The only active token in the process will be the one injected by the intermediate event.\xa0\\n\\n![Triggered Interrupting Catch Event](<Triggered Interrupting Catch Event.png>)\\n\\nWhen the intermediate event interrupts the existing process, the symbol (where the token was present at the time of interruption) will turn grey as seen above.\\n\\nWhen the intermediate event is triggered but does not interrupt the existing process, then all the tokens \u2013 i.e. the ones prior to triggering of intermediate event AND the one created by intermediate event trigger remain active in the process.\\n\\n![Triggered Catch Event](<Triggered Catch Event.png>)\\n\\nAnother scenario\\n\\nImagine a company has a five-stage procurement process:\\n\\n- Stage 1 - identifying the need for a product or service\\n- Stage 2 - conducting research and gathering information about potential vendors\\n- Stage 3 - submitting requests for proposals or quotes\\n- Stage 4 - evaluating proposals and selecting a vendor\\n- Stage 5 - finalizing and executing a contract\\n\\nThe process is sequential in nature. However, in certain situations, it may be necessary to bypass a stage in order to expedite the procurement process.\\n\\nFor example, if the company has a pre-existing relationship with a vendor and has already conducted extensive research on their products or services, they may choose to bypass Stage 2 and go directly to Stage 3 to request a quote or proposal.\\n\\nAlternatively, if the procurement process is taking longer than expected and the need for the product or service is urgent, the company may choose to bypass Stage 3 and go directly to Stage 4 to select a vendor and negotiate a contract.\\n\\nWith the introduction of new **Signal Intermediate Catch Event**, the workflow diagram may appear as shown below:\\n\\n![Multiple injection points](<Multiple injection points.jpeg>)\\n\\nIf the intermediate event(s) are set as interrupting, then in the episode of a stage bypass, the existing token would be killed and the process will advance from the next relevant stage.\\n\\n## Bug Fixes\\n\\n- Fixed feature level permissions getting confused between being on or off\\n- Ensured restarting a process with an errored data association no longer fails to restart\\n- User fields in Explorer will no longer mark the go-to user button as disabled\\n- Fixed choice field fly-outs being random sizes depending on configuration\\n- Exit intent no longer tries to fire when deleting an item\\n- Configuring email communication activities in Workflow will no longer fail if the Principals view is missing columns\\n- Rolling back to the start of a process run will no longer drop input or signal context\\n\\n## Improvements\\n\\n- Added v3 Adaptive document routing to Public Forms in preparation of release\\n- Prevented unconfigured data cans from being flagged as errored\\n- Process runs are now marked as completed when they have no active tokens\\n- Added copy behaviour to ledger content in Explorer\\n- Ensured the Delete Entity button doesn\'t randomly disappear"},{"id":"/2023/11/27/2023-11-27-1.32.0 - Rapid Platform/1.32.0 - Rapid Platform","metadata":{"permalink":"/changelog/2023/11/27/2023-11-27-1.32.0 - Rapid Platform/1.32.0 - Rapid Platform","source":"@site/blog/2023-11-27-1.32.0 - Rapid Platform/2023-11-27-1.32.0 - Rapid Platform.md","title":"1.32.0 - Rapid Platform","description":"27/11/2023","date":"2023-11-27T00:00:00.000Z","tags":[{"inline":true,"label":"Changelog","permalink":"/changelog/tags/changelog"}],"readingTime":8.48,"hasTruncateMarker":false,"authors":[{"name":"Matt Franklin","title":"Documents","url":"https://github.com/MattFranklin-Rapid","email":"matthew@rapidplatform.com","imageURL":"https://github.com/MattFranklin-Rapid.png","key":"matt","page":null}],"frontMatter":{"authors":["matt"],"tags":["Changelog"]},"unlisted":false,"prevItem":{"title":"1.33.0 - Rapid Platform","permalink":"/changelog/2023/11/30/2023-11-30-1.33.0 - Rapid Platform/1.33.0 - Rapid Platform"},"nextItem":{"title":"1.31.1 - Rapid Platform","permalink":"/changelog/2023/11/02/2023-11-02-1.31.1 - Rapid Platform/1.31.1 - Rapid Platform"}},"content":"27/11/2023\\n\\n## Features\\n\\nWe are proud to announce five new features being released today.\\n\\n### Search field for Boards component\\n\\nA search box is added to the KanBan Boards component. This can be used to search items on the Board based on provided keyword(s). The behaviour is identical to the Search items field already present in Data Table List.\\n\\n**Benefit:**\\nThis feature is useful in filtering and finding items easily on the Board.\\n\\nPlease refer to the video below for illustration on how this new field can be used to search Tasks on a Board:\\n\\n<iframe title=\\"YouTube video player\\" src=\\"https://www.youtube.com/embed/Rxly3fTtIhg?si=kz0_HKky1gEnrznR\\" width=\\"750\\" height=\\"420\\" frameborder=\\"0\\" allowfullscreen=\\"allowfullscreen\\"></iframe>\\n\\n## Set default value of User Type field to current user\\n\\nIf in a Data Table, you have a User Type column, you can now set its **Default Value to the current user**. Therefore, if User 1 is creating an Item, then the default value of the User column will be User 1; if User 2 is creating an Item, then the default value will appear as User 2.\\n\\n**Benefit:**\\nThis feature is particularly useful in reducing effort where the current user had to repeatedly select oneself while creating items.\\n\\nThe default value can be set using the following steps:\xa0\\n\\n- Navigate to Designer->Desired Table->Columns Tab->Desired User column.\\n- Goto Default Value field.\\n- Click \\"Assign to Me\\"\\n- The Value \\"@me\\" appears in the field indicating it is set to current user as default.\\n\\nPlease refer to the below video for illustration:\\n\\n<iframe title=\\"YouTube video player\\" src=\\"https://www.youtube.com/embed/tqebQygjw3Q?si=P_zxya2D6pu5tXhl\\" width=\\"750\\" height=\\"420\\" frameborder=\\"0\\" allowfullscreen=\\"allowfullscreen\\"></iframe>\\n\\n## Create Item Service Task\\n\\nYou can now generate items for an entity from within the Workflow. This means (for example) when this service task gets executed, it will add an item with defined field values to the Data Table.\\n\\n**Benefit:**\\nThis is particularly useful in reducing effort spent on creating items by configuring User Tasks, Flows etc. The values of the field can be controlled from within the workflow.\\n\\nYou can pass both static values, as well as, Lodash expressions to the field.\\n\\n![Cerate item service task](<Create item service task.png>)\\n\\n\\nThe UI is consistent with Data Association.\\n\\nTo configure Create Item Service Task:\\n\\n1. Select Create Item in Service Task\\n2. Select entity\\n3. Click +Add Field\\n4. Select desired field - the system will display all the fields from the selected entity.\\n5. Provide Value to the selected field.\\n\\nPlease refer to the below video for illustration:\\n\\n<iframe title=\\"YouTube video player\\" src=\\"https://www.youtube.com/embed/5lCFqC4kfIs?si=_HS0rS-emRvUoVHz\\" width=\\"750\\" height=\\"420\\" frameborder=\\"0\\" allowfullscreen=\\"allowfullscreen\\"></iframe>\\n\\n## Timer Start Events\\n\\nA new type is unlocked for Start Events - the Timer Start Event. You can now configure Timer Start Events in Workflow to have your processes start on a regular cadence.\\n\\n![Timer start event](<Timer start event.png>)\\n\\n**Benefit:**\\nThis is particularly useful when you need a workflow to trigger at a specific time period. For example - an HR manager may want the appraisal cycle to trigger on 1st of March every year.\xa0\\n\\nTimers are configured using the frequency picker but can also be configured with regular cron expressions.\\n\\n![Timer CRON configuration](<Timer CRON configuration.png>)\\n\\n**Fields for Time Start Event:**\\nA time period can be viewed as a hierarchy of units\\n\\n- Year\\n- Month\\n- Week\\n- Day\\n- Hour\\n- Minute\\n\\nThe first field (_Every_) is used to define the frequency and the remaining lower fields are used to defined the exact point(s) on time period when the workflow should be triggered.\xa0\\n\\nFor example - Every Month - defines that the workflow will be triggered every month.\xa0\\n\\nThe lower fields are used to define on which day of the month / week - e.g. 1st of every month and every Sunday of the month.\\n\\nFurther going down the hierarchy of time units, you can define what time of the day - e.g. 9 :15 am\\n\\nTherefore you can define the exact frequency and time when the workflow will be triggered.\xa0\\n\\nBased on the value selected for the first field (Every) the lower fields are displayed for definition.\\n\\n\\n*Please note, if a field is not manually set, its default value is set to single unit. For example: if you have left the minute field blank, the workflow will be triggered every one minute.* \\n\\n\\n### Displaying defined information\\n\\nBased on the definition of frequency, the system will interpret and display the frequency as an English statement.\xa0\\n\\n![CRON tester single example](<CRON tester single example.png>)\\n\\nFurther, the system also displays a schedule for all the future runs of the workflow at the defined frequency (in batches of 5).\\n\\n![CRON tester multi example](<CRON tester multi example.png>)\\n\\nIn case the set frequency is a non achievable case - For example - 31st February, then the schedule will display **N/A**.\\n\\nPlease refer to the below video for illustration:\\n\\n<iframe title=\\"YouTube video player\\" src=\\"https://www.youtube.com/embed/xEGekDGts0w?si=noOWB_nIrGaPD_m5\\" width=\\"750\\" height=\\"420\\" frameborder=\\"0\\" allowfullscreen=\\"allowfullscreen\\"></iframe>\\n\\n## Trigger a specific workflow from a Menu button\\n\\nYou can now configure a Menu button to trigger a desired workflow from within Command Bar of the Explorer Item. There is a new option in the \\"On-Click Action\\" dropdown for Menu. It is titled - \\"Workflow - Execute Process\\".\\n\\n:::tip[Benefit:]\\nPrior to this feature, a Menu button could trigger a Workflow using the \\"On-Click Action\\" as \\"Raise Workflow Created Signal\\". A click on such a Menu button throws the Signal and **all the workflows** with relevant Trigger Start Events would get triggered with this.\\n:::\\n\\nThe subject feature is useful, when you do not want all the workflows to get triggered rather a very specific one.\\n\\nTherefore, this makes it very similar to manually pressing the \\"Launch\\" button from within the workflow, however, this time from within the Explorer.\xa0\\n\\nFurther, you can also pass inputs from Explorer to the subject Workflow. (discussed later as Part II)\\n\\nTo configure the menu button:\\n\\n1. Navigate to / create the desired Menu in Designer\\n2. Select On-Click Action as \\"Workflow - Execute Process\\"\\n3. Enter the Process Diagram ID - The process diagram id is present on the url of the process diagram.\\n\\nFor example - https://test.rapidplatform.com/rapidplatform/example/workflow/diagrams/**91**/edit\\n\\nIn the above URL - 91 is the Process ID.\xa0\\n\\n:::[Please note:] The workflow that you want to trigger from the Menu button triggers with any type of Start Event (normal / Signal / Timer). The Menu behaves like a manual Launch of the workflow process.\\n:::\\n\\nPlease refer to the below video for illustration:\\n\\n<iframe title=\\"YouTube video player\\" src=\\"https://www.youtube.com/embed/oKvHHFbSqW4?si=rN5S7ryTx6DiwukV\\" width=\\"750\\" height=\\"420\\" frameborder=\\"0\\" allowfullscreen=\\"allowfullscreen\\"></iframe>\\n\\n### PART II - Dynamic inputs\\nThis new feature also allows you to pass inputs to the Workflow from Explorer when the Menu button is clicked.\xa0\\n\\nTo achieve this you need to configure the Workflow\'s Process Input section. \xa0\\n\\n![Workflow input configuration](<Workflow input configuration.png>)\\n\\nWhen you configure an Input field in the Process Inputs section, this enables you to provide a user input value at the time of manually triggering the Workflow from the Menu button.\\n\\n**A special case:**\xa0\\nIn case you have:\xa0\\n- configured a Lookup type of Input field in the Process Input section, AND\\n- the Lookup is on the field of the same table where you have configured the menu button, AND\\n- the menu button is displayed on Item Level\xa0\\n\\nThen the system will pickup the Title field value from the subject Item and pre-fill the same in the Input field. This still remains editable, if you wish to manually change the value that gets passed to the Workflow.\\n\\nPlease refer to the image below for illustration:\xa0\\n\\n![Inputs affecting button forms](<Inputs affecting button forms.png>)\\n\\n## Bug Fixes\\n\\n- Fixed popup not closing when clicking off a task entry in explorer with an embedded file selected\\n- Fixed multi-lookup and scoped-link fields failing to render correctly\\n- Repairing sites no longer overrides the primary group\\n- Fixed the titles not wrapping correctly when viewing the cards in the board component\\n- Fixed the logo header in the task experience to match branding guidelines\\n- Fixed email field not being greyed out when write permissions are turned off\\n- Fixed media queries incorrectly applying at the correct screen size\\n- Feature level permissions no longer apply when disabled\\n- UTF8 and UTF16 characters now render correctly in public forms\\n- Deleting a site no longer leaves the database intact\\n- Viewing an Adaptive Documents item in explorer no longer references a non existent column\\n- Loading spinner no longer aligned with the select all toggle when loading a data table\\n- Loading spinner no longer spins indefinitely when creating a new site\\n- Clicking on Workflow in the explorer menu no longer returns a 404 page not found error\\n- Fetching a sub-type of task that already had estimated_time value, no longer returned as an array\\n- Can create and update public forms with site and task id\\n- Manually triggering a process diagram with a signal start event now gives you full item results in the output\\n- Lookups on Workflow execution forms now fetch lookups\\n- Single embedded file component no longer adds a second file when another file is uploaded\\n- Set multiple item data cans to green completed when they fetch successfully\\n- Fixed the Board component not being able to fetch needed columns if the selected view was missing them\\n\\n## Improvements\\n\\n- Added a confirmation modal in Workflow to prevent accidentally rolling back processes\\n- Embedded files preview panel updated to current design\\n- UI now maximizes the use of available screen space in page designer\\n- Removed illegal characters in DocX template names\\n- Adjusted the width of the Delete Entity pane\\n- Added buttons to toggle \\"use created\\" for the Drive and Folder ID\'s when configuring a new Embedded File\\n- Configuring page layouts are now displayed at a more appropriate size\\n- Adaptive Designer styling now matches the new branding\\n- Added search box to board component\\n- Added webhook trigger type to post webhook options\\n- File template configuration input fields now have added spacing\\n- Can now trigger a Workflow from a menu item\\n- Can now delete Embedded Files\\n- Added menus page in Designer and moved all list level menus out of the menu"},{"id":"/2023/11/02/2023-11-02-1.31.1 - Rapid Platform/1.31.1 - Rapid Platform","metadata":{"permalink":"/changelog/2023/11/02/2023-11-02-1.31.1 - Rapid Platform/1.31.1 - Rapid Platform","source":"@site/blog/2023-11-02-1.31.1 - Rapid Platform/2023-11-02-1.31.1 - Rapid Platform.md","title":"1.31.1 - Rapid Platform","description":"2/11/2023","date":"2023-11-02T00:00:00.000Z","tags":[{"inline":true,"label":"Changelog","permalink":"/changelog/tags/changelog"}],"readingTime":3.72,"hasTruncateMarker":false,"authors":[{"name":"Matt Franklin","title":"Documents","url":"https://github.com/MattFranklin-Rapid","email":"matthew@rapidplatform.com","imageURL":"https://github.com/MattFranklin-Rapid.png","key":"matt","page":null}],"frontMatter":{"authors":["matt"],"tags":["Changelog"]},"unlisted":false,"prevItem":{"title":"1.32.0 - Rapid Platform","permalink":"/changelog/2023/11/27/2023-11-27-1.32.0 - Rapid Platform/1.32.0 - Rapid Platform"},"nextItem":{"title":"1.31.0 - Rapid Platform","permalink":"/changelog/2023/10/12/2023-10-12-1.31.0 - Rapid Platform/1.31.0 - Rapid Platform"}},"content":"2/11/2023\\n\\n## Features\\n\\n### Menu action templating\\n\\nYou can now use template strings in the open Hyperlink menu action, just like input field hyperlinks. We have also added three new parameters for templates to be aware of which server you are on.\xa0\\n\\n| Parameter | Result |\\n| --- | --- |\\n| env | Either \'test\' or \'prod\' |\\n| tenant | The current tenant |\\n| site | The current site |\\n\\nFor example, you could create a link that goes to the correct tasks experience for the current site like so:\\n\\n`http://tasks.rapidplatform.<%= env!=\\"prod\\" ?\\"com/_test\\" : \\"com/_prod\\"%>/<%=tenant%>/<%=site%>`\\n\\n### HTML sanitize lodash function\\n\\nWhen you have a textual input that contains HTML glyphs such as  or you can now invoke a built in lodash function to strip out these glyphs. For example, to remove the glyphs from a User Task description field would be like so:\\n\\n`<%=htmlToText(UserTask_0ak37ta.properties.description)%>`\\n\\n### Default Embedded Files\\n\\nContinuing our learnings from template files, you can now configure at the table level a default embedded file definition. These default definitions can either point at the current item (and generate a folder as required) or a statically defined target folder in SharePoint. You can find the configuration in the newly reorganized Options tab when configuring a table.\\n\\n### Trigger on Change\\n\\nYou can configure Webhooks and Workflow Signal Events to conditionally trigger when one or more columns are updated. the changed() function now returns true or false if the indicated column is different from before it was updated.\\n\\nFor example, you could configure a Signal Event to trigger when an Invoice is marked as Voided like so:\\n\\n![Changed condition in trigger event](<Changed condition in trigger event.png>)\\n\\nHere the process will only trigger if both the status was changed, and if it was changed to \'VOIDED\'.\\n\\nThe syntax for changed is:\\n\\n`changed(\'column_name\')`\\n\\n### Workflow Element Coalescing\\n\\nFor those of you working with multiple branching paths in Workflow that need to reference something that could have been created on one of them, you can now reference elements in lodash regardless if they have been executed.\\n\\nThis is best demonstrated with an example, consider this process:\\n\\n![Workflow collapsing to a single task](<Workflow collapsing to a single task.png>)\\n\\nThis process could optionally start from three difference causes; either manually with an input, or triggered via a create or update signal. The AllField data can now references whatever the starting item is and collapses the trigger item into a single place to easily reference throughout the document. The syntax to configure this can is;\\n\\n`<%= inputs?.all_field?.id ?? StartEvent_1?.properties?.id ?? StartEvent_0wzx24k?.properties?.id %>`\\n\\nPreviously trying to reference StartEvent_1 or StartEvent_0wzx24k would throw an error as only one existed. This has been resolved.\\n\\nOutside of starting situations, you can also collapse something created in a branching path for later referencing. Again a Data Can is used here but is not required. The Task can references the single letter task that was chosen (A, B or C) so that it can be reviewed in the Combine task. For completeness the syntax in the Task can is:\\n\\n`<%= inputs?.all_field?.id ?? StartEvent_1?.properties?.id ?? StartEvent_0wzx24k?.properties?.id %>`\\n\\n## Bug Fixes\\n\\n- Prevented tab freeze when configuring pages in Designer under certain conditions\\n- Stopped Table search being case sensitive\\n- Disabled and removed public forms where the task has been completed in all cases\\n- Fixed UI failing to react when clearing / updating template folder configuration\\n- Enabled attachments to be added via drag-n-drop regardless of file type\\n- Fixed daylight savings time being regarded for Public Form submission timeout\\n- Prevented page crash when closing the \'Add to form\' panel in Designer on a table with >30 columns\\n\\n## Improvements\\n\\n- Upgraded styling on required fields in Explorer for readability\\n- Improved Rich Text area styles when disabled to display as rich text instead of HTML\\n- Added time to notes in the Activity feed\\n- Added 401 page when navigating to experiences where the user is not allowed\\n- Added collapse mode to workflow configuration panel (and stopped it popping out on click!)\\n- Put back the Users\' displayed email in User fields\\n- Added Estimated time and On Hold status to Tasks, removed Failed status\\n- Added support for principal unique ID in workflow user task configuration\\n- Added default pages for Workflow Folders system list\\n- Added feedback when uploading a process diagram using the new creation panel\\n- Added Excel Date column when exporting data for better date consistency between locales\\n- Added Multi-Lookup update/replacement support into Public Forms and API requests\\n- Upgraded Tasks, Designer and the Login screens to match the new branding"},{"id":"/2023/10/12/2023-10-12-1.31.0 - Rapid Platform/1.31.0 - Rapid Platform","metadata":{"permalink":"/changelog/2023/10/12/2023-10-12-1.31.0 - Rapid Platform/1.31.0 - Rapid Platform","source":"@site/blog/2023-10-12-1.31.0 - Rapid Platform/2023-10-12-1.31.0 - Rapid Platform.md","title":"1.31.0 - Rapid Platform","description":"12/10/2023","date":"2023-10-12T00:00:00.000Z","tags":[{"inline":true,"label":"Changelog","permalink":"/changelog/tags/changelog"}],"readingTime":3.22,"hasTruncateMarker":false,"authors":[{"name":"Matt Franklin","title":"Documents","url":"https://github.com/MattFranklin-Rapid","email":"matthew@rapidplatform.com","imageURL":"https://github.com/MattFranklin-Rapid.png","key":"matt","page":null}],"frontMatter":{"authors":["matt"],"tags":["Changelog"]},"unlisted":false,"prevItem":{"title":"1.31.1 - Rapid Platform","permalink":"/changelog/2023/11/02/2023-11-02-1.31.1 - Rapid Platform/1.31.1 - Rapid Platform"},"nextItem":{"title":"1.30.14 - Folder Templates","permalink":"/changelog/2023/08/31/2023-08-31-1.30.14 - Rapid Platform/1.30.14 - Rapid Platform"}},"content":"12/10/2023\\n\\n## Features\\n\\n### UI Styling Upgrade\\n\\nRapid Platform System Upgrades\\n\\nFollowing Rapid Platform\'s branding upgrade, Explorer, Designer and Workflow have gotten a facelift. This includes a change to routes for Designer and Workflow\\n\\n| Previously | Now |\\n| --- | --- |\\n| `/{tenant}/{site}/Dezigna` | `/{tenant}/{site}/Designer` |\\n| `/{tenant}/{site}/Compoza` | `/{tenant}/{site}/Workflow` |\\n\\n\\n### Authorized Forms\\n\\nIt is now possible to configure an authenticated public form. Configuring a form to be authorized will require the user to put in a predetermined, generated password before proceeding to the form. It is possible to set auth from workflow and have a password be generated or manually. 2 new columns were added to the tasks table to allow for this. \\n\\n### Custom Users and Minimal Install\\n\\nPrincipals can now be created manually. \\n\\nIn our continued quest to make Rapid as flexible as possible you can now install a limited version without requiring application consent. This change alters the install mechanism to not require SharePoint or Groups access. This will install a site with the creating user only. In order to enable inviting users you can now create principal records to manually create both users and groups.\\n\\nWhen adding a new User the only required information is an email address. This will try to match the User on your active directory (if access is granted) and backfill details when available. Any user that can authenticate to your tenant that have a matching email address to a User in the site will now be able to login.\\n\\nTo help manage membership in cases when groups are not accessible, you can now manually add & remove principals to groups using the command bar. You can view the membership using the Principals tab on a group, with a plan to build a custom membership control at a later stage.\\n\\nSites created with no application permissions will have reduced functionality, notably around files and emails.\\n\\n### Added pipeline page control\\n\\nIt is now possible to add the pipeline control to a page layout in legacy designer, this will allow the connection to a choice field and will display that choice field in a tasteful way as a method of describing progress.\\n\\n### New fetching query parameters\\n\\nWith the development of Adaptive v3, additional query parameters have been added to fetch lists of items based around their link relationships. Check the API Concepts page for further details.\\n\\n## Bug Fixes\\n\\n- Prevented page crash when configuring a Trigger a Webhook service task\\n- Fixed \'Failed to Load\' race condition on Explorer components when refreshing a page\\n- Squashed Resize Observer error in console\\n- Prevented erroneous error being reported when timers return to a deleted process run or diagram\\n- Fixed conditions failing to fire in Adaptive Designer when configuring connections\\n- Stopped menu actions with a form from sending the request on blur or when cancelled\\n- Fixed site repairs with more than 700 principals failing to complete\\n- Fixed selected items in multi-lookup fields failing to display as ticked\\n- Fixed quick search on data tables failing to react after opening an item on the list\\n- Saving in the Tasks experience without document storage set up no longer fails\\n- Prevented command bar action buttons from sending when pressing cancel\\n\\n## Improvements\\n\\n- Ensured Preform Remote Action menu items always send\\n- Made the group picker optional when installing a site\\n- Removed extraneous padding on new lines in multi-line text fields\\n- Added route to fetch Principals based on their membership\\n- Wide sweeping CSS upgrades and library updates throughout UI-React\\n- Ensured page creation state is not re-rendered until after an item is fully created\\n- Improved table scoped command bar actions to respect all possible configurations\\n- Added Choice pipeline component\\n- Upgraded cascading lookup configuration in Designer to be able to regard full query logic\\n- Added Pages page in Designer to manage the pages on the site\\n- Added manual override control for Prefill data configuration in Workflow user tasks\\n- Styled 404 and 403 pages"},{"id":"/2023/08/31/2023-08-31-1.30.14 - Rapid Platform/1.30.14 - Rapid Platform","metadata":{"permalink":"/changelog/2023/08/31/2023-08-31-1.30.14 - Rapid Platform/1.30.14 - Rapid Platform","source":"@site/blog/2023-08-31-1.30.14 - Rapid Platform/2023-08-31-1.30.14 - Rapid Platform.md","title":"1.30.14 - Folder Templates","description":"31/08/2023","date":"2023-08-31T00:00:00.000Z","tags":[{"inline":true,"label":"Changelog","permalink":"/changelog/tags/changelog"}],"readingTime":1.14,"hasTruncateMarker":false,"authors":[{"name":"Matt Franklin","title":"Documents","url":"https://github.com/MattFranklin-Rapid","email":"matthew@rapidplatform.com","imageURL":"https://github.com/MattFranklin-Rapid.png","key":"matt","page":null}],"frontMatter":{"authors":["matt"],"tags":["Changelog"]},"unlisted":false,"prevItem":{"title":"1.31.0 - Rapid Platform","permalink":"/changelog/2023/10/12/2023-10-12-1.31.0 - Rapid Platform/1.31.0 - Rapid Platform"},"nextItem":{"title":"1.30.13 - Adaptive Bug Fixes","permalink":"/changelog/2023/08/17/2023-08-17-1.30.13 - Rapid Platform/1.30.13 - Rapid Platform"}},"content":"31/08/2023\\n\\n## Features\\n\\n### Folder Templates\\n\\nThrough Designer, it is possible to now configure a folder to use as a template for a particular list. If configured, when creating an item when the \'always create folder is enabled\', the contents of the folder will be set on that item. For existing items, the folder will be cloned when creating a new folder for the item through the UI.\\n\\n### URL Parameter for universallyLinkedTo\\n\\nLike the LinkedTo param, putting this in a get Items request from RAPID will return any items for the specified list that are universally link to the specified item, this will not return scoped universal links.\\n\\n## Bug Fixes\\n\\n- Fixed an issue where lists cannot be deleted due to since deleted lookup fields\\n- Prevented page crash on Workflow when viewing malformed sequence flows\\n- Fixed files component in Public Forms failing to upload a file when within a child connection\\n\\n## Improvements\\n\\n- Added a suite of Workflow Integration tests\\n- Added the IN Odata query operator, using the following syntax `IN(column name,value1,value2)`\\n- Added toggle on Perform Remote Action menu items to send a batch request instead of individuals\\n- Added default filter to Adaptive Designer when selecting a document to not regard apps\\n- Hide the execute diagram button if a non-executable diagram is opened\\n- Improved UI for configuring cascading lookups\\n- Cascading lookups now use OData filters"},{"id":"/2023/08/17/2023-08-17-1.30.13 - Rapid Platform/1.30.13 - Rapid Platform","metadata":{"permalink":"/changelog/2023/08/17/2023-08-17-1.30.13 - Rapid Platform/1.30.13 - Rapid Platform","source":"@site/blog/2023-08-17-1.30.13 - Rapid Platform/2023-08-17-1.30.13 - Rapid Platform.md","title":"1.30.13 - Adaptive Bug Fixes","description":"17/08/2023","date":"2023-08-17T00:00:00.000Z","tags":[{"inline":true,"label":"Changelog","permalink":"/changelog/tags/changelog"}],"readingTime":0.14,"hasTruncateMarker":false,"authors":[{"name":"Matt Franklin","title":"Documents","url":"https://github.com/MattFranklin-Rapid","email":"matthew@rapidplatform.com","imageURL":"https://github.com/MattFranklin-Rapid.png","key":"matt","page":null}],"frontMatter":{"authors":["matt"],"tags":["Changelog"]},"unlisted":false,"prevItem":{"title":"1.30.14 - Folder Templates","permalink":"/changelog/2023/08/31/2023-08-31-1.30.14 - Rapid Platform/1.30.14 - Rapid Platform"},"nextItem":{"title":"1.30.12 - Workflow Rollback","permalink":"/changelog/2023/07/20/2023-07-20-1.30.12 - Rapid Platform/1.30.12 - Rapid Platform"}},"content":"17/08/2023\\n\\n## Bug Fixes\\n\\n- Fixed an issue where editing a prefilled multi line text field would sometimes clear\\n\\n## Improvements\\n\\n- Added the ability to theme the login screen"},{"id":"/2023/07/20/2023-07-20-1.30.12 - Rapid Platform/1.30.12 - Rapid Platform","metadata":{"permalink":"/changelog/2023/07/20/2023-07-20-1.30.12 - Rapid Platform/1.30.12 - Rapid Platform","source":"@site/blog/2023-07-20-1.30.12 - Rapid Platform/2023-07-20-1.30.12 - Rapid Platform.md","title":"1.30.12 - Workflow Rollback","description":"20/07/2023","date":"2023-07-20T00:00:00.000Z","tags":[{"inline":true,"label":"Changelog","permalink":"/changelog/tags/changelog"}],"readingTime":1.35,"hasTruncateMarker":false,"authors":[{"name":"Matt Franklin","title":"Documents","url":"https://github.com/MattFranklin-Rapid","email":"matthew@rapidplatform.com","imageURL":"https://github.com/MattFranklin-Rapid.png","key":"matt","page":null}],"frontMatter":{"authors":["matt"],"tags":["Changelog"]},"unlisted":false,"prevItem":{"title":"1.30.13 - Adaptive Bug Fixes","permalink":"/changelog/2023/08/17/2023-08-17-1.30.13 - Rapid Platform/1.30.13 - Rapid Platform"},"nextItem":{"title":"1.30.11 - SendGrid support in User Tasks","permalink":"/changelog/2023/07/06/2023-07-06-1.30.11 - Rapid Platform/1.30.11 - Rapid Platform"}},"content":"20/07/2023\\n\\n:::warning\\nBreaking Change - API user webhook control\\n\\nA new query parameter has been added to POST/PUT requests called webhooks. When true requests will trigger webhook events to fire, when false it will prevent them. This new parameter is assumed to be true for normal requests, but is assumed to be false for Application User requests. \\n\\nAll requests made by application users that require webhook events to fire will need to add webhooks=true\\n:::\\n\\n## Features\\n\\n### Rollback support in Workflow\\n\\nWhile viewing a process run in Workflow you can now select a previously executed element and revert the run back in time to there. For example, selecting a User Task will roll back the process to just prior re-creating the task. Rolling back a process will abort existing tasks and timers to help clean up.\\n\\n## Bug Fixes\\n\\n- Fixed resuming unconfigured data associations erroneously failing\\n- Fixed page crash when configuring some condition cases in Adaptive Designer\\n- Re-enabled success toast on items in Explorer\\n- Enabled the disable deletion configuration to persist through refresh\\n- Refreshed page set when navigating between different Tasks sites\\n- Fixed attachment records failing to refresh when navigating between different tasks in the Tasks experience\\n- Improved reactivity when uploading attachments in the Tasks experience\\n\\n## Improvements\\n\\n- Ensured site details (environment, tenant, site) are on menu action requests\\n- Added concurrency support for resumes in workflow\\n- Added Embedded File column support in data tables for Explorer\\n- Improved performance on lists that contain multi-lookup fields\\n- Added error message reflection to UI when service tasks fail in Workflow\\n- Enforced currency formatting in data tables to be 2 decimal places"},{"id":"/2023/07/06/2023-07-06-1.30.11 - Rapid Platform/1.30.11 - Rapid Platform","metadata":{"permalink":"/changelog/2023/07/06/2023-07-06-1.30.11 - Rapid Platform/1.30.11 - Rapid Platform","source":"@site/blog/2023-07-06-1.30.11 - Rapid Platform/2023-07-06-1.30.11 - Rapid Platform.md","title":"1.30.11 - SendGrid support in User Tasks","description":"6/07/2023","date":"2023-07-06T00:00:00.000Z","tags":[{"inline":true,"label":"Changelog","permalink":"/changelog/tags/changelog"}],"readingTime":0.82,"hasTruncateMarker":false,"authors":[{"name":"Matt Franklin","title":"Documents","url":"https://github.com/MattFranklin-Rapid","email":"matthew@rapidplatform.com","imageURL":"https://github.com/MattFranklin-Rapid.png","key":"matt","page":null}],"frontMatter":{"authors":["matt"],"tags":["Changelog"]},"unlisted":false,"prevItem":{"title":"1.30.12 - Workflow Rollback","permalink":"/changelog/2023/07/20/2023-07-20-1.30.12 - Rapid Platform/1.30.12 - Rapid Platform"},"nextItem":{"title":"1.30.10 - Control Deletion at List Level","permalink":"/changelog/2023/06/29/2023-06-29-1.30.10 - Rapid Platform/1.30.10 - Rapid Platform"}},"content":"6/07/2023\\n\\n## Features\\n\\n### User Task Communication Support\\n\\nYou can now leverage the existing communication infrastructure in User Tasks when configuring your Workflows. This currently only supports SendGrid but will naturally extend to more communication channels as they become available.\\n\\n### Embedded File Control\\n\\nAdded the embedded file control to Adaptive. This allows custom pages to render an embedded file definition and allow file viewing and uploading.\\n\\n## Bug Fixes\\n\\n- Fixed Adaptive Designer overview page failing to populate on refresh\\n- Added more robust error handling and reporting when Data Cans run into problems\\n- Fixed Embedded Files configuration being destroyed by update item menu actions\\n- Fixed dependant lookup construction failing when regarding filters on base tables for sub-types\\n- Updated the Due Date for tasks generated in a loop to regard now, rather than the start of the loop\\n\\n## Improvements\\n\\n- Added exit intent configuration on all Explorer menu buttons\\n- Added Embedded Files control to Adaptive control library\\n- Added environment variables to webhooks and remote actions in Explorer"},{"id":"/2023/06/29/2023-06-29-1.30.10 - Rapid Platform/1.30.10 - Rapid Platform","metadata":{"permalink":"/changelog/2023/06/29/2023-06-29-1.30.10 - Rapid Platform/1.30.10 - Rapid Platform","source":"@site/blog/2023-06-29-1.30.10 - Rapid Platform/2023-06-29-1.30.10 - Rapid Platform.md","title":"1.30.10 - Control Deletion at List Level","description":"29/06/2023","date":"2023-06-29T00:00:00.000Z","tags":[{"inline":true,"label":"Changelog","permalink":"/changelog/tags/changelog"}],"readingTime":0.6,"hasTruncateMarker":false,"authors":[{"name":"Matt Franklin","title":"Documents","url":"https://github.com/MattFranklin-Rapid","email":"matthew@rapidplatform.com","imageURL":"https://github.com/MattFranklin-Rapid.png","key":"matt","page":null}],"frontMatter":{"authors":["matt"],"tags":["Changelog"]},"unlisted":false,"prevItem":{"title":"1.30.11 - SendGrid support in User Tasks","permalink":"/changelog/2023/07/06/2023-07-06-1.30.11 - Rapid Platform/1.30.11 - Rapid Platform"},"nextItem":{"title":"1.30.9 - Form Submission Custom Pages","permalink":"/changelog/2023/06/15/2023-06-15-1.30.9 - Rapid Platform/1.30.9 - Rapid Platform"}},"content":"29/06/2023\\n\\n## Features\\n\\n### List Deletion Configuration\\n\\nIt is now possible to enable/disable delete buttons for a list and its items in Explorer using configuration in Designer. This feature helps prevent accidental deletions in linked contexts.\\n\\n## Bug Fixes\\n\\n- Repeating sections no longer crash the page in certain prefill scenarios\\n- Aliased illegal characters in view names\\n- Enabled common names \\n- Webhooks and signal events now fire on workflow update data association\\n- Fixed cases where an entity cannot be deleted due to foreign key constraints\\n\\n## Improvements\\n\\n- Added ability to copy json paths containing spaces and other characters in workflow\\n- Added validation for view names\\n- Command bar is now disabled when no document is selected\\n- Site creation timeout increased to 5 minutes"},{"id":"/2023/06/15/2023-06-15-1.30.9 - Rapid Platform/1.30.9 - Rapid Platform","metadata":{"permalink":"/changelog/2023/06/15/2023-06-15-1.30.9 - Rapid Platform/1.30.9 - Rapid Platform","source":"@site/blog/2023-06-15-1.30.9 - Rapid Platform/2023-06-15-1.30.9 - Rapid Platform.md","title":"1.30.9 - Form Submission Custom Pages","description":"15/06/2023","date":"2023-06-15T00:00:00.000Z","tags":[{"inline":true,"label":"Changelog","permalink":"/changelog/tags/changelog"}],"readingTime":0.95,"hasTruncateMarker":false,"authors":[{"name":"Matt Franklin","title":"Documents","url":"https://github.com/MattFranklin-Rapid","email":"matthew@rapidplatform.com","imageURL":"https://github.com/MattFranklin-Rapid.png","key":"matt","page":null}],"frontMatter":{"authors":["matt"],"tags":["Changelog"]},"unlisted":false,"prevItem":{"title":"1.30.10 - Control Deletion at List Level","permalink":"/changelog/2023/06/29/2023-06-29-1.30.10 - Rapid Platform/1.30.10 - Rapid Platform"},"nextItem":{"title":"1.30.8 - Workflow Improvements","permalink":"/changelog/2023/06/01/2023-06-01-1.30.8 - Rapid Platform/1.30.8 - Rapid Platform"}},"content":"15/06/2023\\n\\n## Features\\n\\n### Successful Submission Form\\n\\nIt is now possible to configure a form or page to be shown in form service after the submission of a form. This is configured on a form level, where successful or errored submissions of the form can have a custom page shown rather than the default success/fail pages.\\n\\n## Bug Fixes\\n\\n- Fixed an issue where lists fail to delete due to foreign key constraints\\n- Fixed a page crash in forms service when a lookup is prefilled to null\\n- Fixed a crash when typing 2 characters at once in a multi line field with a default value set\\n- Fixed an issue where repeating sections will submit null when containing a default value\\n\\n## Improvements\\n\\n- Priority and all other required fields will now be fetched for the tasks experience\\n- Resolved an issue where an erroneous error is thrown on creation of a folder\\n- It is now possible to compare 2 columns together in an OData Filter\\n- When creating or updating a view with an invalid request, no longer times out but returns error\\n- Inactive users will no longer attempt to have SharePoint permissions synced to"},{"id":"/2023/06/01/2023-06-01-1.30.8 - Rapid Platform/1.30.8 - Rapid Platform","metadata":{"permalink":"/changelog/2023/06/01/2023-06-01-1.30.8 - Rapid Platform/1.30.8 - Rapid Platform","source":"@site/blog/2023-06-01-1.30.8 - Rapid Platform/2023-06-01-1.30.8 - Rapid Platform.md","title":"1.30.8 - Workflow Improvements","description":"01/06/2023","date":"2023-06-01T00:00:00.000Z","tags":[{"inline":true,"label":"Changelog","permalink":"/changelog/tags/changelog"}],"readingTime":0.27,"hasTruncateMarker":false,"authors":[{"name":"Matt Franklin","title":"Documents","url":"https://github.com/MattFranklin-Rapid","email":"matthew@rapidplatform.com","imageURL":"https://github.com/MattFranklin-Rapid.png","key":"matt","page":null}],"frontMatter":{"authors":["matt"],"tags":["Changelog"]},"unlisted":false,"prevItem":{"title":"1.30.9 - Form Submission Custom Pages","permalink":"/changelog/2023/06/15/2023-06-15-1.30.9 - Rapid Platform/1.30.9 - Rapid Platform"},"nextItem":{"title":"1.30.7 - Authenticated Requests","permalink":"/changelog/2023/05/18/2023-05-18-1.30.7 - Rapid Platform/1.30.7 - Rapid Platform"}},"content":"01/06/2023\\n\\n## Bug Fixes\\n\\n- Fixed an issue where process runs fail to resume due to cans referencing a deleted item\\n- Fixed an issue where forms fail to submit in certain repeating section cases\\n\\n## Improvements\\n\\n- Updated error responses for invalid ID being updated\\n- Timers resuming when it has already succeeded will no longer error"},{"id":"/2023/05/18/2023-05-18-1.30.7 - Rapid Platform/1.30.7 - Rapid Platform","metadata":{"permalink":"/changelog/2023/05/18/2023-05-18-1.30.7 - Rapid Platform/1.30.7 - Rapid Platform","source":"@site/blog/2023-05-18-1.30.7 - Rapid Platform/2023-05-18-1.30.7 - Rapid Platform.md","title":"1.30.7 - Authenticated Requests","description":"18/5/2023","date":"2023-05-18T00:00:00.000Z","tags":[{"inline":true,"label":"Changelog","permalink":"/changelog/tags/changelog"}],"readingTime":0.98,"hasTruncateMarker":false,"authors":[{"name":"Matt Franklin","title":"Documents","url":"https://github.com/MattFranklin-Rapid","email":"matthew@rapidplatform.com","imageURL":"https://github.com/MattFranklin-Rapid.png","key":"matt","page":null}],"frontMatter":{"authors":["matt"],"tags":["Changelog"]},"unlisted":false,"prevItem":{"title":"1.30.8 - Workflow Improvements","permalink":"/changelog/2023/06/01/2023-06-01-1.30.8 - Rapid Platform/1.30.8 - Rapid Platform"},"nextItem":{"title":"1.30.6 - Workflow Improvements","permalink":"/changelog/2023/05/11/2023-05-11-1.30.6 - Rapid Platform/1.30.6 - Rapid Platform"}},"content":"18/5/2023\\n\\n## Features\\n\\n### API Key Requests\\n\\nWith the positive feedback from last weeks Authenticated requests from Workflow Service Tasks, we have also added API key support. API Keys still are powered by RAPID Integrations on your site and can be configured in several ways depending on how your target API would prefer to receive its keys.\\n\\n#### Custom Header\\nCUSTOM_KEY = \\"X-API-KEY\\"\\n\\n```\\nGET / HTTP/1.1\\nHost: example.com\\n[CUSTOM_KEY]:  [Your Integration Key]\\n```\\n\\n#### Basic Authentication\\n```\\nGET / HTTP/1.1\\nHost: example.com\\nAuthorization:  Basic [Your Integration Key]\\n```\\n\\n#### Query String\\nCUSTOM_KEY = \\"apiKEY\\"\\n\\n```\\nGET / HTTP/1.1\\nHost: example.com\\nParams:  {\\n    [CUSTOM_KEY]: [Your Integration Key]\\n}\\n```\\n\\n#### Body Parameter\\nCUSTOM_KEY = \\"API-KEY\\"\\n\\n```\\nGET / HTTP/1.1\\nHost: example.com\\nBody:  {\\n    [CUSTOM_KEY]: [Your Integration Key]\\n}\\n```\\n\\n### Adaptive Cascading Lookups\\n\\nYou can now configure cascading lookups in Adaptive documents. Cascading lookups regard another lookup on the document and once configured with a matching criteria will filter the items fetched by that criteria, just like in Explorer. \\n\\nThis support should be live for both Tasks and Public form.\\n\\n## Bug Fixes\\n\\n- Fixed creating RAPID Integrations with a Username failing to save on first create\\n\\n## Improvements\\n\\n- User Tasks in Workflow will now return their entire item profile on creation, rather than just completion"},{"id":"/2023/05/11/2023-05-11-1.30.6 - Rapid Platform/1.30.6 - Rapid Platform","metadata":{"permalink":"/changelog/2023/05/11/2023-05-11-1.30.6 - Rapid Platform/1.30.6 - Rapid Platform","source":"@site/blog/2023-05-11-1.30.6 - Rapid Platform/2023-05-11-1.30.6 - Rapid Platform.md","title":"1.30.6 - Workflow Improvements","description":"11/5/2023","date":"2023-05-11T00:00:00.000Z","tags":[{"inline":true,"label":"Changelog","permalink":"/changelog/tags/changelog"}],"readingTime":1.17,"hasTruncateMarker":false,"authors":[{"name":"Matt Franklin","title":"Documents","url":"https://github.com/MattFranklin-Rapid","email":"matthew@rapidplatform.com","imageURL":"https://github.com/MattFranklin-Rapid.png","key":"matt","page":null}],"frontMatter":{"authors":["matt"],"tags":["Changelog"]},"unlisted":false,"prevItem":{"title":"1.30.7 - Authenticated Requests","permalink":"/changelog/2023/05/18/2023-05-18-1.30.7 - Rapid Platform/1.30.7 - Rapid Platform"},"nextItem":{"title":"1.30.5 - Workflow Improvements","permalink":"/changelog/2023/04/27/2023-04-27-1.30.5 - Rapid Platform/1.30.5 - Rapid Platform"}},"content":"11/5/2023\\n\\n## Features\\n\\n### Update Associations\\n\\nWith the advent of Cans you can now configure the Data Association (dotted arrow) from an Activity towards a Can to set values of the associated item. This update is performed after the action is completed, so that you can capture data collected during the activity itself. \\n\\n![Data association configuration](<Data association configuration.png>)\\n\\n### Authenticated Service Tasks\\n\\nWebhook service tasks can now use Basic authentication when interacting with remote APIs. This authentication is created and stored in a newly updated Rapid Integrations list. When creating a new integration the Username and Password are stored securely in Azure Key Vault and not on your site. As a consequence you will not be able to see stored passwords. Updating a Username or Password will overwrite the value in the Key Vault and thus be used by Workflow form then on.\\n\\n### Lookup View Whitelisting\\n\\nWhen configuring a Lookup component in Adaptive Pages and Forms, you can now select a subset of views on the target table to present to the User. By default the All view will still be the first selected view.\\n\\n## Bug Fixes\\n\\n- Fixed Default values for Choice fields in Adaptive Pages and Forms failing to load\\n- Fixed long placeholder and content values of Choice fields extending out the page\\n- Fixed deleted RAPID Sites persisting in cache storage\\n\\n## Improvements\\n\\n- Disabled Save and Complete buttons on Tasks while saving/completing"},{"id":"/2023/04/27/2023-04-27-1.30.5 - Rapid Platform/1.30.5 - Rapid Platform","metadata":{"permalink":"/changelog/2023/04/27/2023-04-27-1.30.5 - Rapid Platform/1.30.5 - Rapid Platform","source":"@site/blog/2023-04-27-1.30.5 - Rapid Platform/2023-04-27-1.30.5 - Rapid Platform.md","title":"1.30.5 - Workflow Improvements","description":"27/4/2023","date":"2023-04-27T00:00:00.000Z","tags":[{"inline":true,"label":"Changelog","permalink":"/changelog/tags/changelog"}],"readingTime":1.29,"hasTruncateMarker":false,"authors":[{"name":"Matt Franklin","title":"Documents","url":"https://github.com/MattFranklin-Rapid","email":"matthew@rapidplatform.com","imageURL":"https://github.com/MattFranklin-Rapid.png","key":"matt","page":null}],"frontMatter":{"authors":["matt"],"tags":["Changelog"]},"unlisted":false,"prevItem":{"title":"1.30.6 - Workflow Improvements","permalink":"/changelog/2023/05/11/2023-05-11-1.30.6 - Rapid Platform/1.30.6 - Rapid Platform"},"nextItem":{"title":"1.30.4 - Document Theming","permalink":"/changelog/2023/04/21/2023-04-21-1.30.4 - Rapid Platform/1.30.4 - Rapid Platform"}},"content":"27/4/2023\\n\\n## Features\\n\\n### DocX Image Support\\n\\nYou can now use Images in the DocX Templater when filling in documents. With the `{%ImageName}` syntax you can insert new images, or replace existing images by setting their Alt text. Images replaced will respect the image size boundaries while also trying to respect the source image aspect ratio to prevent overflow in your documents. Small images will retain their size if they are smaller than the image they\'re replacing. \\n\\nImages can be sourced from SharePoint, as with all files in RAPID.\\n\\n### Adaptive Output Support\\n\\nUser Tasks in workflow with an attached adaptive forms now present the items created or updated in the ledger. These can be accessed to help identify what happened. Items affected are now available on a \'context\' key after the task is completed.\\n\\n### Prefill Type Coercion\\n\\nPrefill data now parses strings. For example numbers and Boolean values will be cast to their correct type. Booleans are case sensitive, as per these examples:\\n\\n- \\"1\\" > 1\\n- \\"0\\" > 0\\n- \\"true\\" > true\\n- \\"false\\" > false\\n- \\"TrUe\\" > \\"TrUe\\"\\n- \\"FaLSe\\" > \\"FaLSe\\"\\n\\nThis system follows the standard json.parse / json.stringify behaviour.\\n\\n## Bug Fixes\\n\\n- Fixed duplicate universal links created from workflow\\n- Fixed negative numbers in number fields changing to positive\\n- Prevented page crash when list names start with numbers\\n- Fixed page snapping to top when expanding a lookup in a form\\n- Prevented \'Get items\' service tasks without a view selected, from fetching raw items\\n\\n## Improvements\\n\\n- Update styling on Delete intent modal\\n- Users can now remove default repeating sections\\n- Updated forms test url to point to new server"},{"id":"/2023/04/21/2023-04-21-1.30.4 - Rapid Platform/1.30.4 - Rapid Platform","metadata":{"permalink":"/changelog/2023/04/21/2023-04-21-1.30.4 - Rapid Platform/1.30.4 - Rapid Platform","source":"@site/blog/2023-04-21-1.30.4 - Rapid Platform/2023-04-21-1.30.4 - Rapid Platform.md","title":"1.30.4 - Document Theming","description":"21/4/2023","date":"2023-04-21T00:00:00.000Z","tags":[{"inline":true,"label":"Changelog","permalink":"/changelog/tags/changelog"}],"readingTime":1.48,"hasTruncateMarker":false,"authors":[{"name":"Matt Franklin","title":"Documents","url":"https://github.com/MattFranklin-Rapid","email":"matthew@rapidplatform.com","imageURL":"https://github.com/MattFranklin-Rapid.png","key":"matt","page":null}],"frontMatter":{"authors":["matt"],"tags":["Changelog"]},"unlisted":false,"prevItem":{"title":"1.30.5 - Workflow Improvements","permalink":"/changelog/2023/04/27/2023-04-27-1.30.5 - Rapid Platform/1.30.5 - Rapid Platform"},"nextItem":{"title":"1.30.0 - Mobile Tasks","permalink":"/changelog/2023/04/13/2023-04-13-1.30.4 - Rapid Platform/1.30.4 - Rapid Platform"}},"content":"21/4/2023\\n\\n## Features\\n\\n### DocX Theme Support\\n\\nWord Documents support different Themes and the Fill Document service task (powered by DocX) now does as well. You can now configure custom theme colours which will be applied to the produced document. This sets the actual Word theme, so any content within can be styled. The theming interface mirrors the Theme configurator in Word itself to make it easy to map your custom themes across.\\n\\nOne word of warning, Word Online has different behaviour around custom themes as compared to Word running locally. We have noticed the first two theme colours (Text Light 1 and Text Dark 1) are respected by Word Online but instead set to black and white locally.\\n\\n### Adaptive Required Field Support\\n\\nMarking fields as required in Adaptive documents will now be respected by both Public Forms and the Task Experience. Public forms with empty required fields will prevent submission of the form. Tasks can be altered and saved so that they can be pushed out or slowly filled in over time, but trying to complete a task with missing required fields will now direct the user to fill them in. \\n\\nThis update has no effect on Explorer.\\n\\n## Bug Fixes\\n\\n- Fixed failure to save a task in the Task Experience if it did not have a document configured\\n- Fixed parallel gateway merges in loop scenarios failing to wait for all the tokens before completing\\n- Fixed inline refresh on the Tasks Experience failing to actually refresh with items\\n- Prevented repeating sections with 0 items creating a blank item on submission\\n\\n## Improvements\\n\\n- Added confirmation modal to Adaptive Designer delete button\\n- Hidden universal links to notifications in Adaptive Tasks\\n- Enabled item creation blacklisting on Gantt and Board components in Explorer\\n- Cleaned up Tasks experience mobile style from feedback"},{"id":"/2023/04/13/2023-04-13-1.30.4 - Rapid Platform/1.30.4 - Rapid Platform","metadata":{"permalink":"/changelog/2023/04/13/2023-04-13-1.30.4 - Rapid Platform/1.30.4 - Rapid Platform","source":"@site/blog/2023-04-13-1.30.4 - Rapid Platform/2023-04-13-1.30.4 - Rapid Platform.md","title":"1.30.0 - Mobile Tasks","description":"13/4/2023","date":"2023-04-13T00:00:00.000Z","tags":[{"inline":true,"label":"Changelog","permalink":"/changelog/tags/changelog"}],"readingTime":0.94,"hasTruncateMarker":false,"authors":[{"name":"Matt Franklin","title":"Documents","url":"https://github.com/MattFranklin-Rapid","email":"matthew@rapidplatform.com","imageURL":"https://github.com/MattFranklin-Rapid.png","key":"matt","page":null}],"frontMatter":{"authors":["matt"],"tags":["Changelog"]},"unlisted":false,"prevItem":{"title":"1.30.4 - Document Theming","permalink":"/changelog/2023/04/21/2023-04-21-1.30.4 - Rapid Platform/1.30.4 - Rapid Platform"},"nextItem":{"title":"1.29.4 - Bulk Support","permalink":"/changelog/2023/03/30/2023-03-30-1.29.4 - Rapid Platform/1.29.4 - Rapid Platform"}},"content":"13/4/2023\\n\\n## Features\\n\\n### Mobile Tasks\\n\\nThe Tasks experience has been upgraded with a mobile friendly style sheet. This styling change comes with improvements for buttons including a disabled state on task side menus when they are empty. As always these improvements are powered by feedback, so hearing back about how if works on your device is highly appreciated.\\n\\n## Bug Fixes\\n\\n- Nailed down (finally) the last cases where prefilled lookups fail to present their display field\\n- Prevented page crash when expanding the activity feed on some tasks in the Tasks experience\\n- Prevented page crash when adding components to a section in Adaptive Designer with a Process Diagram context\\n- Fixed workflow failing to link produced items in a process run to the triggering item on signal event processes\\n- Prevented Adaptive login screen forcing cursor to end of line in the tenant/site fields\\n\\n## Improvements\\n\\n- Set Tasks experience side panels to disabled when they do not contain any content\\n- Enforced consistent author id when Workflow produces items\\n- Raised date picker modal above all elements when interacting with it\\n- Added automated repair mechanism for product owners to manage their customer sites"},{"id":"/2023/03/30/2023-03-30-1.29.4 - Rapid Platform/1.29.4 - Rapid Platform","metadata":{"permalink":"/changelog/2023/03/30/2023-03-30-1.29.4 - Rapid Platform/1.29.4 - Rapid Platform","source":"@site/blog/2023-03-30-1.29.4 - Rapid Platform/2023-03-30-1.29.4 - Rapid Platform.md","title":"1.29.4 - Bulk Support","description":"30/3/2023","date":"2023-03-30T00:00:00.000Z","tags":[{"inline":true,"label":"Changelog","permalink":"/changelog/tags/changelog"}],"readingTime":0.35,"hasTruncateMarker":false,"authors":[{"name":"Matt Franklin","title":"Documents","url":"https://github.com/MattFranklin-Rapid","email":"matthew@rapidplatform.com","imageURL":"https://github.com/MattFranklin-Rapid.png","key":"matt","page":null}],"frontMatter":{"authors":["matt"],"tags":["Changelog"]},"unlisted":false,"prevItem":{"title":"1.30.0 - Mobile Tasks","permalink":"/changelog/2023/04/13/2023-04-13-1.30.4 - Rapid Platform/1.30.4 - Rapid Platform"},"nextItem":{"title":"1.29.0 - Notification Support","permalink":"/changelog/2023/03/23/2023-03-23-1.29.0 - Rapid Platform/1.29.0 - Rapid Platform"}},"content":"30/3/2023\\n\\n## Improvements\\n\\n- Added bulk selection to the Adaptive Designer component selector\\n- Added new query parameter on bulk creation to enable events to be fired\\n- Enabled events to be fired in Public Forms when creating items in a repeating section\\n- Moved site file caching external and enabled multiple Minilith pods\\n- Lookups in Public Forms now present a more obvious search bar and load 50 items rather than 10"},{"id":"/2023/03/23/2023-03-23-1.29.0 - Rapid Platform/1.29.0 - Rapid Platform","metadata":{"permalink":"/changelog/2023/03/23/2023-03-23-1.29.0 - Rapid Platform/1.29.0 - Rapid Platform","source":"@site/blog/2023-03-23-1.29.0 - Rapid Platform/2023-03-23-1.29.0 - Rapid Platform.md","title":"1.29.0 - Notification Support","description":"23/3/2023","date":"2023-03-23T00:00:00.000Z","tags":[{"inline":true,"label":"Changelog","permalink":"/changelog/tags/changelog"}],"readingTime":1.09,"hasTruncateMarker":false,"authors":[{"name":"Matt Franklin","title":"Documents","url":"https://github.com/MattFranklin-Rapid","email":"matthew@rapidplatform.com","imageURL":"https://github.com/MattFranklin-Rapid.png","key":"matt","page":null}],"frontMatter":{"authors":["matt"],"tags":["Changelog"]},"unlisted":false,"prevItem":{"title":"1.29.4 - Bulk Support","permalink":"/changelog/2023/03/30/2023-03-30-1.29.4 - Rapid Platform/1.29.4 - Rapid Platform"},"nextItem":{"title":"1.28.4 - Data Cans","permalink":"/changelog/2023/03/16/2023-03-16-1.28.4 - Rapid Platform/1.28.4 - Rapid Platform"}},"content":"23/3/2023\\n\\n## Features\\n\\n### Notification Lists\\n\\nNotifications and Audiences have been upgraded from an internal table to full list support. This enables access to access and control of notifications via the API for the creation of 3rd party notification systems. See the Technical Documentation for requirements to produce and manage notifications.\\n\\n### Environment Headers\\n\\nWebhooks and Service tasks sent from RAPID to external systems now will carry environment information in their headers. This allows for the creation of third party endpoints that can react differently if a request is received from Test or Production.\\n\\n## Bugfixs\\n\\n- Fixed dates pulled from a Data Store using Lodash in Workflow v3 returning a JS date instead of an ISO date\\n- Fixed lookups prefilled with just an ID failing to fetch the display field in Tasks\\n- Enabled JSON fields on base tables to be returned on the All$ view, matching behaviour with sub tables\\n\\n## Improvements\\n\\n- Enabled input limits on Adaptive Input components\\n- Added Adaptive File Component support when placed in the Tasks experience\\n- When searching for a component to add in the Adaptive Designer, the All view now can regard a list context\\n- Added multi-select to the component adding panel in Adaptive Designer\\n- Added improved error messaging when trying to submit a public form that had been removed from a local store"},{"id":"/2023/03/16/2023-03-16-1.28.4 - Rapid Platform/1.28.4 - Rapid Platform","metadata":{"permalink":"/changelog/2023/03/16/2023-03-16-1.28.4 - Rapid Platform/1.28.4 - Rapid Platform","source":"@site/blog/2023-03-16-1.28.4 - Rapid Platform/2023-03-16-1.28.4 - Rapid Platform.md","title":"1.28.4 - Data Cans","description":"16/3/2023","date":"2023-03-16T00:00:00.000Z","tags":[{"inline":true,"label":"Changelog","permalink":"/changelog/tags/changelog"}],"readingTime":0.63,"hasTruncateMarker":false,"authors":[{"name":"Matt Franklin","title":"Documents","url":"https://github.com/MattFranklin-Rapid","email":"matthew@rapidplatform.com","imageURL":"https://github.com/MattFranklin-Rapid.png","key":"matt","page":null}],"frontMatter":{"authors":["matt"],"tags":["Changelog"]},"unlisted":false,"prevItem":{"title":"1.29.0 - Notification Support","permalink":"/changelog/2023/03/23/2023-03-23-1.29.0 - Rapid Platform/1.29.0 - Rapid Platform"},"nextItem":{"title":"1.28.2 - Adaptive Cleanup","permalink":"/changelog/2023/03/09/2023-03-09-1.28.2 - Rapid Platform/1.28.2 - Rapid Platform"}},"content":"16/3/2023\\n\\n## Features\\n\\n### Data Cans\\n\\nIt is now possible to add data cans to workflow diagrams. These act as persistent get item or get items service task, where you can reference them and fetch the most upto date state of the item(s)\\n\\n### Error Boundary Event\\n\\nThere is now support for the error boundary event, if the attached activity gets into an errored state, the boundary path will be taken. \\n\\n## Bugfixs\\n\\n- Fixed the Multi Line text control in tasks and anonymous forms\\n- Removing a condition no longer drops the whole array of conditions\\n- Fixed a page crash on editing form state in Designer\\n\\n## Improvements\\n\\n- Added support for double clicking webhook service tasks opening the run information URL\\n- Theme.css file is now loaded into Designer"},{"id":"/2023/03/09/2023-03-09-1.28.2 - Rapid Platform/1.28.2 - Rapid Platform","metadata":{"permalink":"/changelog/2023/03/09/2023-03-09-1.28.2 - Rapid Platform/1.28.2 - Rapid Platform","source":"@site/blog/2023-03-09-1.28.2 - Rapid Platform/2023-03-09-1.28.2 - Rapid Platform.md","title":"1.28.2 - Adaptive Cleanup","description":"9/3/2023","date":"2023-03-09T00:00:00.000Z","tags":[{"inline":true,"label":"Changelog","permalink":"/changelog/tags/changelog"}],"readingTime":0.22,"hasTruncateMarker":false,"authors":[{"name":"Matt Franklin","title":"Documents","url":"https://github.com/MattFranklin-Rapid","email":"matthew@rapidplatform.com","imageURL":"https://github.com/MattFranklin-Rapid.png","key":"matt","page":null}],"frontMatter":{"authors":["matt"],"tags":["Changelog"]},"unlisted":false,"prevItem":{"title":"1.28.4 - Data Cans","permalink":"/changelog/2023/03/16/2023-03-16-1.28.4 - Rapid Platform/1.28.4 - Rapid Platform"},"nextItem":{"title":"1.28.1 - Styling and Cleanup","permalink":"/changelog/2023/03/02/2023-03-02-1.28.1 - Rapid Platform/1.28.1 - Rapid Platform"}},"content":"9/3/2023\\n\\n## Bugfixs\\n\\n- Fixed create pages configured in Tasks failing to render for sub-types of tasks\\n- Fixed the configuration panel in Adaptive Designer showing an empty configuration when opened\\n- Prevented a page crash when viewing embedded files in the Tasks experience"},{"id":"/2023/03/02/2023-03-02-1.28.1 - Rapid Platform/1.28.1 - Rapid Platform","metadata":{"permalink":"/changelog/2023/03/02/2023-03-02-1.28.1 - Rapid Platform/1.28.1 - Rapid Platform","source":"@site/blog/2023-03-02-1.28.1 - Rapid Platform/2023-03-02-1.28.1 - Rapid Platform.md","title":"1.28.1 - Styling and Cleanup","description":"2/3/2023","date":"2023-03-02T00:00:00.000Z","tags":[{"inline":true,"label":"Changelog","permalink":"/changelog/tags/changelog"}],"readingTime":0.98,"hasTruncateMarker":false,"authors":[{"name":"Matt Franklin","title":"Documents","url":"https://github.com/MattFranklin-Rapid","email":"matthew@rapidplatform.com","imageURL":"https://github.com/MattFranklin-Rapid.png","key":"matt","page":null}],"frontMatter":{"authors":["matt"],"tags":["Changelog"]},"unlisted":false,"prevItem":{"title":"1.28.2 - Adaptive Cleanup","permalink":"/changelog/2023/03/09/2023-03-09-1.28.2 - Rapid Platform/1.28.2 - Rapid Platform"},"nextItem":{"title":"1.27.28 - Tasks & Workflow v3","permalink":"/changelog/2023/02/27/2023-02-27-1.27.28 - Rapid Platform/1.27.28 - Rapid Platform"}},"content":"2/3/2023\\n\\n## Features\\n\\n### DocX PDF Support\\n\\nYou can now generate a PDF from the DocX service task. When creating a PDF file the original word file will still be produced. When referencing the embedded files configuration of the DocX service task in Workflow with PDF selected, the PDF file will be returned instead.\\n\\nAdditionally there is now a toggle to preserve the `{moustache glyphs}` within your documents when running the service task. By default these glyphs will now be replaced with a blank character.\\n\\n## Bugfixs\\n\\n- Fixed a page crash when navigating between the login page and task list in the Tasks Experience\\n- Fixed conditions in repeating sections failing to evaluate\\n- Fixed subtypes of items linked via lookup failing to be fetched in linked scenarios\\n\\n## Improvements\\n\\n- Repeating sections in Adaptive now fetch all fields contained within them, including multi-line text fields\\n- Added Theme.css file support to the Tasks experience\\n- Added search when using @mentions in the Activity Feed for sites with more than 250 users\\n- Added click-through support between Explorer and Workflow when opening process runs inside call activity scopes\\n- Added new custom rich text editor to Adapative, replacing the Multi-Line Text Control"},{"id":"/2023/02/27/2023-02-27-1.27.28 - Rapid Platform/1.27.28 - Rapid Platform","metadata":{"permalink":"/changelog/2023/02/27/2023-02-27-1.27.28 - Rapid Platform/1.27.28 - Rapid Platform","source":"@site/blog/2023-02-27-1.27.28 - Rapid Platform/2023-02-27-1.27.28 - Rapid Platform.md","title":"1.27.28 - Tasks & Workflow v3","description":"27/02/2023","date":"2023-02-27T00:00:00.000Z","tags":[{"inline":true,"label":"Changelog","permalink":"/changelog/tags/changelog"}],"readingTime":1.98,"hasTruncateMarker":false,"authors":[{"name":"Matt Franklin","title":"Documents","url":"https://github.com/MattFranklin-Rapid","email":"matthew@rapidplatform.com","imageURL":"https://github.com/MattFranklin-Rapid.png","key":"matt","page":null}],"frontMatter":{"authors":["matt"],"tags":["Changelog"]},"unlisted":false,"prevItem":{"title":"1.28.1 - Styling and Cleanup","permalink":"/changelog/2023/03/02/2023-03-02-1.28.1 - Rapid Platform/1.28.1 - Rapid Platform"},"nextItem":{"title":"1.26.7 - Adaptive Documents","permalink":"/changelog/2022/11/27/2022-11-27-1.26.7 - Rapid Platform/1.26.7 - Rapid Platform"}},"content":"27/02/2023\\n\\nThis release contains a one-two punch of the brand new Tasks experience as well as the shiny new Workflow v3 engine.\\n\\n## Features\\n\\n### Tasks Experience\\n\\nLeveraging the Adaptive Documents design, the new Tasks experience brings the associated document front and centre.\\n\\nThis also comes with a new connection type to configure your Adaptive Documents, the \'Expected Context\' connection. Expected Contexts allow you to define which item type (or sub-type) you are expecting to be present when opening the task. With this you can define how items that are created and updated via an Adaptive document relate to the task, if at all! \\n\\n### Workflow v3\\n\\nWorkflows\' engine has been replaced with a brand new version built from scratch. Faster, more powerful and much more extensible; Workflow 3 unlocks finally implementing more of the BPMN 2.0 specification. One of the most drastic changes comes in the form of Call Activities and their child process runs. To be more in accordance with the BPMN 2.0 specification, and to support future Data Cans and Documents, sub-processes are now incorporated in their parent ledger.\\n\\nWhile this engine upgrade is mostly future facing, it does come with some spicy new improvements right now\\n\\n### Custom Post Bodies\\n\\nYou can now configure custom post bodies in Webhook service tasks. Now you can simplify getting the data you want out of your process by using powerful Lodash expressions. Blank configurations will continue to post the entire ledger, so existing diagrams will not be affected.\\n\\n![Custom post body configuration](<Custom post body configuration.png>)\\n\\n### Non-Interrupting Timers\\n\\nConfiguring a Timer to be non-interrupting allows the creation of follow-up and checking branches in your process, without disrupting mission critical tasks.\\n\\n![Non Interrupting Timer example](<Non Interrupting Timer example.png>)\\n\\n## Bug Fixes\\n\\n- Fixed Context Missing error when trying to create columns called \'Title\' on new tables\\n- Fixed missing clear value buttons on User and Date fields in Adaptive Documents\\n- Prevented root level crash when adding Time Picker component to a page\\n- Fixed custom create pages in Adaptive Documents with lookups rendering behind the creation modal\\n- Fixed configuration components failing to render on the File component\\n\\n## Improvements\\n\\n- Added spinner to RP Forms when loading the framework\\n- Added multi-lookup field support to Adaptive Documents\\n- Removed erroneous .toString when processing id values via the SDK\\n- Implemented sub-process navigation to Explorer and Workflow UI"},{"id":"/2022/11/27/2022-11-27-1.26.7 - Rapid Platform/1.26.7 - Rapid Platform","metadata":{"permalink":"/changelog/2022/11/27/2022-11-27-1.26.7 - Rapid Platform/1.26.7 - Rapid Platform","source":"@site/blog/2022-11-27-1.26.7 - Rapid Platform/2022-11-27-1.26.7 - Rapid Platform.md","title":"1.26.7 - Adaptive Documents","description":"27/11/2022","date":"2022-11-27T00:00:00.000Z","tags":[{"inline":true,"label":"Changelog","permalink":"/changelog/tags/changelog"}],"readingTime":0.95,"hasTruncateMarker":false,"authors":[{"name":"Matt Franklin","title":"Documents","url":"https://github.com/MattFranklin-Rapid","email":"matthew@rapidplatform.com","imageURL":"https://github.com/MattFranklin-Rapid.png","key":"matt","page":null}],"frontMatter":{"authors":["matt"],"tags":["Changelog"]},"unlisted":false,"prevItem":{"title":"1.27.28 - Tasks & Workflow v3","permalink":"/changelog/2023/02/27/2023-02-27-1.27.28 - Rapid Platform/1.27.28 - Rapid Platform"},"nextItem":{"title":"1.25.15 - Link Performance","permalink":"/changelog/2022/11/03/2022-11-03-1.25.15 - Rapid Platform/1.25.15 - Rapid Platform"}},"content":"27/11/2022\\n\\nThis release replaces Adaptive Forms with the more flexible Adaptive Documents. Documents are powerful way to store and track deep data in a single, transmittable form. This change paves the way for Adaptive Apps to develop custom experiences.\\n\\nAs a consequence of this change, Adaptive Designer has been upgraded to support Documents. Additionally this release will include a database upgrade to shift all existing forms into documents. \\n\\n## Features\\n\\n### Adaptive Designer v3\\n\\nDesigner has undergone significant changes supporting documents. You can now open multiple documents at the same time to make switching between them easier.\\n\\n![AD Designer Mutliple documents](<AD Designer Mutliple documents.png>)\\n\\nTab support has also been added to help spread configuration out so you can focus on what you\'re trying to do.\\n\\n![Multiple tabs in Ad Designer](<Multiple tabs in Ad Designer.png>)\\n\\n## Bug Fixes\\n\\n- Fixed malformed item profile response shape when selecting sys_type_id\\n\\n## Improvements\\n\\n- Simplified Universal Link schema to reduce on-disk storage by around 20%\\n- Added Adaptive Documents system list, replacing Adaptive Forms\\n- Associated existing public form tasks to Adaptive Documents\\n- Associated existing process diagrams to Adaptive Documents\\n- Implemented Adaptive Document configuration support into Workflow"},{"id":"/2022/11/03/2022-11-03-1.25.15 - Rapid Platform/1.25.15 - Rapid Platform","metadata":{"permalink":"/changelog/2022/11/03/2022-11-03-1.25.15 - Rapid Platform/1.25.15 - Rapid Platform","source":"@site/blog/2022-11-03-1.25.15 - Rapid Platform/2022-11-03-1.25.15 - Rapid Platform.md","title":"1.25.15 - Link Performance","description":"3/11/2022","date":"2022-11-03T00:00:00.000Z","tags":[{"inline":true,"label":"Changelog","permalink":"/changelog/tags/changelog"}],"readingTime":0.18,"hasTruncateMarker":false,"authors":[{"name":"Matt Franklin","title":"Documents","url":"https://github.com/MattFranklin-Rapid","email":"matthew@rapidplatform.com","imageURL":"https://github.com/MattFranklin-Rapid.png","key":"matt","page":null}],"frontMatter":{"authors":["matt"],"tags":["Changelog"]},"unlisted":false,"prevItem":{"title":"1.26.7 - Adaptive Documents","permalink":"/changelog/2022/11/27/2022-11-27-1.26.7 - Rapid Platform/1.26.7 - Rapid Platform"},"nextItem":{"title":"1.25.14 - API Updates","permalink":"/changelog/2022/10/06/2022-10-06-1.25.14 - Rapid Platform/1.25.14 - Rapid Platform"}},"content":"3/11/2022\\n\\n## Improvements\\n\\n- Updated Universal Link handling in Explorer to be more performant on items with many (200+) universal links\\n- Cloning Process Diagrams and Adaptive Forms now will clone the XML and JSON data within"},{"id":"/2022/10/06/2022-10-06-1.25.14 - Rapid Platform/1.25.14 - Rapid Platform","metadata":{"permalink":"/changelog/2022/10/06/2022-10-06-1.25.14 - Rapid Platform/1.25.14 - Rapid Platform","source":"@site/blog/2022-10-06-1.25.14 - Rapid Platform/2022-10-06-1.25.14 - Rapid Platform.md","title":"1.25.14 - API Updates","description":"6/10/2022","date":"2022-10-06T00:00:00.000Z","tags":[{"inline":true,"label":"Changelog","permalink":"/changelog/tags/changelog"}],"readingTime":0.99,"hasTruncateMarker":false,"authors":[{"name":"Matt Franklin","title":"Documents","url":"https://github.com/MattFranklin-Rapid","email":"matthew@rapidplatform.com","imageURL":"https://github.com/MattFranklin-Rapid.png","key":"matt","page":null}],"frontMatter":{"authors":["matt"],"tags":["Changelog"]},"unlisted":false,"prevItem":{"title":"1.25.15 - Link Performance","permalink":"/changelog/2022/11/03/2022-11-03-1.25.15 - Rapid Platform/1.25.15 - Rapid Platform"},"nextItem":{"title":"1.25.13 - Adaptive Framework Polish","permalink":"/changelog/2022/09/27/2022-09-27-1.25.13 - Rapid Platform/1.25.13 - Rapid Platform"}},"content":"6/10/2022\\n\\n## Features\\n\\n### Default configuration for Date columns on lists\\n\\nYou can now configure a date column in Designer to have a default value. This value is configured as a combination of a relative date plus an offset. For example, Task Start Dates now default to Today, while their Due Date now default to Today +1 (aka: Tommorrow).\\n\\nThe list of relative dates to use mirror the configuration for Views and are\\n\\n- today\\n- tomorrow\\n- startOfWeek\\n- endOfWeek\\n- startOfMonth\\n- endOfMonth\\n- startOfQuarter\\n- endOfQuarter\\n\\nAs always at RAPID we are looking for feedback on which relative dates you would find useful.\\n\\n## Bug Fixes\\n\\n- Fixed itemFilter configuration failing to be regarded in public forms for child repeating sections\\n- Fixed Prefill data for root level single item contexts being nested under _data._data\\n- Removed dead Workflow v2 API routes\\n- Removed dead Workflow v2 test plan routes and UI\\n\\n## Improvements\\n\\n- Added $top and $skip independent query parameter support to Omnichannel when fetching a calendarView, previously both keys were required to be processed\\n- Added scroll to connections panel in Adaptive Designer for tables with more than 30 columns\\n- The Get Items service task now regards the selected view, instead of defaulting to the All$ view"},{"id":"/2022/09/27/2022-09-27-1.25.13 - Rapid Platform/1.25.13 - Rapid Platform","metadata":{"permalink":"/changelog/2022/09/27/2022-09-27-1.25.13 - Rapid Platform/1.25.13 - Rapid Platform","source":"@site/blog/2022-09-27-1.25.13 - Rapid Platform/2022-09-27-1.25.13 - Rapid Platform.md","title":"1.25.13 - Adaptive Framework Polish","description":"27/09/2022","date":"2022-09-27T00:00:00.000Z","tags":[{"inline":true,"label":"Changelog","permalink":"/changelog/tags/changelog"}],"readingTime":0.07,"hasTruncateMarker":false,"authors":[{"name":"Matt Franklin","title":"Documents","url":"https://github.com/MattFranklin-Rapid","email":"matthew@rapidplatform.com","imageURL":"https://github.com/MattFranklin-Rapid.png","key":"matt","page":null}],"frontMatter":{"authors":["matt"],"tags":["Changelog"]},"unlisted":false,"prevItem":{"title":"1.25.14 - API Updates","permalink":"/changelog/2022/10/06/2022-10-06-1.25.14 - Rapid Platform/1.25.14 - Rapid Platform"},"nextItem":{"title":"1.25.12 - Adaptive Framework Polish","permalink":"/changelog/2022/09/15/2022-09-15-1.25.12 - Rapid Platform/1.25.12 - Rapid Platform"}},"content":"27/09/2022\\n\\n## Bug Fixes\\n\\n- Fixed prefill data failing to bind in repeating sections"},{"id":"/2022/09/15/2022-09-15-1.25.12 - Rapid Platform/1.25.12 - Rapid Platform","metadata":{"permalink":"/changelog/2022/09/15/2022-09-15-1.25.12 - Rapid Platform/1.25.12 - Rapid Platform","source":"@site/blog/2022-09-15-1.25.12 - Rapid Platform/2022-09-15-1.25.12 - Rapid Platform.md","title":"1.25.12 - Adaptive Framework Polish","description":"15/09/2022","date":"2022-09-15T00:00:00.000Z","tags":[{"inline":true,"label":"Changelog","permalink":"/changelog/tags/changelog"}],"readingTime":0.45,"hasTruncateMarker":false,"authors":[{"name":"Matt Franklin","title":"Documents","url":"https://github.com/MattFranklin-Rapid","email":"matthew@rapidplatform.com","imageURL":"https://github.com/MattFranklin-Rapid.png","key":"matt","page":null}],"frontMatter":{"authors":["matt"],"tags":["Changelog"]},"unlisted":false,"prevItem":{"title":"1.25.13 - Adaptive Framework Polish","permalink":"/changelog/2022/09/27/2022-09-27-1.25.13 - Rapid Platform/1.25.13 - Rapid Platform"},"nextItem":{"title":"1.25.11 - Time Slot Component","permalink":"/changelog/2022/09/08/2022-09-08-1.25.11 - Rapid Platform/1.25.11 - Rapid Platform"}},"content":"15/09/2022\\n\\n## Bug Fixes\\n\\n- Fixed hyperlinks failing to save their target in Static Text controls for the Adaptive Designer\\n- Prevented data visually bleeding between workflow elements of the same type under certain circumstances\\n- Stopped labels of hidden fields showing\\n\\n## Improvements\\n\\n- Added trashcan button when configuring DocX service tasks in Workflow that clears all form keys (including hidden ones)\\n- Implemented Multi-Lookup per-fill data support in Public Forms and the Adaptive Designer\\n- Prevented proxied endpoints that contain HTTP Verbs in their url from being truncated in the SDK"},{"id":"/2022/09/08/2022-09-08-1.25.11 - Rapid Platform/1.25.11 - Rapid Platform","metadata":{"permalink":"/changelog/2022/09/08/2022-09-08-1.25.11 - Rapid Platform/1.25.11 - Rapid Platform","source":"@site/blog/2022-09-08-1.25.11 - Rapid Platform/2022-09-08-1.25.11 - Rapid Platform.md","title":"1.25.11 - Time Slot Component","description":"8/09/2022","date":"2022-09-08T00:00:00.000Z","tags":[{"inline":true,"label":"Changelog","permalink":"/changelog/tags/changelog"}],"readingTime":0.59,"hasTruncateMarker":false,"authors":[{"name":"Matt Franklin","title":"Documents","url":"https://github.com/MattFranklin-Rapid","email":"matthew@rapidplatform.com","imageURL":"https://github.com/MattFranklin-Rapid.png","key":"matt","page":null}],"frontMatter":{"authors":["matt"],"tags":["Changelog"]},"unlisted":false,"prevItem":{"title":"1.25.12 - Adaptive Framework Polish","permalink":"/changelog/2022/09/15/2022-09-15-1.25.12 - Rapid Platform/1.25.12 - Rapid Platform"},"nextItem":{"title":"1.25.6 - Hotfix 1","permalink":"/changelog/2022/08/22/2022-08-22-1.25.6 - Rapid Platform/1.25.6 - Rapid Platform"}},"content":"8/09/2022\\n\\n## Features\\n\\nAdded the Time Slot component to the Adaptive Designer. This component can be configured to an Exchange inbox to allow users to select a date range (aka : time slot) from available times on that calendar.\\n\\n## Bug Fixes\\n\\n- Fixed updating items via public forms failing to submit\\n- General fixes to components and adaptive controls\\n- Fixed email inputs crashing on mount under certain circumstances\\n- Fixed number inputs in embedded forms eating decimal places\\n\\n## Improvements\\n\\n- Added secure attributes to Framework to give control over protected data in public scenarios\\n- Implemented connection binding controls for components that produce more than one scalar value\\n- Updated Framework typings into data-model\\n- Expanded connection support to handle multiple child connection paths"},{"id":"/2022/08/22/2022-08-22-1.25.6 - Rapid Platform/1.25.6 - Rapid Platform","metadata":{"permalink":"/changelog/2022/08/22/2022-08-22-1.25.6 - Rapid Platform/1.25.6 - Rapid Platform","source":"@site/blog/2022-08-22-1.25.6 - Rapid Platform/2022-08-22-1.25.6 - Rapid Platform.md","title":"1.25.6 - Hotfix 1","description":"22/08/2022","date":"2022-08-22T00:00:00.000Z","tags":[{"inline":true,"label":"Changelog","permalink":"/changelog/tags/changelog"}],"readingTime":0.2,"hasTruncateMarker":false,"authors":[{"name":"Matt Franklin","title":"Documents","url":"https://github.com/MattFranklin-Rapid","email":"matthew@rapidplatform.com","imageURL":"https://github.com/MattFranklin-Rapid.png","key":"matt","page":null}],"frontMatter":{"authors":["matt"],"tags":["Changelog"]},"unlisted":false,"prevItem":{"title":"1.25.11 - Time Slot Component","permalink":"/changelog/2022/09/08/2022-09-08-1.25.11 - Rapid Platform/1.25.11 - Rapid Platform"},"nextItem":{"title":"1.25.6 - Minilith Performance","permalink":"/changelog/2022/08/18/2022-08-18-1.25.6 - Rapid Platform/1.25.6 - Rapid Platform"}},"content":"22/08/2022\\n\\n:::warning\\n1.25.6 caused a regression that resulted in the site file becoming immutable in rare circumstances. This resulted in the inability to do many common actions \\n:::\\n\\n## Bug Fixes\\n\\n- Fixed an issue where the site file becomes \'locked\'"},{"id":"/2022/08/18/2022-08-18-1.25.6 - Rapid Platform/1.25.6 - Rapid Platform","metadata":{"permalink":"/changelog/2022/08/18/2022-08-18-1.25.6 - Rapid Platform/1.25.6 - Rapid Platform","source":"@site/blog/2022-08-18-1.25.6 - Rapid Platform/2022-08-18-1.25.6 - Rapid Platform.md","title":"1.25.6 - Minilith Performance","description":"18/08/2022","date":"2022-08-18T00:00:00.000Z","tags":[{"inline":true,"label":"Changelog","permalink":"/changelog/tags/changelog"}],"readingTime":0.08,"hasTruncateMarker":false,"authors":[{"name":"Matt Franklin","title":"Documents","url":"https://github.com/MattFranklin-Rapid","email":"matthew@rapidplatform.com","imageURL":"https://github.com/MattFranklin-Rapid.png","key":"matt","page":null}],"frontMatter":{"authors":["matt"],"tags":["Changelog"]},"unlisted":false,"prevItem":{"title":"1.25.6 - Hotfix 1","permalink":"/changelog/2022/08/22/2022-08-22-1.25.6 - Rapid Platform/1.25.6 - Rapid Platform"},"nextItem":{"title":"1.25.5 - Workflow Usability","permalink":"/changelog/2022/08/11/2022-08-11-1.25.5 - Rapid Platform/1.25.5 - Rapid Platform"}},"content":"18/08/2022\\n\\n## Bug Fixes\\n\\n- Fixed an issue where bulk creating items sometimes caused server instability"},{"id":"/2022/08/11/2022-08-11-1.25.5 - Rapid Platform/1.25.5 - Rapid Platform","metadata":{"permalink":"/changelog/2022/08/11/2022-08-11-1.25.5 - Rapid Platform/1.25.5 - Rapid Platform","source":"@site/blog/2022-08-11-1.25.5 - Rapid Platform/2022-08-11-1.25.5 - Rapid Platform.md","title":"1.25.5 - Workflow Usability","description":"11/08/2022","date":"2022-08-11T00:00:00.000Z","tags":[{"inline":true,"label":"Changelog","permalink":"/changelog/tags/changelog"}],"readingTime":0.09,"hasTruncateMarker":false,"authors":[{"name":"Matt Franklin","title":"Documents","url":"https://github.com/MattFranklin-Rapid","email":"matthew@rapidplatform.com","imageURL":"https://github.com/MattFranklin-Rapid.png","key":"matt","page":null}],"frontMatter":{"authors":["matt"],"tags":["Changelog"]},"unlisted":false,"prevItem":{"title":"1.25.6 - Minilith Performance","permalink":"/changelog/2022/08/18/2022-08-18-1.25.6 - Rapid Platform/1.25.6 - Rapid Platform"},"nextItem":{"title":"1.25.3 - Saving Minor Fix","permalink":"/changelog/2022/07/28/2022-07-28-1.25.3 - Rapid Platform/1.25.3 - Rapid Platform"}},"content":"11/08/2022\\n\\n## Bug Fixes\\n\\n- Fixed an issue where configuring embedded forms in workflow would return an error"},{"id":"/2022/07/28/2022-07-28-1.25.3 - Rapid Platform/1.25.3 - Rapid Platform","metadata":{"permalink":"/changelog/2022/07/28/2022-07-28-1.25.3 - Rapid Platform/1.25.3 - Rapid Platform","source":"@site/blog/2022-07-28-1.25.3 - Rapid Platform/2022-07-28-1.25.3 - Rapid Platform.md","title":"1.25.3 - Saving Minor Fix","description":"28/07/2022","date":"2022-07-28T00:00:00.000Z","tags":[{"inline":true,"label":"Changelog","permalink":"/changelog/tags/changelog"}],"readingTime":0.06,"hasTruncateMarker":false,"authors":[{"name":"Matt Franklin","title":"Documents","url":"https://github.com/MattFranklin-Rapid","email":"matthew@rapidplatform.com","imageURL":"https://github.com/MattFranklin-Rapid.png","key":"matt","page":null}],"frontMatter":{"authors":["matt"],"tags":["Changelog"]},"unlisted":false,"prevItem":{"title":"1.25.5 - Workflow Usability","permalink":"/changelog/2022/08/11/2022-08-11-1.25.5 - Rapid Platform/1.25.5 - Rapid Platform"},"nextItem":{"title":"1.25.4 - Adaptive Scheduler","permalink":"/changelog/2022/07/28/2022-07-28-1.25.4 - Rapid Platform/1.25.4 - Rapid Platform"}},"content":"28/07/2022\\n\\n## Bug Fixes\\n\\n- Fixed toLowerCase error when saving items"},{"id":"/2022/07/28/2022-07-28-1.25.4 - Rapid Platform/1.25.4 - Rapid Platform","metadata":{"permalink":"/changelog/2022/07/28/2022-07-28-1.25.4 - Rapid Platform/1.25.4 - Rapid Platform","source":"@site/blog/2022-07-28-1.25.4 - Rapid Platform/2022-07-28-1.25.4 - Rapid Platform.md","title":"1.25.4 - Adaptive Scheduler","description":"28/07/2022","date":"2022-07-28T00:00:00.000Z","tags":[{"inline":true,"label":"Changelog","permalink":"/changelog/tags/changelog"}],"readingTime":0.53,"hasTruncateMarker":false,"authors":[{"name":"Matt Franklin","title":"Documents","url":"https://github.com/MattFranklin-Rapid","email":"matthew@rapidplatform.com","imageURL":"https://github.com/MattFranklin-Rapid.png","key":"matt","page":null}],"frontMatter":{"authors":["matt"],"tags":["Changelog"]},"unlisted":false,"prevItem":{"title":"1.25.3 - Saving Minor Fix","permalink":"/changelog/2022/07/28/2022-07-28-1.25.3 - Rapid Platform/1.25.3 - Rapid Platform"},"nextItem":{"title":"1.25.2 - Workflow Get Items","permalink":"/changelog/2022/07/07/2022-07-07-1.25.2 - Rapid Platform/1.25.2 - Rapid Platform"}},"content":"28/07/2022\\n\\n## Features \\n\\n### Added the scheduler Control\\n\\nAdds the DHX scheduler to Adaptive Designer. Currently this control is in preview mode and was built specifically around providing a booking system. There are more generic uses for this control and these will be more explicitly supported as time goes on. \\n\\n## Bug Fixes\\n\\n- Fixed an issue where the sharepoint permission call can fail in certain cases\\n- Fixed an issue where a timeout occurs on save when all permissions are cleared from an item\\n\\n## UI/UX Fixes\\n\\n- Added the ability to set number of default sections in a repeating section\\n- Added the ability to configure multilookup parent connections"},{"id":"/2022/07/07/2022-07-07-1.25.2 - Rapid Platform/1.25.2 - Rapid Platform","metadata":{"permalink":"/changelog/2022/07/07/2022-07-07-1.25.2 - Rapid Platform/1.25.2 - Rapid Platform","source":"@site/blog/2022-07-07-1.25.2 - Rapid Platform/2022-07-07-1.25.2 - Rapid Platform.md","title":"1.25.2 - Workflow Get Items","description":"07/07/2022","date":"2022-07-07T00:00:00.000Z","tags":[{"inline":true,"label":"Changelog","permalink":"/changelog/tags/changelog"}],"readingTime":0.67,"hasTruncateMarker":false,"authors":[{"name":"Matt Franklin","title":"Documents","url":"https://github.com/MattFranklin-Rapid","email":"matthew@rapidplatform.com","imageURL":"https://github.com/MattFranklin-Rapid.png","key":"matt","page":null}],"frontMatter":{"authors":["matt"],"tags":["Changelog"]},"unlisted":false,"prevItem":{"title":"1.25.4 - Adaptive Scheduler","permalink":"/changelog/2022/07/28/2022-07-28-1.25.4 - Rapid Platform/1.25.4 - Rapid Platform"},"nextItem":{"title":"1.25.0 - Hotfix 1","permalink":"/changelog/2022/06/27/2022-06-27-1.25.0 - Rapid Platform/1.25.0 - Rapid Platform"}},"content":"07/07/2022\\n\\n## Features\\n\\n### Added a get Items Service task to the workflow engine\\n\\nA recurring theme in workflows had process writers going to an external source (like power automate) via a webhook in workflow which simply returns a list of items that can be used in the workflow. As this was such a common action it is now possible to directly configure a service task by setting its type to \'Get Items\' This allows for filters, select statements and the option to only get items in a linked context.\\n\\n## UI/UX Fixes\\n\\n- Added the ability for subquery and computed fields to be set as titles on the board control\\n\\n## Bug Fixes\\n\\n- Fixed an issue where an item will get its permissions set to null if there are extra keys in the permissions object"},{"id":"/2022/06/27/2022-06-27-1.25.0 - Rapid Platform/1.25.0 - Rapid Platform","metadata":{"permalink":"/changelog/2022/06/27/2022-06-27-1.25.0 - Rapid Platform/1.25.0 - Rapid Platform","source":"@site/blog/2022-06-27-1.25.0 - Rapid Platform/2022-06-27-1.25.0 - Rapid Platform.md","title":"1.25.0 - Hotfix 1","description":"27/06/2022","date":"2022-06-27T00:00:00.000Z","tags":[{"inline":true,"label":"Changelog","permalink":"/changelog/tags/changelog"}],"readingTime":0.24,"hasTruncateMarker":false,"authors":[{"name":"Matt Franklin","title":"Documents","url":"https://github.com/MattFranklin-Rapid","email":"matthew@rapidplatform.com","imageURL":"https://github.com/MattFranklin-Rapid.png","key":"matt","page":null}],"frontMatter":{"authors":["matt"],"tags":["Changelog"]},"unlisted":false,"prevItem":{"title":"1.25.2 - Workflow Get Items","permalink":"/changelog/2022/07/07/2022-07-07-1.25.2 - Rapid Platform/1.25.2 - Rapid Platform"},"nextItem":{"title":"1.25.0 - Form Service Fast Renderer","permalink":"/changelog/2022/06/24/2022-06-24-1.25.0 - Rapid Platform/1.25.0 - Rapid Platform"}},"content":"27/06/2022\\n\\n:::warning\\n1.25.0 caused a regression that resulted in a page crash when viewing or previewing a form that contained an email field within a repeating section\\n:::\\n\\n# Bug Fixes\\n\\n- Fixed a page crash when viewing a form containing an email field within a repeating section"},{"id":"/2022/06/24/2022-06-24-1.25.0 - Rapid Platform/1.25.0 - Rapid Platform","metadata":{"permalink":"/changelog/2022/06/24/2022-06-24-1.25.0 - Rapid Platform/1.25.0 - Rapid Platform","source":"@site/blog/2022-06-24-1.25.0 - Rapid Platform/2022-06-24-1.25.0 - Rapid Platform.md","title":"1.25.0 - Form Service Fast Renderer","description":"24/06/2022","date":"2022-06-24T00:00:00.000Z","tags":[{"inline":true,"label":"Changelog","permalink":"/changelog/tags/changelog"}],"readingTime":0.86,"hasTruncateMarker":false,"authors":[{"name":"Matt Franklin","title":"Documents","url":"https://github.com/MattFranklin-Rapid","email":"matthew@rapidplatform.com","imageURL":"https://github.com/MattFranklin-Rapid.png","key":"matt","page":null}],"frontMatter":{"authors":["matt"],"tags":["Changelog"]},"unlisted":false,"prevItem":{"title":"1.25.0 - Hotfix 1","permalink":"/changelog/2022/06/27/2022-06-27-1.25.0 - Rapid Platform/1.25.0 - Rapid Platform"},"nextItem":{"title":"1.24.8 - Form Service Fast Renderer","permalink":"/changelog/2022/06/17/2022-06-17-1.24.8 - Rapid Platform/1.24.8 - Rapid Platform"}},"content":"24/06/2022\\n\\n# Features\\n\\n## Fast renderer in Form service\\n\\nA different renderer is now used in the form service, notable speed improvements should be noted when using it, especially with longer forms. Virtualisation is added to repeating sections and views where only 5 instances/rows will be rendered at any given time. \\n\\n## Bug Fixes\\n\\n- Removed an erroneous multi page nav menu control\\n- Fixed an issue where data can be lost when navigating multi pages\\n- Fixed an issue where CSS classes were propagating to child elements\\n- Fixed an issue where views were not being fetched when configuring a view connection\\n- Fixed a page crash when configuring a condition configured to trigger on \'falsey\'\\n- Fixed the inability to set and view choices for choice fields in Designer\\n- Fixed the inability to configure radio inputs\\n\\n# UI/UX Fixes\\n\\n- Fixed an issue where lookup config was not loading for connections in Designer\\n- Fixed an issue where labels and descriptions sometimes propagated to child elements\\n- Fixed an issue where data can bleed across input attributes in designer"},{"id":"/2022/06/17/2022-06-17-1.24.8 - Rapid Platform/1.24.8 - Rapid Platform","metadata":{"permalink":"/changelog/2022/06/17/2022-06-17-1.24.8 - Rapid Platform/1.24.8 - Rapid Platform","source":"@site/blog/2022-06-17-1.24.8 - Rapid Platform/2022-06-17-1.24.8 - Rapid Platform.md","title":"1.24.8 - Form Service Fast Renderer","description":"17/06/2022","date":"2022-06-17T00:00:00.000Z","tags":[{"inline":true,"label":"Changelog","permalink":"/changelog/tags/changelog"}],"readingTime":0.67,"hasTruncateMarker":false,"authors":[{"name":"Matt Franklin","title":"Documents","url":"https://github.com/MattFranklin-Rapid","email":"matthew@rapidplatform.com","imageURL":"https://github.com/MattFranklin-Rapid.png","key":"matt","page":null}],"frontMatter":{"authors":["matt"],"tags":["Changelog"]},"unlisted":false,"prevItem":{"title":"1.25.0 - Form Service Fast Renderer","permalink":"/changelog/2022/06/24/2022-06-24-1.25.0 - Rapid Platform/1.25.0 - Rapid Platform"},"nextItem":{"title":"1.24.7 - Hotfix 1","permalink":"/changelog/2022/06/14/2022-06-14-1.24.7 - Rapid Platform/1.24.7 - Rapid Platform"}},"content":"17/06/2022\\n\\n## Bug Fixes\\n\\n- Fixed an issue where email fields would set their default value to \'true\' automatically\\n- Fixed an issue where hidden fields are not being applied correctly in Designer and Preview\\n- Fixed an issue where cancelling form details no longer clears the form in Designer\\n- Fixed the inability to clone a previously cloned element in Designer\\n- Fixed an issue where the first page of multi page is navigated to erroneously\\n- Fixed an issue where views are not fetched when configuring a view in Designer\\n\\n## UI/UX Fixes\\n\\n- Fixed an issue of config attributes in designer bleeding across different fields\\n- Fixed text fields rendering as not read only in Designer\\n- Updated the component tree in Designer to be more usable\\n- Fixed an issue where repeating sections failed to show one by default"},{"id":"/2022/06/14/2022-06-14-1.24.7 - Rapid Platform/1.24.7 - Rapid Platform","metadata":{"permalink":"/changelog/2022/06/14/2022-06-14-1.24.7 - Rapid Platform/1.24.7 - Rapid Platform","source":"@site/blog/2022-06-14-1.24.7 - Rapid Platform/2022-06-14-1.24.7 - Rapid Platform.md","title":"1.24.7 - Hotfix 1","description":"14/06/2022","date":"2022-06-14T00:00:00.000Z","tags":[{"inline":true,"label":"Changelog","permalink":"/changelog/tags/changelog"}],"readingTime":0.19,"hasTruncateMarker":false,"authors":[{"name":"Matt Franklin","title":"Documents","url":"https://github.com/MattFranklin-Rapid","email":"matthew@rapidplatform.com","imageURL":"https://github.com/MattFranklin-Rapid.png","key":"matt","page":null}],"frontMatter":{"authors":["matt"],"tags":["Changelog"]},"unlisted":false,"prevItem":{"title":"1.24.8 - Form Service Fast Renderer","permalink":"/changelog/2022/06/17/2022-06-17-1.24.8 - Rapid Platform/1.24.8 - Rapid Platform"},"nextItem":{"title":"1.24.7 - Adaptive Designer Performance Overhaul","permalink":"/changelog/2022/06/10/2022-06-10-1.24.7 - Rapid Platform/1.24.7 - Rapid Platform"}},"content":"14/06/2022\\n\\n:::warning\\n1.24.7 caused a regression with bulk updates in gantt, boards and the bulk update action which caused only the first item to get updated\\n:::\\n\\n## Bug Fixes\\n\\n- Fixed an issue with bulk updates not performing"},{"id":"/2022/06/10/2022-06-10-1.24.7 - Rapid Platform/1.24.7 - Rapid Platform","metadata":{"permalink":"/changelog/2022/06/10/2022-06-10-1.24.7 - Rapid Platform/1.24.7 - Rapid Platform","source":"@site/blog/2022-06-10-1.24.7 - Rapid Platform/2022-06-10-1.24.7 - Rapid Platform.md","title":"1.24.7 - Adaptive Designer Performance Overhaul","description":"10/06/2022","date":"2022-06-10T00:00:00.000Z","tags":[{"inline":true,"label":"Changelog","permalink":"/changelog/tags/changelog"}],"readingTime":0.55,"hasTruncateMarker":false,"authors":[{"name":"Matt Franklin","title":"Documents","url":"https://github.com/MattFranklin-Rapid","email":"matthew@rapidplatform.com","imageURL":"https://github.com/MattFranklin-Rapid.png","key":"matt","page":null}],"frontMatter":{"authors":["matt"],"tags":["Changelog"]},"unlisted":false,"prevItem":{"title":"1.24.7 - Hotfix 1","permalink":"/changelog/2022/06/14/2022-06-14-1.24.7 - Rapid Platform/1.24.7 - Rapid Platform"},"nextItem":{"title":"1.24.6 - Public Form Submission","permalink":"/changelog/2022/06/01/2022-06-01-1.24.6 - Rapid Platform/1.24.6 - Rapid Platform"}},"content":"10/06/2022\\n\\n## Features\\n\\n### Sharepoint Permission Sync\\n\\nWhen creating or editing an item with a drive and folder set, the same permissions applied to the item will be applied to that item\'s folder in sharepoint. This ensures that an item\'s permissions will be the same as the file permissions.\\n\\n## UI/UX Fixes\\n\\n- Added ability to disable create button for current list on data tables in Explorer\\n- Fixed lookups in public forms displaying \'0\' when unset\\n- Locale is now set correctly when exporting CSV from data table in Explorer\\n\\n## Improvements\\n\\n- Overhaul of Adaptive Designer and the Adaptive Renderer which results in major performance benefits. Render and load times are dramatically decreased"},{"id":"/2022/06/01/2022-06-01-1.24.6 - Rapid Platform/1.24.6 - Rapid Platform","metadata":{"permalink":"/changelog/2022/06/01/2022-06-01-1.24.6 - Rapid Platform/1.24.6 - Rapid Platform","source":"@site/blog/2022-06-01-1.24.6 - Rapid Platform/2022-06-01-1.24.6 - Rapid Platform.md","title":"1.24.6 - Public Form Submission","description":"1/06/2022","date":"2022-06-01T00:00:00.000Z","tags":[{"inline":true,"label":"Changelog","permalink":"/changelog/tags/changelog"}],"readingTime":0.31,"hasTruncateMarker":false,"authors":[{"name":"Matt Franklin","title":"Documents","url":"https://github.com/MattFranklin-Rapid","email":"matthew@rapidplatform.com","imageURL":"https://github.com/MattFranklin-Rapid.png","key":"matt","page":null}],"frontMatter":{"authors":["matt"],"tags":["Changelog"]},"unlisted":false,"prevItem":{"title":"1.24.7 - Adaptive Designer Performance Overhaul","permalink":"/changelog/2022/06/10/2022-06-10-1.24.7 - Rapid Platform/1.24.7 - Rapid Platform"},"nextItem":{"title":"1.24.5 - Workflow Linking","permalink":"/changelog/2022/05/26/2022-05-26-1.24.5 - Rapid Platform/1.24.5 - Rapid Platform"}},"content":"1/06/2022\\n\\n## Improvements\\n\\n- Public forms with pre-fill data that are missing the __metadata tag will now try to insert them where possible\\n\\n# Bug Fixes\\n\\n- Enabled the following relational data cases to be submitted successfully\\n- Single Item Create/Update\\n- View Create/Update\\n- View linked to Single item via Universal Link Create/Update\\n- View linked to Single item via Lookup Create/Update"},{"id":"/2022/05/26/2022-05-26-1.24.5 - Rapid Platform/1.24.5 - Rapid Platform","metadata":{"permalink":"/changelog/2022/05/26/2022-05-26-1.24.5 - Rapid Platform/1.24.5 - Rapid Platform","source":"@site/blog/2022-05-26-1.24.5 - Rapid Platform/2022-05-26-1.24.5 - Rapid Platform.md","title":"1.24.5 - Workflow Linking","description":"26/05/2022","date":"2022-05-26T00:00:00.000Z","tags":[{"inline":true,"label":"Changelog","permalink":"/changelog/tags/changelog"}],"readingTime":0.15,"hasTruncateMarker":false,"authors":[{"name":"Matt Franklin","title":"Documents","url":"https://github.com/MattFranklin-Rapid","email":"matthew@rapidplatform.com","imageURL":"https://github.com/MattFranklin-Rapid.png","key":"matt","page":null}],"frontMatter":{"authors":["matt"],"tags":["Changelog"]},"unlisted":false,"prevItem":{"title":"1.24.6 - Public Form Submission","permalink":"/changelog/2022/06/01/2022-06-01-1.24.6 - Rapid Platform/1.24.6 - Rapid Platform"},"nextItem":{"title":"1.24.4 - Adaptive Designer Improvements","permalink":"/changelog/2022/05/12/2022-05-12-1.24.4 - Rapid Platform/1.24.4 - Rapid Platform"}},"content":"26/05/2022\\n\\n## Bug Fixes\\n\\n- Fixed erroneous validation preventing creating a universal link between a task and a custom list that contains the word task in its name via Workflow"},{"id":"/2022/05/12/2022-05-12-1.24.4 - Rapid Platform/1.24.4 - Rapid Platform","metadata":{"permalink":"/changelog/2022/05/12/2022-05-12-1.24.4 - Rapid Platform/1.24.4 - Rapid Platform","source":"@site/blog/2022-05-12-1.24.4 - Rapid Platform/2022-05-12-1.24.4 - Rapid Platform.md","title":"1.24.4 - Adaptive Designer Improvements","description":"12/05/2022","date":"2022-05-12T00:00:00.000Z","tags":[{"inline":true,"label":"Changelog","permalink":"/changelog/tags/changelog"}],"readingTime":0.57,"hasTruncateMarker":false,"authors":[{"name":"Matt Franklin","title":"Documents","url":"https://github.com/MattFranklin-Rapid","email":"matthew@rapidplatform.com","imageURL":"https://github.com/MattFranklin-Rapid.png","key":"matt","page":null}],"frontMatter":{"authors":["matt"],"tags":["Changelog"]},"unlisted":false,"prevItem":{"title":"1.24.5 - Workflow Linking","permalink":"/changelog/2022/05/26/2022-05-26-1.24.5 - Rapid Platform/1.24.5 - Rapid Platform"},"nextItem":{"title":"1.24.3 - Adaptive Designer Improvements","permalink":"/changelog/2022/05/05/2022-05-05-1.24.3 - Rapid Platform/1.24.3 - Rapid Platform"}},"content":"12/05/2022\\n\\n## Bug Fixes\\n\\n- Prefill Data now gets constructed correctly by workflow in single item cases\\n- Fixed an issue prefill data failed to load in universal link scenarios\\n- Fixed a page crash for view connections that did not contain a columnName attribute\\n- Fixed an issue where UI will not update in workflow to input prefill data in certain cases\\n- Fixed an issue where prefill data cannot be configured for 2 lookups with the same name\\n- Fixed an issue where files failed to be submitted upon form submission\\n\\n## UI/UX Fixes\\n\\n- Fixed an issue where first click will not perform add repeating section actions\\n- List and column name is now prepended to array prefill data"},{"id":"/2022/05/05/2022-05-05-1.24.3 - Rapid Platform/1.24.3 - Rapid Platform","metadata":{"permalink":"/changelog/2022/05/05/2022-05-05-1.24.3 - Rapid Platform/1.24.3 - Rapid Platform","source":"@site/blog/2022-05-05-1.24.3 - Rapid Platform/2022-05-05-1.24.3 - Rapid Platform.md","title":"1.24.3 - Adaptive Designer Improvements","description":"05/05/2022","date":"2022-05-05T00:00:00.000Z","tags":[{"inline":true,"label":"Changelog","permalink":"/changelog/tags/changelog"}],"readingTime":0.52,"hasTruncateMarker":false,"authors":[{"name":"Matt Franklin","title":"Documents","url":"https://github.com/MattFranklin-Rapid","email":"matthew@rapidplatform.com","imageURL":"https://github.com/MattFranklin-Rapid.png","key":"matt","page":null}],"frontMatter":{"authors":["matt"],"tags":["Changelog"]},"unlisted":false,"prevItem":{"title":"1.24.4 - Adaptive Designer Improvements","permalink":"/changelog/2022/05/12/2022-05-12-1.24.4 - Rapid Platform/1.24.4 - Rapid Platform"},"nextItem":{"title":"1.24.2 - Adaptive Designer Improvements","permalink":"/changelog/2022/04/25/2022-04-25-1.24.2 - Rapid Platform/1.24.2 - Rapid Platform"}},"content":"05/05/2022\\n\\n## Bug Fixes\\n\\n- Fixed an issue where action buttons were anchoring to a point on page unexpectedly\\n- Fixed an issue where starting conditions are applied in the design space when configuring conditions\\n\\n## UI/UX Fixes\\n\\n- Added number input to sliders\\n- Removed some RAPID system controls from the context menu\\n- Now able to set a width and height on embedded controls\\n- Added label to accordion sections\\n- Added the ability to enable time on embedded form date fields in workflow\\n- In Explorer can render embedded forms with date fields with time inputs\\n\\n# Improvements\\n\\n- Date fields correctly store their value in memory as ISO strings"},{"id":"/2022/04/25/2022-04-25-1.24.2 - Rapid Platform/1.24.2 - Rapid Platform","metadata":{"permalink":"/changelog/2022/04/25/2022-04-25-1.24.2 - Rapid Platform/1.24.2 - Rapid Platform","source":"@site/blog/2022-04-25-1.24.2 - Rapid Platform/2022-04-25-1.24.2 - Rapid Platform.md","title":"1.24.2 - Adaptive Designer Improvements","description":"28/04/2022","date":"2022-04-25T00:00:00.000Z","tags":[{"inline":true,"label":"Changelog","permalink":"/changelog/tags/changelog"}],"readingTime":0.64,"hasTruncateMarker":false,"authors":[{"name":"Matt Franklin","title":"Documents","url":"https://github.com/MattFranklin-Rapid","email":"matthew@rapidplatform.com","imageURL":"https://github.com/MattFranklin-Rapid.png","key":"matt","page":null}],"frontMatter":{"authors":["matt"],"tags":["Changelog"]},"unlisted":false,"prevItem":{"title":"1.24.3 - Adaptive Designer Improvements","permalink":"/changelog/2022/05/05/2022-05-05-1.24.3 - Rapid Platform/1.24.3 - Rapid Platform"},"nextItem":{"title":"1.24.1 - Adaptive Designer Improvements","permalink":"/changelog/2022/04/21/2022-04-21-1.24.1 - Rapid Platform/1.24.1 - Rapid Platform"}},"content":"28/04/2022\\n\\n## Bug Fixes\\n\\n- Fixed an issue where repeating sections would display the data of one shared item rather than having their own unique values\\n- Now Able to view dates in excel correctly when exporting as CSV from a data table\\n- Fixed a page crash when adding an element to a section that has fetch Items turned on\\n- Removing a connection now removes all connection data from form schema\\n- Fixed an issue where the column layout will apply row spacing above the top row\\n- Fixed an issue where default values could not be applied to number fields\\n- Fixed the TabControl component where it would not render correctly\\n\\n## UI/UX Fixes\\n\\n- Clearing border in the styles tab now removes border properly\\n- Re-Added Hidden attribute to fields"},{"id":"/2022/04/21/2022-04-21-1.24.1 - Rapid Platform/1.24.1 - Rapid Platform","metadata":{"permalink":"/changelog/2022/04/21/2022-04-21-1.24.1 - Rapid Platform/1.24.1 - Rapid Platform","source":"@site/blog/2022-04-21-1.24.1 - Rapid Platform/2022-04-21-1.24.1 - Rapid Platform.md","title":"1.24.1 - Adaptive Designer Improvements","description":"21/04/2022","date":"2022-04-21T00:00:00.000Z","tags":[{"inline":true,"label":"Changelog","permalink":"/changelog/tags/changelog"}],"readingTime":0.59,"hasTruncateMarker":false,"authors":[{"name":"Matt Franklin","title":"Documents","url":"https://github.com/MattFranklin-Rapid","email":"matthew@rapidplatform.com","imageURL":"https://github.com/MattFranklin-Rapid.png","key":"matt","page":null}],"frontMatter":{"authors":["matt"],"tags":["Changelog"]},"unlisted":false,"prevItem":{"title":"1.24.2 - Adaptive Designer Improvements","permalink":"/changelog/2022/04/25/2022-04-25-1.24.2 - Rapid Platform/1.24.2 - Rapid Platform"},"nextItem":{"title":"1.24.0 - Adaptive Framework Improvements","permalink":"/changelog/2022/04/14/2022-04-14-1.24.0 - Rapid Platform/1.24.0 - Rapid Platform"}},"content":"21/04/2022\\n\\n## Bug Fixes\\n\\n- Fixed an issue where duplicate principals can get created rather than linking existing ones in rare cases when using Omnichannel\\n\\n## UI/UX Fixes\\n\\n- Added a column layout control which allows for evenly spaced columns\\n- Added ability to add a link to an image which will navigate on clicking of the image\\n- Updated the embedded control to allow the input of an iframe html src (like youtube embed)\\n- Currency fields now display the correct UI\\n- Percentage fields now show % icon\\n- Removed validation message on email control\\n- Added the slider input control - outputs a number \\n- Updated the Rating input control - outputs a number\\n\\n## Improvements\\n\\n- Started to move away form UUID to using NanoID instead"},{"id":"/2022/04/14/2022-04-14-1.24.0 - Rapid Platform/1.24.0 - Rapid Platform","metadata":{"permalink":"/changelog/2022/04/14/2022-04-14-1.24.0 - Rapid Platform/1.24.0 - Rapid Platform","source":"@site/blog/2022-04-14-1.24.0 - Rapid Platform/2022-04-14-1.24.0 - Rapid Platform.md","title":"1.24.0 - Adaptive Framework Improvements","description":"14/04/2022","date":"2022-04-14T00:00:00.000Z","tags":[{"inline":true,"label":"Changelog","permalink":"/changelog/tags/changelog"}],"readingTime":0.7,"hasTruncateMarker":false,"authors":[{"name":"Matt Franklin","title":"Documents","url":"https://github.com/MattFranklin-Rapid","email":"matthew@rapidplatform.com","imageURL":"https://github.com/MattFranklin-Rapid.png","key":"matt","page":null}],"frontMatter":{"authors":["matt"],"tags":["Changelog"]},"unlisted":false,"prevItem":{"title":"1.24.1 - Adaptive Designer Improvements","permalink":"/changelog/2022/04/21/2022-04-21-1.24.1 - Rapid Platform/1.24.1 - Rapid Platform"},"nextItem":{"title":"1.23.0 - Adaptive Data Connections","permalink":"/changelog/2022/04/07/2022-04-07-1.23.0 - Rapid Platform/1.23.0 - Rapid Platform"}},"content":"14/04/2022\\n\\n## Features\\n\\n### Data Table\\n\\nAs a companion to repeating sections the Adaptive Designer now supports the data table control for a more compact way to create, view and edit several items. This control is powered by the new Adaptive data connections using the view mode and is supported in the Anonymous Forms experience.\\n\\n## Bug Fixes\\n\\n- Fixed creating meeting events more than 3 months in the future causing automation deletion of that event\\n- Fixed crash on sections when using show conditions on children elements\\n- Updated flip card control to show children elements correctly\\n\\n## UI/UX Fixes\\n\\n- Updated flip card control to show configuration panel correctly\\n- Updated icon for flip card control\\n- Updated boolean controls to new skinny switch\\n\\n## Improvements\\n\\n- Upgraded Carousel control to work with data connections\\n- Enabled overriding of default data context when using pre-fill data"},{"id":"/2022/04/07/2022-04-07-1.23.0 - Rapid Platform/1.23.0 - Rapid Platform","metadata":{"permalink":"/changelog/2022/04/07/2022-04-07-1.23.0 - Rapid Platform/1.23.0 - Rapid Platform","source":"@site/blog/2022-04-07-1.23.0 - Rapid Platform/2022-04-07-1.23.0 - Rapid Platform.md","title":"1.23.0 - Adaptive Data Connections","description":"07/04/2022","date":"2022-04-07T00:00:00.000Z","tags":[{"inline":true,"label":"Changelog","permalink":"/changelog/tags/changelog"}],"readingTime":1.32,"hasTruncateMarker":false,"authors":[{"name":"Matt Franklin","title":"Documents","url":"https://github.com/MattFranklin-Rapid","email":"matthew@rapidplatform.com","imageURL":"https://github.com/MattFranklin-Rapid.png","key":"matt","page":null}],"frontMatter":{"authors":["matt"],"tags":["Changelog"]},"unlisted":false,"prevItem":{"title":"1.24.0 - Adaptive Framework Improvements","permalink":"/changelog/2022/04/14/2022-04-14-1.24.0 - Rapid Platform/1.24.0 - Rapid Platform"},"nextItem":{"title":"1.22.3 - Adaptive Data Connections","permalink":"/changelog/2022/03/31/2022-03-31-1.22.3 - Rapid Platform/1.22.3 - Rapid Platform"}},"content":"07/04/2022\\n\\n## Bug Fixes\\n\\n- Fixed whole number control using the decimal input instead of integer input\\n- Prevented grid control generating erroneous element IDs\\n- Prevented creating a new form setting the page into an error state depending on which controls were added before save\\n- Reinstated RAPID Choices being able to use choices defined in the site\\n- Fixed panel crash when collapsing the connections configuration\\n- Updated Carousel to be a layout control type and pass connections\\n- Fixed some configuration failing to dirty the form and prevent saving\\n\\n## UI/UX Fixes\\n\\n- Removed debug controls from configuration panels\\n- Stopped editing fields from forcing the cursor to the end of the content\\n- Improved control search to accept any text characters and retain it\'s group panel in all states\\n- Ensured Rapid Attributes configuration is no longer used in configuration panels\\n- Disabled multi-page menu nav control when in edit mode\\n- Reinstated placeholder behaviour missing on various fields\\n- Allowed title to reflect an element label when the title has not been configured\\n- Enabled configuration panels to scroll\\n- Updated control categories to remove uncategorized and redundant field/input split\\n- The Style configuration tab will no longer \'remember\' the previous controls configuration\\n- Opening a Office 365 document in the file control will now default to opening the associated local application\\n- Updated default label for buttons to \'Submit\' from \'submit\'\\n\\n## Improvements\\n\\n- Added repeating section default buttons\\n- Enabled Submit button to handle multiple instances in Anonymous forms\\n- Added Contains and Equals condition rules for string and joi type conditions\\n- Updated conditions to not process on load in lieu of new initial state configuration"},{"id":"/2022/03/31/2022-03-31-1.22.3 - Rapid Platform/1.22.3 - Rapid Platform","metadata":{"permalink":"/changelog/2022/03/31/2022-03-31-1.22.3 - Rapid Platform/1.22.3 - Rapid Platform","source":"@site/blog/2022-03-31-1.22.3 - Rapid Platform/2022-03-31-1.22.3 - Rapid Platform.md","title":"1.22.3 - Adaptive Data Connections","description":"31/03/2022","date":"2022-03-31T00:00:00.000Z","tags":[{"inline":true,"label":"Changelog","permalink":"/changelog/tags/changelog"}],"readingTime":2.47,"hasTruncateMarker":false,"authors":[{"name":"Matt Franklin","title":"Documents","url":"https://github.com/MattFranklin-Rapid","email":"matthew@rapidplatform.com","imageURL":"https://github.com/MattFranklin-Rapid.png","key":"matt","page":null}],"frontMatter":{"authors":["matt"],"tags":["Changelog"]},"unlisted":false,"prevItem":{"title":"1.23.0 - Adaptive Data Connections","permalink":"/changelog/2022/04/07/2022-04-07-1.23.0 - Rapid Platform/1.23.0 - Rapid Platform"},"nextItem":{"title":"1.22.2 - RAPID Meetings","permalink":"/changelog/2022/03/24/2022-03-24-1.22.2 - Rapid Platform/1.22.2 - Rapid Platform"}},"content":"31/03/2022\\n\\n## Features\\n\\n### (Preview) Adaptive Connections\\n\\nThis release introduces the concept of data connections to Adaptive Schemas created in the Adaptive Designer. Data connections allow you to dictate where data comes from and goes to at a per element level of detail. This preview enables the configuration of the Rapid data connector which replaces the old Rapid Attributes configuration, with plans to extend to other services in the future.\\n\\nIn addition to being able to have your adaptive forms and apps communicate with more than just Rapid, this feature also enables the configuration of related data. For example, you can now create an adaptive form that creates (or updates) an Invoice along with an arbitrary number of invoice detail lines.\\n\\nThis feature is in preview with a heavy focus on usability improvements over the next week. Any feedback on your experience using connections is highly appreciated.\\n\\n### Fetch and Save buttons\\n\\nAlong with being able to define more complicated data structures in your adaptive forms, we have also added actions to control fetching and saving data from your connections. These new actions can be applied to action buttons and allow the updating/saving of specific controls in your form.\\n\\nAs the Save action only targets one element, complex forms with many disparate items are expected to still use the Submit action to save everything at once.\\n\\n### Improved Conditions\\n\\nConditions also got some love in this release. After feedback we have added an initial state configuration so you can now have forms elements that start hidden/disabled and \'unlock\' as their condition is met. We have added in Equals and Contains conditions for text data, also thanks to your feedback.\\n\\n## Bug Fixes\\n\\n- Prevented adding controls to blank adaptive sections crashing the page\\n- Fixed quickly creating blank adaptive schemas saving corrupt\\n- Handled extended characters when searching for controls in the adaptive control picker\\n- Prevented page crash when navigating to a new adaptive schema and editing it before all controls had loaded\\n- Removed initial condition computation in lieu of initial state setting\\n- Resolved some cases where adding controls resolved in a corrupt element path\\n- Prevented adaptive grid crashing when trying to render negative columns\\n- Fixed adding multi-line of text inputs actually adding a single-line of text control instead\\n- Fixed adding a whole number control just adding a number control instead\\n- Fixed missing placeholder configuration on input field controls\\n- Fixed choice fields trying to save their display content instead of their value\\n\\n## UI/UX Fixes\\n\\n- Enabled adding of system fields to adaptive schemas\\n- Removed Rapid Attributes panel in lieu of new connections infrastructure\\n- Applied element connection controls to all adaptive elements\\n- Added Rapid view selector to connection configuration panel\\n- Added return to site picker / return to launchpad buttons to main adaptive designer page\\n- Enabled panel scroll in configuration panels\\n- Removed debug \'data path\' controls on some element configuration panels\\n- Set title of elements to mirror label when empty\\n- Disabled multi-page menu in design mode"},{"id":"/2022/03/24/2022-03-24-1.22.2 - Rapid Platform/1.22.2 - Rapid Platform","metadata":{"permalink":"/changelog/2022/03/24/2022-03-24-1.22.2 - Rapid Platform/1.22.2 - Rapid Platform","source":"@site/blog/2022-03-24-1.22.2 - Rapid Platform/2022-03-24-1.22.2 - Rapid Platform.md","title":"1.22.2 - RAPID Meetings","description":"24/03/2022","date":"2022-03-24T00:00:00.000Z","tags":[{"inline":true,"label":"Changelog","permalink":"/changelog/tags/changelog"}],"readingTime":1.54,"hasTruncateMarker":false,"authors":[{"name":"Matt Franklin","title":"Documents","url":"https://github.com/MattFranklin-Rapid","email":"matthew@rapidplatform.com","imageURL":"https://github.com/MattFranklin-Rapid.png","key":"matt","page":null}],"frontMatter":{"authors":["matt"],"tags":["Changelog"]},"unlisted":false,"prevItem":{"title":"1.22.3 - Adaptive Data Connections","permalink":"/changelog/2022/03/31/2022-03-31-1.22.3 - Rapid Platform/1.22.3 - Rapid Platform"},"nextItem":{"title":"1.22.0 - SendGrid Support","permalink":"/changelog/2022/03/10/2022-03-10-1.22.0 - Rapid Platform/1.22.0 - Rapid Platform"}},"content":"24/03/2022\\n\\n## Features\\n\\n### RAPID Meetings\\n\\nIt is now possible to create manage and sync meetings and meeting events through RAPID. Installing the created Meeting bundle onto your site will give you access to this new feature. A key feature of Meetings is that it will sync with outlook. It will create outlook events and keep them synced to the meeting items in RAPID.\\n\\n### Date Time Field Configuration\\n\\nWhen configuring page definitions in RAPID Designer, it is now possible to specify on the attributes of a date time field for time to be configurable. This will allow for a specific time to be saved to an item when viewing the field on the particular page that has time enabled on the field. This time field uses the user\'s chrome locale so ensuring it is set correctly is important. \\n\\n## Bug Fixes \\n\\n- Prevented Multilookups and multi line text fields being added the all view upon column creation\\n- Workflow now shows parent relationships correctly\\n- Form schemas are now no longer created corrupt if list name has a space in it\\n- Multilookups are no longer added to the default all view when they are created\\n- Completing a call activity in certain cases will no longer create duplicate tokens on a parallel merge\\n- Ensured update item actions receive correct data structure on submission\\n- Ensured tenant name is lower cased in anonymous forms when fetching css from cdn\\n- Sections in a multi page component within Adaptive Designer now have correct ID\'s\\n\\n## UI/UX Fixes\\n\\n- Fixed the displaying of elements in a horizontal layout within adaptive designer\\n- Ensured lookups and boolean fields are disabled on the canvas in adaptive designer\\n- Updated header and panel designer in Adaptive Designer\\n\\n## Improvements\\n \\n- Added an internal server for omnichannel\\n- Extended the lookup filter and create to scoped and linked items\\n- Added a new system list for internal webhooks"},{"id":"/2022/03/10/2022-03-10-1.22.0 - Rapid Platform/1.22.0 - Rapid Platform","metadata":{"permalink":"/changelog/2022/03/10/2022-03-10-1.22.0 - Rapid Platform/1.22.0 - Rapid Platform","source":"@site/blog/2022-03-10-1.22.0 - Rapid Platform/2022-03-10-1.22.0 - Rapid Platform.md","title":"1.22.0 - SendGrid Support","description":"10/03/2022","date":"2022-03-10T00:00:00.000Z","tags":[{"inline":true,"label":"Changelog","permalink":"/changelog/tags/changelog"}],"readingTime":1.79,"hasTruncateMarker":false,"authors":[{"name":"Matt Franklin","title":"Documents","url":"https://github.com/MattFranklin-Rapid","email":"matthew@rapidplatform.com","imageURL":"https://github.com/MattFranklin-Rapid.png","key":"matt","page":null}],"frontMatter":{"authors":["matt"],"tags":["Changelog"]},"unlisted":false,"prevItem":{"title":"1.22.2 - RAPID Meetings","permalink":"/changelog/2022/03/24/2022-03-24-1.22.2 - Rapid Platform/1.22.2 - Rapid Platform"},"nextItem":{"title":"1.21.1 - Fill in the Blank (Adaptive Designer)","permalink":"/changelog/2022/03/09/2022-03-09-1.21.1 - Rapid Platform/1.21.1 - Rapid Platform"}},"content":"10/03/2022\\n\\n## Features\\n\\n### SendGrid Support\\n\\nIt is now possible to integrate your RAPID Site with sendgrid. It is possible to send emails using this service both through action buttons configured for a list through Explorer and on send and receive tasks through workflow. Refer here for a breakdown on configuring sendgrid and integrations to your RAPID site.\\n\\n### Receive Tasks. \\nThese will pause a process run and wait for an email from the specified address to the specified address. Note, the receiving address must have its domain and subdomain configured through sendgrid\\n\\n### Send Tasks\\nThese allow you to select an integration and allow the selection of a template from sendgrid to use and allow for the input of variables into this template. It is possible to use expressions in the configuration for the send task in workflow. Executing a send task will send the email, in the template chosen (if one) to the nominated email. The process will then continue.\\n\\n### Hidden Field Support\\n\\nAdded the ability to set the hidden attribute on a field. Setting this will prevent the field from displaying on a form when that form is opened in either the form or anonymous form experiences. It makes the field immutable but retains the ability for the data to be submitted. The purpose of this is to allow forms to be configured and have data submitted without allowing the user to change or see the data. To configure a field to be hidden, set the hidden attribute on the desired field in the Adaptive Designer.\\n\\n## Bug Fixes \\n\\n- Prevented Multilookups and multi line text fields being added the all view upon column creation\\n- Workflow now shows parent relationships correctly\\n\\n## UI/UX Fixes\\n\\n- Changed the default pages for public form tasks to make them more usable\\n- Added the ability to use a context menu to add elements before and after in Adaptive Designer\\n- In Adaptive Designer, adding a user field will now set the column that is being looked up (full name)\\n\\n## Improvements\\n\\n- Added new system lists which lays the groundwork for Sendgrid and Twilio support (site repair required)\\n- In Adaptive Designer, adding elements now uses an action"},{"id":"/2022/03/09/2022-03-09-1.21.1 - Rapid Platform/1.21.1 - Rapid Platform","metadata":{"permalink":"/changelog/2022/03/09/2022-03-09-1.21.1 - Rapid Platform/1.21.1 - Rapid Platform","source":"@site/blog/2022-03-09-1.21.1 - Rapid Platform/2022-03-09-1.21.1 - Rapid Platform.md","title":"1.21.1 - Fill in the Blank (Adaptive Designer)","description":"09/03/2022","date":"2022-03-09T00:00:00.000Z","tags":[{"inline":true,"label":"Changelog","permalink":"/changelog/tags/changelog"}],"readingTime":0.71,"hasTruncateMarker":false,"authors":[{"name":"Matt Franklin","title":"Documents","url":"https://github.com/MattFranklin-Rapid","email":"matthew@rapidplatform.com","imageURL":"https://github.com/MattFranklin-Rapid.png","key":"matt","page":null}],"frontMatter":{"authors":["matt"],"tags":["Changelog"]},"unlisted":false,"prevItem":{"title":"1.22.0 - SendGrid Support","permalink":"/changelog/2022/03/10/2022-03-10-1.22.0 - Rapid Platform/1.22.0 - Rapid Platform"},"nextItem":{"title":"1.21.0 - Prefill Anonymous Form Data","permalink":"/changelog/2022/02/28/2022-02-28-1.21.0 - Rapid Platform/1.21.0 - Rapid Platform"}},"content":"09/03/2022\\n\\n## Features\\n\\n### Fill in the Blank Component\\n\\nAdded the following component into the Adaptive Designer. It allows for another way of entering data. The intended use for the fill in the blank component is when a form designer wants to make a questionnaire where the inputted answers will be within a block of text. The Fill in the blank component supports all field inputs along with the static text component.\\n\\n## Bug Fixes \\n\\n- Fixed adding preconfigured fields to a form through the context menu\\n\\n## UI/UX Fixes\\n\\n- Added the ability to select base entity fields when an inherited list is selected\\n- Lookups no longer show an ID in Anonymous forms\\n- Added the ability to clear attribute and style fields in Designer\\n- In Designer, made user fields read only\\n- Now able to set an icon and custom label on a submit button"},{"id":"/2022/02/28/2022-02-28-1.21.0 - Rapid Platform/1.21.0 - Rapid Platform","metadata":{"permalink":"/changelog/2022/02/28/2022-02-28-1.21.0 - Rapid Platform/1.21.0 - Rapid Platform","source":"@site/blog/2022-02-28-1.21.0 - Rapid Platform/2022-02-28-1.21.0 - Rapid Platform.md","title":"1.21.0 - Prefill Anonymous Form Data","description":"28/02/2022","date":"2022-02-28T00:00:00.000Z","tags":[{"inline":true,"label":"Changelog","permalink":"/changelog/tags/changelog"}],"readingTime":0.51,"hasTruncateMarker":false,"authors":[{"name":"Matt Franklin","title":"Documents","url":"https://github.com/MattFranklin-Rapid","email":"matthew@rapidplatform.com","imageURL":"https://github.com/MattFranklin-Rapid.png","key":"matt","page":null}],"frontMatter":{"authors":["matt"],"tags":["Changelog"]},"unlisted":false,"prevItem":{"title":"1.21.1 - Fill in the Blank (Adaptive Designer)","permalink":"/changelog/2022/03/09/2022-03-09-1.21.1 - Rapid Platform/1.21.1 - Rapid Platform"},"nextItem":{"title":"1.20.1 - Anonymous Forms","permalink":"/changelog/2022/01/15/2022-01-15-1.20.1 - Rapid Platform/1.20.1 - Rapid Platform"}},"content":"28/02/2022\\n\\n## Features\\n\\n### Prefill Data \\n\\nIt is now possible to create anonymous forms where field(s) in that anonymous form have data already in them. This data can be dynamically generated by workflow using expressions.  \\n\\n- Adds UI in workflow to configure prefill data \\n- Updated the Form Service to accept prefill data\\n\\n### Read Only Fields in Explorer\\n\\nIt is now possible through page design to set fields to read only, this will allow items to be created or modified externally, but when viewed from Explorer will present the field as Read Only \\n\\n## Improvements\\n\\n- Updated how JSON objects are parsed to Minilith"},{"id":"/2022/01/15/2022-01-15-1.20.1 - Rapid Platform/1.20.1 - Rapid Platform","metadata":{"permalink":"/changelog/2022/01/15/2022-01-15-1.20.1 - Rapid Platform/1.20.1 - Rapid Platform","source":"@site/blog/2022-01-15-1.20.1 - Rapid Platform/2022-01-15-1.20.1 - Rapid Platform.md","title":"1.20.1 - Anonymous Forms","description":"15/01/2022","date":"2022-01-15T00:00:00.000Z","tags":[{"inline":true,"label":"Changelog","permalink":"/changelog/tags/changelog"}],"readingTime":1.31,"hasTruncateMarker":false,"authors":[{"name":"Matt Franklin","title":"Documents","url":"https://github.com/MattFranklin-Rapid","email":"matthew@rapidplatform.com","imageURL":"https://github.com/MattFranklin-Rapid.png","key":"matt","page":null}],"frontMatter":{"authors":["matt"],"tags":["Changelog"]},"unlisted":false,"prevItem":{"title":"1.21.0 - Prefill Anonymous Form Data","permalink":"/changelog/2022/02/28/2022-02-28-1.21.0 - Rapid Platform/1.21.0 - Rapid Platform"},"nextItem":{"title":"1.20.0 - Workflow Usability","permalink":"/changelog/2021/12/01/2021-12-01-1.20.0 - Rapid Platform/1.20.0 - Rapid Platform"}},"content":"15/01/2022\\n\\n## Features\\n\\n### Anonymous Forms\\nYou can now create publicly accessible forms via Workflow. An anonymous form has a unique URL that you can send to a 3rd party to fill in. When they submit the form it will then complete the form task which allows your processes to wait until it is completed before moving on. Completed forms will then prevent a person from submitting that form again.\\n\\nYou can also create anonymous forms ad-hoc by creating a form task. This will generate the unique URL within the task automatically. Ad-hoc form tasks can also be flagged as persistent which will prevent the task from being completed on submission, so that you can send the same form to multiple people.\\n\\n## UI/UX Fixes\\n\\n- Added missing icons for some note types in the Activity Feed\\n- Prevented description icon being place in incorrect location in designer\\n- Removed choice specific configuration on non-choice fields\\n- Set the default title and icon for Adaptive Forms system list\\n\\n## Bug Fixes\\n\\n- Fixed dart-sass upgrade removing styles\\n- Prevented updating a diagram element affecting unrelated elements\\n- Fixed error on adding a template file to an embedded file definition\\n- Updated recursive task fetching to regard deleted tasks in the middle of the tree\\n- Fixed placeholder permissions not being configurable on inherited fields\\n- Fixed Linked To lists failing to fetch items via inherited multi-lookup fields\\n- Fixed call activity inputs failing to process Lodash templates\\n\\n## Improvements\\n\\n- Updated OpenAPI typings for subquery and computed fields\\n- Added API routes for view manipulation, see the docs for a breakdown"},{"id":"/2021/12/01/2021-12-01-1.20.0 - Rapid Platform/1.20.0 - Rapid Platform","metadata":{"permalink":"/changelog/2021/12/01/2021-12-01-1.20.0 - Rapid Platform/1.20.0 - Rapid Platform","source":"@site/blog/2021-12-01-1.20.0 - Rapid Platform/2021-12-01-1.20.0 - Rapid Platform.md","title":"1.20.0 - Workflow Usability","description":"1/12/2021","date":"2021-12-01T00:00:00.000Z","tags":[{"inline":true,"label":"Changelog","permalink":"/changelog/tags/changelog"}],"readingTime":0.32,"hasTruncateMarker":false,"authors":[{"name":"Matt Franklin","title":"Documents","url":"https://github.com/MattFranklin-Rapid","email":"matthew@rapidplatform.com","imageURL":"https://github.com/MattFranklin-Rapid.png","key":"matt","page":null}],"frontMatter":{"authors":["matt"],"tags":["Changelog"]},"unlisted":false,"prevItem":{"title":"1.20.1 - Anonymous Forms","permalink":"/changelog/2022/01/15/2022-01-15-1.20.1 - Rapid Platform/1.20.1 - Rapid Platform"},"nextItem":{"title":"1.19.12 - Hotfix","permalink":"/changelog/2021/11/26/2021-11-26-1.19.12 - Rapid Platform/1.19.12 - Rapid Platform"}},"content":"1/12/2021\\n\\n## UI/UX Fixes\\n\\n- Added tree view to workflow diagrams following the Parent column\\n- Removed blur effect on process diagrams\\n\\n## Bug Fixes\\n\\n- Fixed missing error messages on workflow results pane\\n- Fixed page crash on selecting a call activity process for v1 diagrams\\n- Resolved test plan diagrams failing to render\\n- Prevented uploaded erroneous file names crashing the bundles parser\\n- Prevented sequence flow"},{"id":"/2021/11/26/2021-11-26-1.19.12 - Rapid Platform/1.19.12 - Rapid Platform","metadata":{"permalink":"/changelog/2021/11/26/2021-11-26-1.19.12 - Rapid Platform/1.19.12 - Rapid Platform","source":"@site/blog/2021-11-26-1.19.12 - Rapid Platform/2021-11-26-1.19.12 - Rapid Platform.md","title":"1.19.12 - Hotfix","description":"26/11/2021","date":"2021-11-26T00:00:00.000Z","tags":[{"inline":true,"label":"Changelog","permalink":"/changelog/tags/changelog"}],"readingTime":0.32,"hasTruncateMarker":false,"authors":[{"name":"Matt Franklin","title":"Documents","url":"https://github.com/MattFranklin-Rapid","email":"matthew@rapidplatform.com","imageURL":"https://github.com/MattFranklin-Rapid.png","key":"matt","page":null}],"frontMatter":{"authors":["matt"],"tags":["Changelog"]},"unlisted":false,"prevItem":{"title":"1.20.0 - Workflow Usability","permalink":"/changelog/2021/12/01/2021-12-01-1.20.0 - Rapid Platform/1.20.0 - Rapid Platform"},"nextItem":{"title":"1.19.11 - General Usability","permalink":"/changelog/2021/11/25/2021-11-25-1.19.11 - Rapid Platform/1.19.11 - Rapid Platform"}},"content":"26/11/2021\\n\\n:::warning\\nThe previous release (1.19.11) caused a regression which caused a page crash in RAPID Explorer upon interacting with the Explorer nav menu when configured and interacted with in a particular way.\\n:::\\n\\n# Bug Fixes\\n\\n- Fixed regression where expanding an Explorer nav menu item will navigate to a page crash\\n- Fixed call activity inputs to regard expressions and all field types"},{"id":"/2021/11/25/2021-11-25-1.19.11 - Rapid Platform/1.19.11 - Rapid Platform","metadata":{"permalink":"/changelog/2021/11/25/2021-11-25-1.19.11 - Rapid Platform/1.19.11 - Rapid Platform","source":"@site/blog/2021-11-25-1.19.11 - Rapid Platform/2021-11-25-1.19.11 - Rapid Platform.md","title":"1.19.11 - General Usability","description":"25/11/2021","date":"2021-11-25T00:00:00.000Z","tags":[{"inline":true,"label":"Changelog","permalink":"/changelog/tags/changelog"}],"readingTime":0.95,"hasTruncateMarker":false,"authors":[{"name":"Matt Franklin","title":"Documents","url":"https://github.com/MattFranklin-Rapid","email":"matthew@rapidplatform.com","imageURL":"https://github.com/MattFranklin-Rapid.png","key":"matt","page":null}],"frontMatter":{"authors":["matt"],"tags":["Changelog"]},"unlisted":false,"prevItem":{"title":"1.19.12 - Hotfix","permalink":"/changelog/2021/11/26/2021-11-26-1.19.12 - Rapid Platform/1.19.12 - Rapid Platform"},"nextItem":{"title":"1.19.10 - Hotfix","permalink":"/changelog/2021/11/16/2021-11-16-1.19.10 - Rapid Platform/1.19.10 - Rapid Platform"}},"content":"25/11/2021\\n\\n## Bug Fixes\\n\\n- Fixed regression where a template file is unable to be selected in Workflow\\n- Fixed the recursive link items to respect if a parent item is deleted and then not recurse down in Explorer\\n- Fixed placeholder permissions not being applied correctly when an inherited user field is created\\n- Fixed a rare issue where inherited types may not be fetched in LinkedTo context if they are linked through a multi-lookup\\n\\n## UI/UX Fixes\\n\\n- Fixed minor UI issue with parallel gateways in Workflow\\n- Changed the diagram filtering in Workflow to be case insensitive\\n- Added Icons to update notes in the activity feed\\n- Prevented a tooltip hover covering the close action button on certain field types in Designer\\n- Removed a field configuration option for choice type from unrelated fields in the properties pane of a field in Designer\\n- Added icons and title for the Adaptive system list\\n\\n## Improvements\\n\\n- Added routes to allow users to create and access database views\\n- This change is fundamental to the Reporting experience which relies on giving the ability for users to create their own views which they can then use in their reporting"},{"id":"/2021/11/16/2021-11-16-1.19.10 - Rapid Platform/1.19.10 - Rapid Platform","metadata":{"permalink":"/changelog/2021/11/16/2021-11-16-1.19.10 - Rapid Platform/1.19.10 - Rapid Platform","source":"@site/blog/2021-11-16-1.19.10 - Rapid Platform/2021-11-16-1.19.10 - Rapid Platform.md","title":"1.19.10 - Hotfix","description":"16/11/2021","date":"2021-11-16T00:00:00.000Z","tags":[{"inline":true,"label":"Changelog","permalink":"/changelog/tags/changelog"}],"readingTime":0.36,"hasTruncateMarker":false,"authors":[{"name":"Matt Franklin","title":"Documents","url":"https://github.com/MattFranklin-Rapid","email":"matthew@rapidplatform.com","imageURL":"https://github.com/MattFranklin-Rapid.png","key":"matt","page":null}],"frontMatter":{"authors":["matt"],"tags":["Changelog"]},"unlisted":false,"prevItem":{"title":"1.19.11 - General Usability","permalink":"/changelog/2021/11/25/2021-11-25-1.19.11 - Rapid Platform/1.19.11 - Rapid Platform"},"nextItem":{"title":"1.19.9 - RAPID Reports","permalink":"/changelog/2021/11/16/2021-11-16-1.19.9 - Rapid Platform/1.19.9 - Rapid Platform"}},"content":"16/11/2021\\n\\n:::warning\\nThe previous release (1.19.9) caused a regression where upon fresh page loads , under rare circumstances would leave the local store (browser storage) in a corrupt state which would lead to a page crash. \\n:::\\n\\n## Bug Fixes\\n\\n- Fixed the inability to lock the All View from Designer if the view has not previously been modified\\n- Fixed a page crash when opening in items in rare cases after a refresh"},{"id":"/2021/11/16/2021-11-16-1.19.9 - Rapid Platform/1.19.9 - Rapid Platform","metadata":{"permalink":"/changelog/2021/11/16/2021-11-16-1.19.9 - Rapid Platform/1.19.9 - Rapid Platform","source":"@site/blog/2021-11-16-1.19.9 - Rapid Platform/2021-11-16-1.19.9 - Rapid Platform.md","title":"1.19.9 - RAPID Reports","description":"16/11/2021","date":"2021-11-16T00:00:00.000Z","tags":[{"inline":true,"label":"Changelog","permalink":"/changelog/tags/changelog"}],"readingTime":1.52,"hasTruncateMarker":false,"authors":[{"name":"Matt Franklin","title":"Documents","url":"https://github.com/MattFranklin-Rapid","email":"matthew@rapidplatform.com","imageURL":"https://github.com/MattFranklin-Rapid.png","key":"matt","page":null}],"frontMatter":{"authors":["matt"],"tags":["Changelog"]},"unlisted":false,"prevItem":{"title":"1.19.10 - Hotfix","permalink":"/changelog/2021/11/16/2021-11-16-1.19.10 - Rapid Platform/1.19.10 - Rapid Platform"},"nextItem":{"title":"1.19.8 - Email Attachments","permalink":"/changelog/2021/10/20/2021-10-20-1.19.8 - Rapid Platform/1.19.8 - Rapid Platform"}},"content":"16/11/2021\\n\\n## Features\\n\\n### List support for Action Buttons\\n\\nYou can now opt for Action Buttons to be presented on items and/or lists. When triggered from a list an action will be made for each selected item on that list.\\n\\nIn addition, you can now configure a Form to request additional information when pressing an Action Button. These are pulled from your list of Forms in the new Forms Experience and will submit the collected information along with each request.\\n\\nPlease note that in list scenarios only one form is collected for all selected items.\\n\\n### RAPID Forms (Preview)\\n\\nBuilding on top of the current Form builder in Designer, Forms empowers you to build nice looking input forms with control over styling and support for making more than one kind of item at once. \\nCustom layout options now include support for \\n\\n- sections and sub-sections\\n- both horizontal and vertical layouts, including multi-column forms\\n- Linkert display for questionnaires\\n- and conditional visibility based on form content  \\n\\nRAPID Forms are broken into two parts:\\n\\n1) Form Designer - Build and design your forms with custom layouts\\n2) Forms - Browse the forms on your site and fill them in\\n\\n### RAPID Reports (Preview)\\n\\nReports enables the creation of PowerBI reports based on your RAPID data straight in your web browser. This is an extension of PowerBI edit mode in Explorer.\\n\\nIn addition to helping show what reports are currently on the site, you can also create Dashboards that organise reports and views into handy groups to make keeping track of your site data easier than ever.\\n\\n## UI/UX Fixes\\n\\n- Added state preservation to pages in Explorer\\n\\n## Bug Fixes\\n\\n- Prevented forms breaking when trying to render a deleted column\\n- Prevented embedded file components creating their configured sub folder twice\\n\\n## Improvements\\n\\n- Updated error handling in SDK to have friendlier error messages"},{"id":"/2021/10/20/2021-10-20-1.19.8 - Rapid Platform/1.19.8 - Rapid Platform","metadata":{"permalink":"/changelog/2021/10/20/2021-10-20-1.19.8 - Rapid Platform/1.19.8 - Rapid Platform","source":"@site/blog/2021-10-20-1.19.8 - Rapid Platform/2021-10-20-1.19.8 - Rapid Platform.md","title":"1.19.8 - Email Attachments","description":"20/10/2021","date":"2021-10-20T00:00:00.000Z","tags":[{"inline":true,"label":"Changelog","permalink":"/changelog/tags/changelog"}],"readingTime":0.57,"hasTruncateMarker":false,"authors":[{"name":"Matt Franklin","title":"Documents","url":"https://github.com/MattFranklin-Rapid","email":"matthew@rapidplatform.com","imageURL":"https://github.com/MattFranklin-Rapid.png","key":"matt","page":null}],"frontMatter":{"authors":["matt"],"tags":["Changelog"]},"unlisted":false,"prevItem":{"title":"1.19.9 - RAPID Reports","permalink":"/changelog/2021/11/16/2021-11-16-1.19.9 - Rapid Platform/1.19.9 - Rapid Platform"},"nextItem":{"title":"1.19.6 - Embedded Form Rework","permalink":"/changelog/2021/10/12/2021-10-12-1.19.6 - Rapid Platform/1.19.6 - Rapid Platform"}},"content":"20/10/2021\\n\\n## Features\\n\\n### Attachments for Email Service Tasks\\n\\nAdding extra functionality to the current email service task for workflow, This allows process writers to add one or more sharepoint drive Item ID\'s and Folder ID\'s to the configuration of an email service task, these can be dynamically generated using Lodash expressions. Upon execution of that email service task, the email will be sent with the attachments specified. \\n\\n## UI/UX\\n\\n- Added page state; re-opening an item or page in Explorer will retain the previously opened context\\n\\n## Bug Fixes\\n\\n- Fixed double folders being created when adding files to an embedded file component under certain circumstances\\n- Made embedded forms more resilient by validating out deleted columns"},{"id":"/2021/10/12/2021-10-12-1.19.6 - Rapid Platform/1.19.6 - Rapid Platform","metadata":{"permalink":"/changelog/2021/10/12/2021-10-12-1.19.6 - Rapid Platform/1.19.6 - Rapid Platform","source":"@site/blog/2021-10-12-1.19.6 - Rapid Platform/2021-10-12-1.19.6 - Rapid Platform.md","title":"1.19.6 - Embedded Form Rework","description":"12/10/2021","date":"2021-10-12T00:00:00.000Z","tags":[{"inline":true,"label":"Changelog","permalink":"/changelog/tags/changelog"}],"readingTime":0.34,"hasTruncateMarker":false,"authors":[{"name":"Matt Franklin","title":"Documents","url":"https://github.com/MattFranklin-Rapid","email":"matthew@rapidplatform.com","imageURL":"https://github.com/MattFranklin-Rapid.png","key":"matt","page":null}],"frontMatter":{"authors":["matt"],"tags":["Changelog"]},"unlisted":false,"prevItem":{"title":"1.19.8 - Email Attachments","permalink":"/changelog/2021/10/20/2021-10-20-1.19.8 - Rapid Platform/1.19.8 - Rapid Platform"},"nextItem":{"title":"1.19.5 - Item Action Buttons","permalink":"/changelog/2021/10/11/2021-10-11-1.19.5 - Rapid Platform/1.19.5 - Rapid Platform"}},"content":"12/10/2021\\n\\n## UI/UX Fixes\\n\\n- Fixed embedded form data loading on item load\\n\\n## Bug Fixes\\n\\n- Fixed a page crash when viewing process diagrams with null versions\\n- Fixed the ability to set the value of dates in embedded forms to null\\n- Fixed corruption to service tasks configuration when changing service task types on the same element\\n\\n## Improvements\\n\\n- Embedded forms in Explorer are now rendered as adaptive forms"},{"id":"/2021/10/11/2021-10-11-1.19.5 - Rapid Platform/1.19.5 - Rapid Platform","metadata":{"permalink":"/changelog/2021/10/11/2021-10-11-1.19.5 - Rapid Platform/1.19.5 - Rapid Platform","source":"@site/blog/2021-10-11-1.19.5 - Rapid Platform/2021-10-11-1.19.5 - Rapid Platform.md","title":"1.19.5 - Item Action Buttons","description":"11/10/2021","date":"2021-10-11T00:00:00.000Z","tags":[{"inline":true,"label":"Changelog","permalink":"/changelog/tags/changelog"}],"readingTime":4.12,"hasTruncateMarker":false,"authors":[{"name":"Matt Franklin","title":"Documents","url":"https://github.com/MattFranklin-Rapid","email":"matthew@rapidplatform.com","imageURL":"https://github.com/MattFranklin-Rapid.png","key":"matt","page":null}],"frontMatter":{"authors":["matt"],"tags":["Changelog"]},"unlisted":false,"prevItem":{"title":"1.19.6 - Embedded Form Rework","permalink":"/changelog/2021/10/12/2021-10-12-1.19.6 - Rapid Platform/1.19.6 - Rapid Platform"}},"content":"11/10/2021\\n\\n## Features\\n\\n### Action Buttons on Items\\n\\nIt is now possible to configure custom action buttons on items in the command bar. These actions include existing menu support to open pages and custom links as well as to trigger custom server endpoints (such as Flows).\\n\\nFor example, you can now configure a custom Delete action that triggers a Flow which can then delete both the clicked item and all linked items to make \u2018bulk\u2019 administration easier.\\nFor support in creating and designing your custom actions please contact your representative.\\n\\n### Workflow v2 Input Support\\n\\nWorkflow v2 Diagrams can now support Inputs and Outputs both for manually started processes as well as Call Activities. These inputs can be referenced within processes using both adaptive expressions and directly on conditional gateways.\\n\\nThis allows for the creation of processes that can understand the context they are being triggered from without needing to use signal events. As you start building input driven processes, try executing a process manually form within Explorer for that extra \u2018on demand\u2019 convenience.\\n\\n### Workflow v2 Test Plans\\n\\nFor those wanting to ensure their processes keep doing what they expect you can now create test plans for v2 diagrams. Test plans run in a sandbox environment that will not affect anything outside the test. Tests cannot trigger webhooks, create or edit items and cause any other permanent side-effect. \\n\\nWhen writing a test plan you provide what external information you expect to occur within the test letting you test different scenarios quickly and easily. Test plans are saved making re-testing changes to existing workflows quicker and easier.\\n\\n### Bundles v2\\n\\nBundle support has been overhauled to now support zipped files, which can include table, menu and PowerBI report items to be imported. Extracting a bundle will now generate in the new format. The library of existing bundles have also been updated to conform to the new structure.\\n\\n## UI/UX Fixes\\n\\n- Updated advanced pages in Designer to conform to same style\\n- Updated signal condition hint text to be accurate for Workflow v2\\n- Removed blank option for column types\\n- Added word counter on table name creation (limit 50)\\n- Added ability to configure time when creating a manual reminder\\n- Added configuration to display a choice field as a radio button in Designer\\n- Updated delete button in Workflow to use bulk delete action\\n- Removed un-used type configuration on Call Activity inputs\\n- Added ability to choose which sub-types appear on specific data tables\\n- Improved render speed of menu configuration page for sites with large numbers of users\\n- Added array handling to DocX template actions in Workflow v1\\n- Improved error messages on PowerBI upload\\n- Upgraded embedded form components to use new SDK components\\n- Improved styling when viewing process runs for Workflow v1 and v2 in Explorer\\n- Fixed embedded date fields with erroneous dates showing NaN for all options\\n- Updated spelling on table configuration warning message\\n\\n## Bug Fixes\\n\\n- Fixed search request for Org Wide emails fetching too many emails\\n- Fixed process inputs with null values failing to generate\\n- Fixed call activities failing to navigate on click in Explorer\\n- Fixed white on white text in menu configuration panel\\n- Ensured errors on process run items in Workflow v2 apply visually\\n- Prevented changing service task type failing to clean up after itself\\n- Fixed opening workflow results panel completing a selected task\\n- Prevented page crash in Explorer when manually executing a process with lookup inputs\\n- Fixed inputs failing to display in workflow results panel\\n- Prevented bulk delete from trying to delete 0 items\\n- Prevented page crash when fetching empty diagrams\\n- Fixed lookup inputs in processes failing to auto-populate when triggered in Explorer\\n- Prevented multi-lookup columns being applied as title columns on tables\\n- Stopped endless loop when trying to delete an already deleted item\\n- Fixed saving a diagram preventing further edits to fail to save\\n- Fixed lookup item creation failing to create sub-types\\n- Ensured task notifications are generated when the new assigned to User is the last editor\\n- Prevented editing Principals directly through the API\\n- Updated Get Item service task to regard expressions in Workflow v2\\n- Fixed embedded form configuration with universal links failing to create those links in Workflow v2\\n- Ensured expressions in Workflow v2 only regard the last item in looping scenarios\\n- Fixed emailing a single file from the File Browser entering an infinite loop\\n- Prevented double fetching of items in linked context\\n- Fixed bulk deletion failing to update inherited tables\\n- Prevented rules on conditional gateway sequence flows marked as default from being calculated\\n- Updated actions in menu sidebar contexts to not try and post a missing item profile  \\n\\n## Improvements\\n\\n- Added principal display and UPN support to network requests\\n- Implemented multi-site context management into SDK\\n- Added controls to disable AutoFetch in ManagedViewContext in SDK\\n- Added typings for Workflow Test Plans to Data-Model\\n- Upgraded table deletion to also include shadow views\\n- Added expression support for embedded form content into Workflow v2\\n- Added unique embedded form IDs in Workflow"}]}}')}}]);